import type { GuidedLab } from '../../../quizBank';

export const GUIDED: Record<string, GuidedLab> = {"labex-sklearn-label-propagation-learning":{"intro":"In this lab, we will learn how to use LabelPropagation to learn the labels of unknown samples from labeled samples. We will generate a dataset containing two concentric circles and assign labels to each sample. Then, we will use LabelPropagation to learn the labels of the unknown samples.","steps":[{"title":"Import Required Libraries","body":["We start by importing the required libraries for this lab."],"code":[{"lang":"python","text":"import numpy as np\nfrom sklearn.datasets import make_circles\nimport matplotlib.pyplot as plt\nfrom sklearn.semi_supervised import LabelSpreading"}]},{"title":"Generate Dataset","body":["Next, we generate a dataset containing two concentric circles using make_circles. We assign labels to the dataset such that all samples are unknown except for two samples which belong to the outer and inner circles respectively."],"code":[{"lang":"python","text":"n_samples = 200\nX, y = make_circles(n_samples=n_samples, shuffle=False)\nouter, inner = 0, 1\nlabels = np.full(n_samples, -1.0)\nlabels[0] = outer\nlabels[-1] = inner"}]},{"title":"Plot Raw Data","body":["We plot the raw data to visualize the circles and labels."],"code":[{"lang":"python","text":"plt.figure(figsize=(4, 4))\nplt.scatter(\n    X[labels == outer, 0],\n    X[labels == outer, 1],\n    color=\"navy\",\n    marker=\"s\",\n    lw=0,\n    label=\"outer labeled\",\n    s=10,\n)\nplt.scatter(\n    X[labels == inner, 0],\n    X[labels == inner, 1],\n    color=\"c\",\n    marker=\"s\",\n    lw=0,\n    label=\"inner labeled\",\n    s=10,\n)\nplt.scatter(\n    X[labels == -1, 0],\n    X[labels == -1, 1],\n    color=\"darkorange\",\n    marker=\".\",\n    label=\"unlabeled\",\n)\nplt.legend(scatterpoints=1, shadow=False, loc=\"center\")\n_ = plt.title(\"Raw data (2 classes=outer and inner)\")"}]},{"title":"Learn Labels with LabelPropagation","body":["Learn Labels with LabelPropagation","We use LabelSpreading to learn the labels of the unknown samples."],"code":[{"lang":"python","text":"label_spread = LabelSpreading(kernel=\"knn\", alpha=0.8)\nlabel_spread.fit(X, labels)"}]},{"title":"Plot Learned Labels","body":["Finally, we plot the learned labels to visualize the accuracy of LabelPropagation."],"code":[{"lang":"python","text":"output_labels = label_spread.transduction_\noutput_label_array = np.asarray(output_labels)\nouter_numbers = np.where(output_label_array == outer)[0]\ninner_numbers = np.where(output_label_array == inner)[0]\n\nplt.figure(figsize=(4, 4))\nplt.scatter(\n    X[outer_numbers, 0],\n    X[outer_numbers, 1],\n    color=\"navy\",\n    marker=\"s\",\n    lw=0,\n    s=10,\n    label=\"outer learned\",\n)\nplt.scatter(\n    X[inner_numbers, 0],\n    X[inner_numbers, 1],\n    color=\"c\",\n    marker=\"s\",\n    lw=0,\n    s=10,\n    label=\"inner learned\",\n)\nplt.legend(scatterpoints=1, shadow=False, loc=\"center\")\nplt.title(\"Labels learned with Label Spreading (KNN)\")\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"output_labels = label_spread.transduction_\noutput_label_array = np.asarray(output_labels)\nouter_numbers = np.where(output_label_array == outer)[0]\ninner_numbers = np.where(output_label_array == inner)[0]\n\nplt.figure(figsize=(4, 4))\nplt.scatter(\n    X[outer_numbers, 0],\n    X[outer_numbers, 1],\n    color=\"navy\",\n    marker=\"s\",\n    lw=0,\n    s=10,\n    label=\"outer learned\",\n)\nplt.scatter(\n    X[inner_numbers, 0],\n    X[inner_numbers, 1],\n    color=\"c\",\n    marker=\"s\",\n    lw=0,\n    s=10,\n    label=\"inner learned\",\n)\nplt.legend(scatterpoints=1, shadow=False, loc=\"center\")\nplt.title(\"Labels learned with Label Spreading (KNN)\")\nplt.show()"}],"source":"scikit-learn/scikit-learn · BSD 3-Clause"},"labex-sklearn-sparse-signal-regression-with-l1-based-model":{"intro":"In this lab, we will demonstrate how to use L1-based regression models to deal with high-dimensional and sparse signals. In particular, we will compare three popular L1-based models: Lasso, Automatic Relevance Determination (ARD), and ElasticNet. We will use a synthetic dataset to illustrate the performance of these models in terms of fitting time, R2 score, and sparsity of estimated coefficients.","steps":[{"title":"Generate Synthetic Dataset","body":["First, we generate a dataset where the number of samples is lower than the total number of features. This leads to an underdetermined system, i.e., the solution is not unique, and we cannot apply an ordinary least squares by itself. Regularization introduces a penalty term to the objective function, which modifies the optimization problem and can help alleviate the underdetermined nature of the system. We will generate a target y that is a linear combination with alternating signs of sinusoidal signals. Only the 10 lowest out of the 100 frequencies in X are used to generate y, while the rest of the features are not informative.…"],"code":[{"lang":"python","text":"import numpy as np\n\nrng = np.random.RandomState(0)\nn_samples, n_features, n_informative = 50, 100, 10\ntime_step = np.linspace(-2, 2, n_samples)\nfreqs = 2 * np.pi * np.sort(rng.rand(n_features)) / 0.01\nX = np.zeros((n_samples, n_features))\n\nfor i in range(n_features):\n    X[:, i] = np.sin(freqs[i] * time_step)\n\nidx = np.arange(n_features)\ntrue_coef = (-1) ** idx * np.exp(-idx / 10)\ntrue_coef[n_informative:] = 0  # sparsify coef\ny = np.dot(X, true_coef)\n\n# introduce random phase using numpy.random.random_sample\n# add some gaussian noise using numpy.random.normal\nfor i in range(n_features):\n    X[:, i] = np.sin(freqs[i] * time_step + 2 * (rng.random_sample() - 0.5))\n    X[:, i] += 0.2 * rng.normal(0, 1, n_samples)\n\ny += 0.2 * rng.normal(0, 1, n_samples)\n\n# split the data into train and test sets using train_test_split from sklearn\nfrom sklearn.model_selection import train_test_split\nX_train, X_test, y_train, y_test = train_test_split(X, y, test_size=0.5, shuffle=False)"}]},{"title":"Lasso","body":["In this step, we will demonstrate how to use Lasso regression model to estimate the sparse coefficients of the dataset. We will use a fixed value of the regularization parameter alpha. In practice, the optimal parameter alpha should be selected by passing a TimeSeriesSplit cross-validation strategy to a LassoCV. To keep the example simple and fast to execute, we directly set the optimal value for alpha here."],"code":[{"lang":"python","text":"from sklearn.linear_model import Lasso\nfrom sklearn.metrics import r2_score\nfrom time import time\n\nt0 = time()\nlasso = Lasso(alpha=0.14).fit(X_train, y_train)\nprint(f\"Lasso fit done in {(time() - t0):.3f}s\")\n\ny_pred_lasso = lasso.predict(X_test)\nr2_score_lasso = r2_score(y_test, y_pred_lasso)\nprint(f\"Lasso r^2 on test data : {r2_score_lasso:.3f}\")"}]},{"title":"Automatic Relevance Determination (ARD)","body":["Automatic Relevance Determination (ARD)","An ARD regression is the Bayesian version of the Lasso. It can produce interval estimates for all of the parameters, including the error variance, if required. It is a suitable option when the signals have Gaussian noise."],"code":[{"lang":"python","text":"from sklearn.linear_model import ARDRegression\n\nt0 = time()\nard = ARDRegression().fit(X_train, y_train)\nprint(f\"ARD fit done in {(time() - t0):.3f}s\")\n\ny_pred_ard = ard.predict(X_test)\nr2_score_ard = r2_score(y_test, y_pred_ard)\nprint(f\"ARD r^2 on test data : {r2_score_ard:.3f}\")"}]},{"title":"ElasticNet","body":["ElasticNet is a middle ground between Lasso and Ridge regression, as it combines an L1 and an L2-penalty. The amount of regularization is controlled by the two hyperparameters l1_ratio and alpha. For l1_ratio = 0 the penalty is pure L2 and the model is equivalent to a Ridge regression. Similarly, l1_ratio = 1 is a pure L1 penalty and the model is equivalent to a Lasso regression. For 0 < l1_ratio < 1, the penalty is a combination of L1 and L2."],"code":[{"lang":"python","text":"from sklearn.linear_model import ElasticNet\n\nt0 = time()\nenet = ElasticNet(alpha=0.08, l1_ratio=0.5).fit(X_train, y_train)\nprint(f\"ElasticNet fit done in {(time() - t0):.3f}s\")\n\ny_pred_enet = enet.predict(X_test)\nr2_score_enet = r2_score(y_test, y_pred_enet)\nprint(f\"ElasticNet r^2 on test data : {r2_score_enet:.3f}\")"}]},{"title":"Plot and Analysis of the Results","body":["Plot and Analysis of the Results","In this step, we use a heatmap to visualize the sparsity of the true and estimated coefficients of the respective linear models."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport seaborn as sns\nimport pandas as pd\nfrom matplotlib.colors import SymLogNorm\n\ndf = pd.DataFrame(\n    {\n        \"True coefficients\": true_coef,\n        \"Lasso\": lasso.coef_,\n        \"ARDRegression\": ard.coef_,\n        \"ElasticNet\": enet.coef_,\n    }\n)\n\nplt.figure(figsize=(10, 6))\nax = sns.heatmap(\n    df.T,\n    norm=SymLogNorm(linthresh=10e-4, vmin=-1, vmax=1),\n    cbar_kws={\"label\": \"coefficients' values\"},\n    cmap=\"seismic_r\",\n)\nplt.ylabel(\"linear model\")\nplt.xlabel(\"coefficients\")\nplt.title(\n    f\"Models' coefficients\\nLasso $R^2$: {r2_score_lasso:.3f}, \"\n    f\"ARD $R^2$: {r2_score_ard:.3f}, \"\n    f\"ElasticNet $R^2$: {r2_score_enet:.3f}\"\n)\nplt.tight_layout()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"import matplotlib.pyplot as plt\nimport seaborn as sns\nimport pandas as pd\nfrom matplotlib.colors import SymLogNorm\n\ndf = pd.DataFrame(\n    {\n        \"True coefficients\": true_coef,\n        \"Lasso\": lasso.coef_,\n        \"ARDRegression\": ard.coef_,\n        \"ElasticNet\": enet.coef_,\n    }\n)\n\nplt.figure(figsize=(10, 6))\nax = sns.heatmap(\n    df.T,\n    norm=SymLogNorm(linthresh=10e-4, vmin=-1, vmax=1),\n    cbar_kws={\"label\": \"coefficients' values\"},\n    cmap=\"seismic_r\",\n)\nplt.ylabel(\"linear model\")\nplt.xlabel(\"coefficients\")\nplt.title(\n    f\"Models' coefficients\\nLasso $R^2$: {r2_score_lasso:.3f}, \"\n    f\"ARD $R^2$: {r2_score_ard:.3f}, \"\n    f\"ElasticNet $R^2$: {r2_score_enet:.3f}\"\n)\nplt.tight_layout()"}],"source":"scikit-learn/scikit-learn · BSD 3-Clause"},"labex-sklearn-lasso-and-elastic-net":{"intro":"In this tutorial, we will learn about Lasso and Elastic Net, which are techniques used for linear regression and implemented using a coordinate descent. We will learn how to compute regularization paths using the Lasso and Elastic Net, and how to display the results using matplotlib.","steps":[{"title":"Load the Dataset","body":["In this step, we will load the diabetes dataset from scikit-learn library and standardize the data."],"code":[{"lang":"python","text":"from sklearn import datasets\n\n# Load the diabetes dataset\nX, y = datasets.load_diabetes(return_X_y=True)\n\n# Standardize data\nX /= X.std(axis=0)"}]},{"title":"Compute Regularization Path Using Lasso","body":["Compute Regularization Path Using Lasso","In this step, we will compute the regularization path using the Lasso technique and display the results using matplotlib."],"code":[{"lang":"python","text":"from sklearn.linear_model import lasso_path\nimport numpy as np\nimport matplotlib.pyplot as plt\n\n# Set the value of eps\neps = 5e-3\n\n# Compute regularization path using the Lasso\nalphas_lasso, coefs_lasso, _ = lasso_path(X, y, eps=eps)\n\n# Display the results using matplotlib\nplt.figure(1)\ncolors = cycle([\"b\", \"r\", \"g\", \"c\", \"k\"])\nneg_log_alphas_lasso = -np.log10(alphas_lasso)\nfor coef_l, c in zip(coefs_lasso, colors):\n    l1 = plt.plot(neg_log_alphas_lasso, coef_l, c=c)\n\nplt.xlabel(\"-Log(alpha)\")\nplt.ylabel(\"coefficients\")\nplt.title(\"Lasso Path\")\nplt.axis(\"tight\")\nplt.show()"}]},{"title":"Compute Regularization Path Using Positive Lasso","body":["Compute Regularization Path Using Positive Lasso","In this step, we will compute the regularization path using the positive Lasso technique and display the results using matplotlib."],"code":[{"lang":"python","text":"# Compute regularization path using the positive Lasso\nalphas_positive_lasso, coefs_positive_lasso, _ = lasso_path(X, y, eps=eps, positive=True)\n\n# Display the results using matplotlib\nplt.figure(2)\nneg_log_alphas_positive_lasso = -np.log10(alphas_positive_lasso)\nfor coef_l, coef_pl, c in zip(coefs_lasso, coefs_positive_lasso, colors):\n    l1 = plt.plot(neg_log_alphas_lasso, coef_l, c=c)\n    l2 = plt.plot(neg_log_alphas_positive_lasso, coef_pl, linestyle=\"--\", c=c)\n\nplt.xlabel(\"-Log(alpha)\")\nplt.ylabel(\"coefficients\")\nplt.title(\"Lasso and Positive Lasso\")\nplt.legend((l1[-1], l2[-1]), (\"Lasso\", \"Positive Lasso\"), loc=\"lower left\")\nplt.axis(\"tight\")\nplt.show()"}]},{"title":"Compute Regularization Path Using Elastic Net","body":["Compute Regularization Path Using Elastic Net","In this step, we will compute the regularization path using the Elastic Net technique and display the results using matplotlib."],"code":[{"lang":"python","text":"from sklearn.linear_model import enet_path\n\n# Compute regularization path using the Elastic Net\nalphas_enet, coefs_enet, _ = enet_path(X, y, eps=eps, l1_ratio=0.8)\n\n# Display the results using matplotlib\nplt.figure(3)\nneg_log_alphas_enet = -np.log10(alphas_enet)\nfor coef_e, c in zip(coefs_enet, colors):\n    l1 = plt.plot(neg_log_alphas_enet, coef_e, c=c)\n\nplt.xlabel(\"-Log(alpha)\")\nplt.ylabel(\"coefficients\")\nplt.title(\"Elastic Net Path\")\nplt.axis(\"tight\")\nplt.show()"}]},{"title":"Compute Regularization Path Using Positive Elastic Net","body":["Compute Regularization Path Using Positive Elastic Net","In this step, we will compute the regularization path using the positive Elastic Net technique and display the results using matplotlib."],"code":[{"lang":"python","text":"# Compute regularization path using the positive Elastic Net\nalphas_positive_enet, coefs_positive_enet, _ = enet_path(X, y, eps=eps, l1_ratio=0.8, positive=True)\n\n# Display the results using matplotlib\nplt.figure(4)\nneg_log_alphas_positive_enet = -np.log10(alphas_positive_enet)\nfor coef_e, coef_pe, c in zip(coefs_enet, coefs_positive_enet, colors):\n    l1 = plt.plot(neg_log_alphas_enet, coef_e, c=c)\n    l2 = plt.plot(neg_log_alphas_positive_enet, coef_pe, linestyle=\"--\", c=c)\n\nplt.xlabel(\"-Log(alpha)\")\nplt.ylabel(\"coefficients\")\nplt.title(\"Elastic Net and Positive Elastic Net\")\nplt.legend((l1[-1], l2[-1]), (\"Elastic Net\", \"Positive Elastic Net\"), loc=\"lower left\")\nplt.axis(\"tight\")\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"# Compute regularization path using the positive Elastic Net\nalphas_positive_enet, coefs_positive_enet, _ = enet_path(X, y, eps=eps, l1_ratio=0.8, positive=True)\n\n# Display the results using matplotlib\nplt.figure(4)\nneg_log_alphas_positive_enet = -np.log10(alphas_positive_enet)\nfor coef_e, coef_pe, c in zip(coefs_enet, coefs_positive_enet, colors):\n    l1 = plt.plot(neg_log_alphas_enet, coef_e, c=c)\n    l2 = plt.plot(neg_log_alphas_positive_enet, coef_pe, linestyle=\"--\", c=c)\n\nplt.xlabel(\"-Log(alpha)\")\nplt.ylabel(\"coefficients\")\nplt.title(\"Elastic Net and Positive Elastic Net\")\nplt.legend((l1[-1], l2[-1]), (\"Elastic Net\", \"Positive Elastic Net\"), loc=\"lower left\")\nplt.axis(\"tight\")\nplt.show()"}],"source":"scikit-learn/scikit-learn · BSD 3-Clause"},"labex-sklearn-scikit-learn-lasso-regression":{"intro":"This lab demonstrates the use of Scikit-learn's Lasso regression algorithm on dense and sparse data. The Lasso algorithm is a linear regression method that adds a penalty to the regression coefficients. This penalty encourages the model to produce sparse coefficients. The Lasso algorithm is useful in situations where the number of features is large compared to the number of samples.","steps":[{"title":"Import Libraries","body":["We begin by importing the necessary libraries. We need Scikit-learn, NumPy, and SciPy."],"code":[{"lang":"python","text":"from time import time\nfrom scipy import sparse\nfrom scipy import linalg\nfrom sklearn.datasets import make_regression\nfrom sklearn.linear_model import Lasso"}]},{"title":"Generate Dense Data","body":["Next, we generate some dense data that we will use for the Lasso regression. We use Scikit-learn's make_regression function to generate 200 samples with 5000 features."],"code":[{"lang":"python","text":"X, y = make_regression(n_samples=200, n_features=5000, random_state=0)"}]},{"title":"Train Lasso on Dense Data","body":["Now we train two Lasso regression models, one on the dense data and one on the sparse data. We set the alpha parameter to 1 and the maximum number of iterations to 1000."],"code":[{"lang":"python","text":"alpha = 1\nsparse_lasso = Lasso(alpha=alpha, fit_intercept=False, max_iter=1000)\ndense_lasso = Lasso(alpha=alpha, fit_intercept=False, max_iter=1000)"}]},{"title":"Fit Lasso to Dense Data","body":["We fit the Lasso regression models to the dense data using Scikit-learn's fit function. We also time the fitting process and print the time for each Lasso model."],"code":[{"lang":"python","text":"t0 = time()\nsparse_lasso.fit(X_sp, y)\nprint(f\"Sparse Lasso done in {(time() - t0):.3f}s\")\n\nt0 = time()\ndense_lasso.fit(X, y)\nprint(f\"Dense Lasso done in {(time() - t0):.3f}s\")"}]},{"title":"Compare Coefficients of Dense Lasso and Sparse Lasso","body":["Compare Coefficients of Dense Lasso and Sparse Lasso","We compare the coefficients of the dense Lasso model and the sparse Lasso model to ensure that they are producing the same results. We compute the Euclidean norm of the difference between the coefficients."],"code":[{"lang":"python","text":"coeff_diff = linalg.norm(sparse_lasso.coef_ - dense_lasso.coef_)\nprint(f\"Distance between coefficients : {coeff_diff:.2e}\")"}]},{"title":"Generate Sparse Data","body":["Next, we generate some sparse data that we will use for the Lasso regression. We copy the dense data from the previous step and replace all values less than 2.5 with 0. We also convert the sparse data to Scipy's Compressed Sparse Column format."],"code":[{"lang":"python","text":"Xs = X.copy()\nXs[Xs < 2.5] = 0.0\nXs_sp = sparse.coo_matrix(Xs)\nXs_sp = Xs_sp.tocsc()"}]},{"title":"Train Lasso on Sparse Data","body":["Now we train two Lasso regression models, one on the dense data and one on the sparse data. We set the alpha parameter to 0.1 and the maximum number of iterations to 10000."],"code":[{"lang":"python","text":"alpha = 0.1\nsparse_lasso = Lasso(alpha=alpha, fit_intercept=False, max_iter=10000)\ndense_lasso = Lasso(alpha=alpha, fit_intercept=False, max_iter=10000)"}]},{"title":"Fit Lasso to Sparse Data","body":["We fit the Lasso regression models to the sparse data using Scikit-learn's fit function. We also time the fitting process and print the time for each Lasso model."],"code":[{"lang":"python","text":"t0 = time()\nsparse_lasso.fit(Xs_sp, y)\nprint(f\"Sparse Lasso done in {(time() - t0):.3f}s\")\n\nt0 = time()\ndense_lasso.fit(Xs, y)\nprint(f\"Dense Lasso done in  {(time() - t0):.3f}s\")"}]}],"commands":[],"reference":[{"path":"reference.py","text":"coeff_diff = linalg.norm(sparse_lasso.coef_ - dense_lasso.coef_)\nprint(f\"Distance between coefficients : {coeff_diff:.2e}\")"}],"source":"scikit-learn/scikit-learn · BSD 3-Clause"},"labex-sklearn-scikit-learn-lasso-path":{"intro":"This lab will demonstrate how to compute the Lasso Path along the regularization parameter using the LARS algorithm on the diabetes dataset. The Lasso Path is a plot of the coefficients of a linear model as the L1 regularization parameter is increased. Each color represents a different feature of the coefficient vector, and this is displayed as a function of the regularization parameter.","steps":[{"title":"Load Data","body":["The first step is to load the diabetes dataset from Scikit-Learn."],"code":[{"lang":"python","text":"from sklearn import datasets\n\nX, y = datasets.load_diabetes(return_X_y=True)"}]},{"title":"Compute Lasso Path","body":["Next, we compute the Lasso Path using the LARS algorithm. The lars_path function from Scikit-Learn's linear_model module is used to compute the Lasso Path. The function takes the input features, target variable, and method as parameters. In this case, we use the \"lasso\" method for L1 regularization."],"code":[{"lang":"python","text":"from sklearn import linear_model\n\n_, _, coefs = linear_model.lars_path(X, y, method=\"lasso\", verbose=True)"}]},{"title":"Plot Lasso Path","body":["After computing the Lasso Path, we plot the results. The coefficients for each feature are plotted as a function of the regularization parameter."],"code":[{"lang":"python","text":"import numpy as np\nimport matplotlib.pyplot as plt\n\nxx = np.sum(np.abs(coefs.T), axis=1)\nxx /= xx[-1]\n\nplt.plot(xx, coefs.T)\nymin, ymax = plt.ylim()\nplt.vlines(xx, ymin, ymax, linestyle=\"dashed\")\nplt.xlabel(\"|coef| / max|coef|\")\nplt.ylabel(\"Coefficients\")\nplt.title(\"LASSO Path\")\nplt.axis(\"tight\")\nplt.show()"}]},{"title":"Interpret Results","body":["The resulting plot shows the Lasso Path for the diabetes dataset. Each color represents a different feature of the coefficient vector, and this is displayed as a function of the regularization parameter. As the regularization parameter increases, the coefficients for some features shrink towards zero, indicating that those features are less important for predicting the target variable."],"code":[]}],"commands":[],"reference":[],"source":"scikit-learn/scikit-learn · BSD 3-Clause"},"labex-sklearn-lasso-model-selection":{"intro":"In this lab, we will learn how to use LassoLarsIC estimator to select the best Lasso model using AIC and BIC criteria. We will use the diabetes dataset from scikit-learn.","steps":[{"title":"Load the Data","body":["We will load the diabetes dataset from scikit-learn using the load_diabetes method."],"code":[{"lang":"python","text":"from sklearn.datasets import load_diabetes\n\nX, y = load_diabetes(return_X_y=True, as_frame=True)"}]},{"title":"Preprocess the Data","body":["We will scale the dataset using the StandardScaler method and fit the LassoLarsIC estimator with AIC criterion."],"code":[{"lang":"python","text":"from sklearn.preprocessing import StandardScaler\nfrom sklearn.linear_model import LassoLarsIC\nfrom sklearn.pipeline import make_pipeline\n\nlasso_lars_ic = make_pipeline(StandardScaler(), LassoLarsIC(criterion=\"aic\")).fit(X, y)"}]},{"title":"Rescale AIC and BIC","body":["We need to rescale the AIC and BIC to be in line with the definition in [ZHT2007]\\_."],"code":[{"lang":"python","text":"def zou_et_al_criterion_rescaling(criterion, n_samples, noise_variance):\n    \"\"\"Rescale the information criterion to follow the definition of Zou et al.\"\"\"\n    return criterion - n_samples * np.log(2 * np.pi * noise_variance) - n_samples\n\naic_criterion = zou_et_al_criterion_rescaling(\n    lasso_lars_ic[-1].criterion_,\n    n_samples,\n    lasso_lars_ic[-1].noise_variance_,\n)\n\nindex_alpha_path_aic = np.flatnonzero(\n    lasso_lars_ic[-1].alphas_ == lasso_lars_ic[-1].alpha_\n)[0]"}]},{"title":"Fit LassoLarsIC estimator with BIC criterion","body":["Fit LassoLarsIC estimator with BIC criterion","We will now fit the LassoLarsIC estimator with BIC criterion."],"code":[{"lang":"python","text":"lasso_lars_ic.set_params(lassolarsic__criterion=\"bic\").fit(X, y)\n\nbic_criterion = zou_et_al_criterion_rescaling(\n    lasso_lars_ic[-1].criterion_,\n    n_samples,\n    lasso_lars_ic[-1].noise_variance_,\n)\n\nindex_alpha_path_bic = np.flatnonzero(\n    lasso_lars_ic[-1].alphas_ == lasso_lars_ic[-1].alpha_\n)[0]"}]},{"title":"Plot AIC and BIC Criterion","body":["We will plot the AIC and BIC criterion and the subsequent selected regularization parameter."],"code":[{"lang":"python","text":"plt.plot(aic_criterion, color=\"tab:blue\", marker=\"o\", label=\"AIC criterion\")\nplt.plot(bic_criterion, color=\"tab:orange\", marker=\"o\", label=\"BIC criterion\")\nplt.vlines(\n    index_alpha_path_bic,\n    aic_criterion.min(),\n    aic_criterion.max(),\n    color=\"black\",\n    linestyle=\"--\",\n    label=\"Selected alpha\",\n)\nplt.legend()\nplt.ylabel(\"Information criterion\")\nplt.xlabel(\"Lasso model sequence\")\n_ = plt.title(\"Lasso model selection via AIC and BIC\")"}]}],"commands":[],"reference":[{"path":"reference.py","text":"plt.plot(aic_criterion, color=\"tab:blue\", marker=\"o\", label=\"AIC criterion\")\nplt.plot(bic_criterion, color=\"tab:orange\", marker=\"o\", label=\"BIC criterion\")\nplt.vlines(\n    index_alpha_path_bic,\n    aic_criterion.min(),\n    aic_criterion.max(),\n    color=\"black\",\n    linestyle=\"--\",\n    label=\"Selected alpha\",\n)\nplt.legend()\nplt.ylabel(\"Information criterion\")\nplt.xlabel(\"Lasso model sequence\")\n_ = plt.title(\"Lasso model selection via AIC and BIC\")"}],"source":"scikit-learn/scikit-learn · BSD 3-Clause"},"labex-sklearn-model-selection-for-lasso-regression":{"intro":"In this lab, we will learn about selecting the best hyperparameter alpha for Lasso regression models. Two approaches will be discussed: (1) selecting the optimal value of alpha by only using the training set and some information criterion, and (2) selecting the best hyperparameter using cross-validation. We will use the diabetes dataset in this example.","steps":[{"title":"Dataset","body":["First, we will load the diabetes dataset using the load_diabetes function from sklearn.datasets. The dataset consists of 10 baseline variables, age, sex, body mass index, average blood pressure, and six blood serum measurements, and a quantitative measure of disease progression one year after baseline."],"code":[{"lang":"python","text":"from sklearn.datasets import load_diabetes\n\nX, y = load_diabetes(return_X_y=True, as_frame=True)\nX.head()"}]},{"title":"Adding Random Features","body":["We will add some random features to the original data to better illustrate the feature selection performed by the Lasso model. Random features will be generated using the RandomState function from numpy."],"code":[{"lang":"python","text":"import numpy as np\nimport pandas as pd\n\nrng = np.random.RandomState(42)\nn_random_features = 14\nX_random = pd.DataFrame(\n    rng.randn(X.shape[0], n_random_features),\n    columns=[f\"random_{i:02d}\" for i in range(n_random_features)],\n)\nX = pd.concat([X, X_random], axis=1)\nX[X.columns[::3]].head()"}]},{"title":"Selecting Lasso via an Information Criterion","body":["Selecting Lasso via an Information Criterion","We will use the LassoLarsIC function from sklearn.linear_model to provide a Lasso estimator that uses the Akaike information criterion (AIC) or the Bayes information criterion (BIC) to select the optimal value of the regularization parameter alpha. We will first fit a Lasso model with the AIC criterion."],"code":[{"lang":"python","text":"import time\nfrom sklearn.preprocessing import StandardScaler\nfrom sklearn.linear_model import LassoLarsIC\nfrom sklearn.pipeline import make_pipeline\n\nstart_time = time.time()\nlasso_lars_ic = make_pipeline(StandardScaler(), LassoLarsIC(criterion=\"aic\")).fit(X, y)\nfit_time = time.time() - start_time"}]},{"title":"Storing Results and Checking Optimal Alpha","body":["Storing Results and Checking Optimal Alpha","We will store the AIC metric for each value of alpha used during fit. We will then perform the same analysis using the BIC criterion. Finally, we will check which value of alpha leads to the minimum AIC and BIC."],"code":[{"lang":"python","text":"results = pd.DataFrame(\n    {\n        \"alphas\": lasso_lars_ic[-1].alphas_,\n        \"AIC criterion\": lasso_lars_ic[-1].criterion_,\n    }\n).set_index(\"alphas\")\nalpha_aic = lasso_lars_ic[-1].alpha_\n\nlasso_lars_ic.set_params(lassolarsic__criterion=\"bic\").fit(X, y)\nresults[\"BIC criterion\"] = lasso_lars_ic[-1].criterion_\nalpha_bic = lasso_lars_ic[-1].alpha_\n\ndef highlight_min(x):\n    x_min = x.min()\n    return [\"font-weight: bold\" if v == x_min else \"\" for v in x]\n\nresults.style.apply(highlight_min)"}]},{"title":"Plotting AIC and BIC Values","body":["Finally, we will plot the AIC and BIC values for the different alpha values. The vertical lines in the plot correspond to the alpha chosen for each criterion. The selected alpha corresponds to the minimum of the AIC or BIC criterion."],"code":[{"lang":"python","text":"ax = results.plot()\nax.vlines(\n    alpha_aic,\n    results[\"AIC criterion\"].min(),\n    results[\"AIC criterion\"].max(),\n    label=\"alpha: AIC estimate\",\n    linestyles=\"--\",\n    color=\"tab:blue\",\n)\nax.vlines(\n    alpha_bic,\n    results[\"BIC criterion\"].min(),\n    results[\"BIC criterion\"].max(),\n    label=\"alpha: BIC estimate\",\n    linestyle=\"--\",\n    color=\"tab:orange\",\n)\nax.set_xlabel(r\"$\\alpha$\")\nax.set_ylabel(\"criterion\")\nax.set_xscale(\"log\")\nax.legend()\n_ = ax.set_title(\n    f\"Information-criterion for model selection (training time {fit_time:.2f}s)\"\n)"}]},{"title":"Selecting Lasso via Cross-Validation","body":["Selecting Lasso via Cross-Validation","We will use two different estimators to select the best hyperparameter alpha with integrated cross-validation: LassoCV and LassoLarsCV. For both algorithms, we will use a 20-fold cross-validation strategy."],"code":[]},{"title":": Lasso via Coordinate Descent","body":["We will make the hyperparameter tuning using LassoCV."],"code":[{"lang":"python","text":"from sklearn.linear_model import LassoCV\n\nstart_time = time.time()\nmodel = make_pipeline(StandardScaler(), LassoCV(cv=20)).fit(X, y)\nfit_time = time.time() - start_time"}]},{"title":": Lasso via Least Angle Regression","body":["Lasso via Least Angle Regression","We will make the hyperparameter tuning using LassoLarsCV."],"code":[{"lang":"python","text":"from sklearn.linear_model import LassoLarsCV\n\nstart_time = time.time()\nmodel = make_pipeline(StandardScaler(), LassoLarsCV(cv=20)).fit(X, y)\nfit_time = time.time() - start_time"}]}],"commands":[],"reference":[],"source":"scikit-learn/scikit-learn · BSD 3-Clause"},"labex-sklearn-linear-discriminant-analysis-for-classificat":{"intro":"This lab will introduce you to Linear Discriminant Analysis (LDA) and how it can be used for classification. We will use scikit-learn, a popular machine learning library in Python, to implement LDA. We will also explore how the Ledoit-Wolf and Oracle Shrinkage Approximating (OAS) estimators of covariance can improve classification.","steps":[{"title":"Generate Random Data","body":["First, we need to generate random data with a discriminative feature and noisy features. We will use scikit-learn's make_blobs function to generate two clusters of data with one discriminative feature. Then we will add random noise to the other features."],"code":[{"lang":"python","text":"import numpy as np\nfrom sklearn.datasets import make_blobs\n\ndef generate_data(n_samples, n_features):\n    \"\"\"Generate random blob-ish data with noisy features.\n\n    This returns an array of input data with shape `(n_samples, n_features)`\n    and an array of `n_samples` target labels.\n\n    Only one feature contains discriminative information, the other features\n    contain only noise.\n    \"\"\"\n    X, y = make_blobs(n_samples=n_samples, n_features=1, centers=[[-2], [2]])\n\n    # add non-discriminative features\n    if n_features > 1:\n        X = np.hstack([X, np.random.randn(n_samples, n_features - 1)])\n    return X, y"}]},{"title":"Implement LDA","body":["Next, we will implement LDA using scikit-learn's LinearDiscriminantAnalysis class. We will create three classifiers:","• LDA with no shrinkage • LDA with Ledoit-Wolf shrinkage • LDA with OAS shrinkage"],"code":[{"lang":"python","text":"from sklearn.discriminant_analysis import LinearDiscriminantAnalysis\nfrom sklearn.covariance import OAS\n\nclf1 = LinearDiscriminantAnalysis(solver=\"lsqr\", shrinkage=None)\nclf2 = LinearDiscriminantAnalysis(solver=\"lsqr\", shrinkage=\"auto\")\noa = OAS(store_precision=False, assume_centered=False)\nclf3 = LinearDiscriminantAnalysis(solver=\"lsqr\", covariance_estimator=oa)"}]},{"title":"Train and Test Classifiers","body":["We will train and test each classifier to see how they perform on the generated data. We will repeat this process multiple times to get an average accuracy score."],"code":[{"lang":"python","text":"n_train = 20  # samples for training\nn_test = 200  # samples for testing\nn_averages = 50  # how often to repeat classification\nn_features_max = 75  # maximum number of features\nstep = 4  # step size for the calculation\n\nacc_clf1, acc_clf2, acc_clf3 = [], [], []\nn_features_range = range(1, n_features_max + 1, step)\n\nfor n_features in n_features_range:\n    score_clf1, score_clf2, score_clf3 = 0, 0, 0\n    for _ in range(n_averages):\n        X, y = generate_data(n_train, n_features)\n\n        clf1.fit(X, y)\n        clf2.fit(X, y)\n        clf3.fit(X, y)\n\n        X, y = generate_data(n_test, n_features)\n        score_clf1 += clf1.score(X, y)\n        score_clf2 += clf2.score(X, y)\n        score_clf3 += clf3.score(X, y)\n\n    acc_clf1.append(score_clf1 / n_averages)\n    acc_clf2.append(score_clf2 / n_averages)\n    acc_clf3.append(score_clf3 / n_averages)"}]},{"title":"Visualize Results","body":["Finally, we will plot the classification accuracy for each classifier as a function of the number of features. We will use matplotlib to create the plot."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\n\nfeatures_samples_ratio = np.array(n_features_range) / n_train\n\nplt.plot(\n    features_samples_ratio,\n    acc_clf1,\n    linewidth=2,\n    label=\"LDA\",\n    color=\"gold\",\n    linestyle=\"solid\",\n)\nplt.plot(\n    features_samples_ratio,\n    acc_clf2,\n    linewidth=2,\n    label=\"LDA with Ledoit Wolf\",\n    color=\"navy\",\n    linestyle=\"dashed\",\n)\nplt.plot(\n    features_samples_ratio,\n    acc_clf3,\n    linewidth=2,\n    label=\"LDA with OAS\",\n    color=\"red\",\n    linestyle=\"dotted\",\n)\n\nplt.xlabel(\"n_features / n_samples\")\nplt.ylabel(\"Classification accuracy\")\n\nplt.legend(loc=\"lower left\")\nplt.ylim((0.65, 1.0))\nplt.suptitle(\n    \"LDA (Linear Discriminant Analysis) vs. \"\n    + \"\\n\"\n    + \"LDA with Ledoit Wolf vs. \"\n    + \"\\n\"\n    + \"LDA with OAS (1 discriminative feature)\"\n)\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"import matplotlib.pyplot as plt\n\nfeatures_samples_ratio = np.array(n_features_range) / n_train\n\nplt.plot(\n    features_samples_ratio,\n    acc_clf1,\n    linewidth=2,\n    label=\"LDA\",\n    color=\"gold\",\n    linestyle=\"solid\",\n)\nplt.plot(\n    features_samples_ratio,\n    acc_clf2,\n    linewidth=2,\n    label=\"LDA with Ledoit Wolf\",\n    color=\"navy\",\n    linestyle=\"dashed\",\n)\nplt.plot(\n    features_samples_ratio,\n    acc_clf3,\n    linewidth=2,\n    label=\"LDA with OAS\",\n    color=\"red\",\n    linestyle=\"dotted\",\n)\n\nplt.xlabel(\"n_features / n_samples\")\nplt.ylabel(\"Classification accuracy\")\n\nplt.legend(loc=\"lower left\")\nplt.ylim((0.65, 1.0))\nplt.suptitle(\n    \"LDA (Linear Discriminant Analysis) vs. \"\n    + \"\\n\"\n    + \"LDA with Ledoit Wolf vs. \"\n    + \"\\n\"\n    + \"LDA with OAS (1 discriminative feature)\"\n)\nplt.show()"}],"source":"scikit-learn/scikit-learn · BSD 3-Clause"},"labex-sklearn-discriminant-analysis-classification-algorit":{"intro":"In this lab, we will learn about Linear and Quadratic Discriminant Analysis (LDA and QDA). LDA and QDA are classification algorithms that are used to find a linear and quadratic decision boundary, respectively, between two or more classes. We will use the scikit-learn library to implement these algorithms and visualize the decision boundaries.","steps":[{"title":"Import Libraries and Generate Datasets","body":["Import Libraries and Generate Datasets","First, we will import the necessary libraries and generate two datasets: one with fixed covariance and one with varying covariances."],"code":[{"lang":"python","text":"import numpy as np\nimport matplotlib.pyplot as plt\nfrom scipy import linalg\nfrom matplotlib import colors\nimport matplotlib as mpl\nfrom sklearn.discriminant_analysis import LinearDiscriminantAnalysis, QuadraticDiscriminantAnalysis\n\n# generate dataset with fixed covariance\ndef dataset_fixed_cov():\n    n, dim = 300, 2\n    np.random.seed(0)\n    C = np.array([[0.0, -0.23], [0.83, 0.23]])\n    X = np.r_[np.dot(np.random.randn(n, dim), C), np.dot(np.random.randn(n, dim), C) + np.array([1, 1])]\n    y = np.hstack((np.zeros(n), np.ones(n)))\n    return X, y\n\n# generate dataset with varying covariances\ndef dataset_cov():\n    n, dim = 300, 2\n    np.random.seed(0)\n    C = np.array([[0.0, -1.0], [2.5, 0.7]]) * 2.0\n    X = np.r_[np.dot(np.random.randn(n, dim), C), np.dot(np.random.randn(n, dim), C.T) + np.array([1, 4])]\n    y = np.hstack((np.zeros(n), np.ones(n)))\n    return X, y"}]},{"title":"Create Colormap","body":["We will create a custom colormap to use in our visualizations."],"code":[{"lang":"python","text":"cmap = colors.LinearSegmentedColormap(\n    \"red_blue_classes\",\n    {\n        \"red\": [(0, 1, 1), (1, 0.7, 0.7)],\n        \"green\": [(0, 0.7, 0.7), (1, 0.7, 0.7)],\n        \"blue\": [(0, 0.7, 0.7), (1, 1, 1)],\n    },\n)\nplt.cm.register_cmap(cmap=cmap)"}]},{"title":"Plot Functions","body":["We will define two functions to plot the data and ellipses."],"code":[{"lang":"python","text":"def plot_data(lda, X, y, y_pred, fig_index):\n    splot = plt.subplot(2, 2, fig_index)\n    if fig_index == 1:\n        plt.title(\"Linear Discriminant Analysis\")\n        plt.ylabel(\"Data with\\n fixed covariance\")\n    elif fig_index == 2:\n        plt.title(\"Quadratic Discriminant Analysis\")\n    elif fig_index == 3:\n        plt.ylabel(\"Data with\\n varying covariances\")\n\n    tp = y == y_pred  # True Positive\n    tp0, tp1 = tp[y == 0], tp[y == 1]\n    X0, X1 = X[y == 0], X[y == 1]\n    X0_tp, X0_fp = X0[tp0], X0[~tp0]\n    X1_tp, X1_fp = X1[tp1], X1[~tp1]\n\n    # class 0: dots\n    plt.scatter(X0_tp[:, 0], X0_tp[:, 1], marker=\".\", color=\"red\")\n    plt.scatter(X0_fp[:, 0], X0_fp[:, 1], marker=\"x\", s=20, color=\"#990000\")  # dark red\n\n    # class 1: dots\n    plt.scatter(X1_tp[:, 0], X1_tp[:, 1], marker=\".\", color=\"blue\")\n    plt.scatter(X1_fp[:, 0], X1_fp[:, 1], marker=\"x\", s=20, color=\"#000099\")  # dark blue\n\n    # class 0 and 1 : areas\n    nx, ny = 200, 100\n    x_min, x_max = plt.xlim()\n    y_min, y_max = plt.ylim()\n    xx, yy = np.meshgrid(np.linspace(x_min, x_max, nx), np.linspace(y_min, y_max, ny))\n    Z = lda.predict_proba(np.c_[xx.ravel(), yy.ravel()])\n    Z = Z[:, 1].reshape(xx.shape)\n    plt.pcolormesh(xx, yy, Z, cmap=\"red_blue_classes\", norm=colors.Normalize(0.0, 1.0), zorder=0)\n    plt.contour(xx, yy, Z, [0.5], linewidths=2.0, colors=\"white\")\n\n    # means\n    plt.plot(lda.means_[0][0], lda.means_[0][1], \"*\", color=\"yellow\", markersize=15, markeredgecolor=\"grey\")\n    plt.plot(lda.means_[1][0], lda.means_[1][1], \"*\", color=\"yellow\", markersize=15, markeredgecolor=\"grey\")\n\n    return splot\n\n\ndef plot_ellipse(splot, mean, cov, color):\n    v, w = linalg.eigh(cov)\n    u = w[0] / linalg.norm(w[0])\n    angle = np.arctan(u[1] / u[0])\n    angle = 180 * angle / np.pi  # convert to degrees\n    # filled Gaussian at 2 standard deviation\n    ell = mpl.patches.Ellipse(mean, 2 * v[0] ** 0.5, 2 * v[1] ** 0.5, angle=180 + angle, facecolor=color, edgecolor=\"black\", linewidth=2)"}]},{"title":"Plot LDA Covariance Ellipses","body":["We will plot the covariance ellipsoids for LDA."],"code":[{"lang":"python","text":"def plot_lda_cov(lda, splot):\n    plot_ellipse(splot, lda.means_[0], lda.covariance_, \"red\")\n    plot_ellipse(splot, lda.means_[1], lda.covariance_, \"blue\")"}]},{"title":"Plot QDA Covariance Ellipses","body":["We will plot the covariance ellipsoids for QDA."],"code":[{"lang":"python","text":"def plot_qda_cov(qda, splot):\n    plot_ellipse(splot, qda.means_[0], qda.covariance_[0], \"red\")\n    plot_ellipse(splot, qda.means_[1], qda.covariance_[1], \"blue\")"}]},{"title":"Visualize the Decision Boundaries","body":["Visualize the Decision Boundaries","We will use the datasets generated in Step 1 to visualize the decision boundaries for LDA and QDA."],"code":[{"lang":"python","text":"plt.figure(figsize=(10, 8), facecolor=\"white\")\nplt.suptitle(\"Linear Discriminant Analysis vs Quadratic Discriminant Analysis\", y=0.98, fontsize=15)\n\nfor i, (X, y) in enumerate([dataset_fixed_cov(), dataset_cov()]):\n    # Linear Discriminant Analysis\n    lda = LinearDiscriminantAnalysis(solver=\"svd\", store_covariance=True)\n    y_pred = lda.fit(X, y).predict(X)\n    splot = plot_data(lda, X, y, y_pred, fig_index=2 * i + 1)\n    plot_lda_cov(lda, splot)\n    plt.axis(\"tight\")\n\n    # Quadratic Discriminant Analysis\n    qda = QuadraticDiscriminantAnalysis(store_covariance=True)\n    y_pred = qda.fit(X, y).predict(X)\n    splot = plot_data(qda, X, y, y_pred, fig_index=2 * i + 2)\n    plot_qda_cov(qda, splot)\n    plt.axis(\"tight\")\n\nplt.tight_layout()\nplt.subplots_adjust(top=0.92)\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"plt.figure(figsize=(10, 8), facecolor=\"white\")\nplt.suptitle(\"Linear Discriminant Analysis vs Quadratic Discriminant Analysis\", y=0.98, fontsize=15)\n\nfor i, (X, y) in enumerate([dataset_fixed_cov(), dataset_cov()]):\n    # Linear Discriminant Analysis\n    lda = LinearDiscriminantAnalysis(solver=\"svd\", store_covariance=True)\n    y_pred = lda.fit(X, y).predict(X)\n    splot = plot_data(lda, X, y, y_pred, fig_index=2 * i + 1)\n    plot_lda_cov(lda, splot)\n    plt.axis(\"tight\")\n\n    # Quadratic Discriminant Analysis\n    qda = QuadraticDiscriminantAnalysis(store_covariance=True)\n    y_pred = qda.fit(X, y).predict(X)\n    splot = plot_data(qda, X, y, y_pred, fig_index=2 * i + 2)\n    plot_qda_cov(qda, splot)\n    plt.axis(\"tight\")\n\nplt.tight_layout()\nplt.subplots_adjust(top=0.92)\nplt.show()"}],"source":"scikit-learn/scikit-learn · BSD 3-Clause"},"labex-sklearn-plotting-learning-curves":{"intro":"The purpose of this lab is to show how to use the LearningCurveDisplay class from scikit-learn to plot learning curves. Learning curves show the effect of adding more samples during the training process. We will analyze the learning curve of a naive Bayes classifier and a SVM classifier with a RBF kernel using the digits dataset. Additionally, we will look at the scalability of these predictive models by looking at their computational cost and not only at their statistical accuracy.","steps":[{"title":"Load the dataset","body":[],"code":[{"lang":"python","text":"from sklearn.datasets import load_digits\n\nX, y = load_digits(return_X_y=True)"}]},{"title":"Define the models","body":[],"code":[{"lang":"python","text":"from sklearn.naive_bayes import GaussianNB\nfrom sklearn.svm import SVC\n\nnaive_bayes = GaussianNB()\nsvc = SVC(kernel=\"rbf\", gamma=0.001)"}]},{"title":"Plot the learning curves","body":[],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\nfrom sklearn.model_selection import LearningCurveDisplay, ShuffleSplit\n\nfig, ax = plt.subplots(nrows=1, ncols=2, figsize=(10, 6), sharey=True)\n\ncommon_params = {\n    \"X\": X,\n    \"y\": y,\n    \"train_sizes\": np.linspace(0.1, 1.0, 5),\n    \"cv\": ShuffleSplit(n_splits=50, test_size=0.2, random_state=0),\n    \"score_type\": \"both\",\n    \"n_jobs\": 4,\n    \"line_kw\": {\"marker\": \"o\"},\n    \"std_display_style\": \"fill_between\",\n    \"score_name\": \"Accuracy\",\n}\n\nfor ax_idx, estimator in enumerate([naive_bayes, svc]):\n    LearningCurveDisplay.from_estimator(estimator, **common_params, ax=ax[ax_idx])\n    handles, label = ax[ax_idx].get_legend_handles_labels()\n    ax[ax_idx].legend(handles[:2], [\"Training Score\", \"Test Score\"])\n    ax[ax_idx].set_title(f\"Learning Curve for {estimator.__class__.__name__}\")"}]},{"title":"Analyze the learning curves","body":["We can analyze the learning curve of the naive Bayes classifier. Its shape can be found in more complex datasets very often: the training score is very high when using few samples for training and decreases when increasing the number of samples, whereas the test score is very low at the beginning and then increases when adding samples. The training and test scores become more realistic when all the samples are used for training.","We see another typical learning curve for the SVM classifier with RBF kernel. The training score remains high regardless of the size of the training set. On the other hand, the test score increases with the size of the training dataset. Indeed, it increases up to a point where it reaches a plateau. Observing such a plateau is an indication that it might not be useful to acquire new data to train the model since the generalization performance of the model will not increase anymore."],"code":[{"lang":"python","text":"# Interpret the learning curves"}]},{"title":"Check the scalability of the models","body":["Check the scalability of the models"],"code":[{"lang":"python","text":"from sklearn.model_selection import learning_curve\n\ncommon_params = {\n    \"X\": X,\n    \"y\": y,\n    \"train_sizes\": np.linspace(0.1, 1.0, 5),\n    \"cv\": ShuffleSplit(n_splits=50, test_size=0.2, random_state=0),\n    \"n_jobs\": 4,\n    \"return_times\": True,\n}\n\ntrain_sizes, _, test_scores_nb, fit_times_nb, score_times_nb = learning_curve(\n    naive_bayes, **common_params\n)\ntrain_sizes, _, test_scores_svm, fit_times_svm, score_times_svm = learning_curve(\n    svc, **common_params\n)"}]},{"title":"Plot the scalability of the models","body":["Plot the scalability of the models"],"code":[{"lang":"python","text":"fig, ax = plt.subplots(nrows=2, ncols=2, figsize=(16, 12), sharex=True)\n\nfor ax_idx, (fit_times, score_times, estimator) in enumerate(\n    zip(\n        [fit_times_nb, fit_times_svm],\n        [score_times_nb, score_times_svm],\n        [naive_bayes, svc],\n    )\n):\n    # scalability regarding the fit time\n    ax[0, ax_idx].plot(train_sizes, fit_times.mean(axis=1), \"o-\")\n    ax[0, ax_idx].fill_between(\n        train_sizes,\n        fit_times.mean(axis=1) - fit_times.std(axis=1),\n        fit_times.mean(axis=1) + fit_times.std(axis=1),\n        alpha=0.3,\n    )\n    ax[0, ax_idx].set_ylabel(\"Fit time (s)\")\n    ax[0, ax_idx].set_title(\n        f\"Scalability of the {estimator.__class__.__name__} classifier\"\n    )\n\n    # scalability regarding the score time\n    ax[1, ax_idx].plot(train_sizes, score_times.mean(axis=1), \"o-\")\n    ax[1, ax_idx].fill_between(\n        train_sizes,\n        score_times.mean(axis=1) - score_times.std(axis=1),\n        score_times.mean(axis=1) + score_times.std(axis=1),\n        alpha=0.3,\n    )\n    ax[1, ax_idx].set_ylabel(\"Score time (s)\")\n    ax[1, ax_idx].set_xlabel(\"Number of training samples\")"}]},{"title":"Check the trade-off between increased training time and cross-validation score","body":["Check the trade-off between increased training time and cross-validation score"],"code":[{"lang":"python","text":"fig, ax = plt.subplots(nrows=1, ncols=2, figsize=(16, 6))\n\nfor ax_idx, (fit_times, test_scores, estimator) in enumerate(\n    zip(\n        [fit_times_nb, fit_times_svm],\n        [test_scores_nb, test_scores_svm],\n        [naive_bayes, svc],\n    )\n):\n    ax[ax_idx].plot(fit_times.mean(axis=1), test_scores.mean(axis=1), \"o-\")\n    ax[ax_idx].fill_between(\n        fit_times.mean(axis=1),\n        test_scores.mean(axis=1) - test_scores.std(axis=1),\n        test_scores.mean(axis=1) + test_scores.std(axis=1),\n        alpha=0.3,\n    )\n    ax[ax_idx].set_ylabel(\"Accuracy\")\n    ax[ax_idx].set_xlabel(\"Fit time (s)\")\n    ax[ax_idx].set_title(\n        f\"Performance of the {estimator.__class__.__name__} classifier\"\n    )\n\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"fig, ax = plt.subplots(nrows=1, ncols=2, figsize=(16, 6))\n\nfor ax_idx, (fit_times, test_scores, estimator) in enumerate(\n    zip(\n        [fit_times_nb, fit_times_svm],\n        [test_scores_nb, test_scores_svm],\n        [naive_bayes, svc],\n    )\n):\n    ax[ax_idx].plot(fit_times.mean(axis=1), test_scores.mean(axis=1), \"o-\")\n    ax[ax_idx].fill_between(\n        fit_times.mean(axis=1),\n        test_scores.mean(axis=1) - test_scores.std(axis=1),\n        test_scores.mean(axis=1) + test_scores.std(axis=1),\n        alpha=0.3,\n    )\n    ax[ax_idx].set_ylabel(\"Accuracy\")\n    ax[ax_idx].set_xlabel(\"Fit time (s)\")\n    ax[ax_idx].set_title(\n        f\"Performance of the {estimator.__class__.__name__} classifier\"\n    )\n\nplt.show()"}],"source":"scikit-learn/scikit-learn · BSD 3-Clause"},"labex-sklearn-class-likelihood-ratios-to-measure-classific":{"intro":"In this lab, we will use scikit-learn to demonstrate how to compute the positive and negative likelihood ratios (LR+, LR-) to assess the predictive power of a binary classifier. These metrics are independent of the proportion between classes in the test set, which makes them very useful when the available data for a study has a different class proportion than the target application. We will go through the following steps:","steps":[{"title":"Preparing the Data","body":["We will generate a synthetic dataset using the make_classification function from scikit-learn. This dataset will simulate a population with a minority of subjects carrying a disease."],"code":[]},{"title":"Pre-test vs. Post-test Analysis","body":["Pre-test vs. Post-test Analysis","We will fit a logistic regression model to the data and evaluate its performance on a held-out test set. We will compute the positive likelihood ratio to evaluate the usefulness of this classifier as a disease diagnosis tool."],"code":[]},{"title":"Cross-validation of Likelihood Ratios","body":["Cross-validation of Likelihood Ratios","We will assess the variability of the measurements for the class likelihood ratios in some particular cases using cross-validation."],"code":[]},{"title":"Invariance with Respect to Prevalence","body":["Invariance with Respect to Prevalence","We will show that the class likelihood ratios are independent of the disease prevalence and can be extrapolated between populations regardless of any possible class imbalance.","We will generate a synthetic dataset using the make_classification function from scikit-learn. This dataset will simulate a population with a minority of subjects carrying a disease.","Pre-test vs. Post-test Analysis"],"code":[{"lang":"python","text":"from sklearn.datasets import make_classification\n\nX, y = make_classification(n_samples=10_000, weights=[0.9, 0.1], random_state=0)\nprint(f\"Percentage of people carrying the disease: {100*y.mean():.2f}%\")"},{"lang":"python","text":"from sklearn.model_selection import train_test_split\nfrom sklearn.metrics import class_likelihood_ratios\nfrom sklearn.linear_model import LogisticRegression\n\nX_train, X_test, y_train, y_test = train_test_split(X, y, random_state=0)\n\nestimator = LogisticRegression().fit(X_train, y_train)\ny_pred = estimator.predict(X_test)\npos_LR, neg_LR = class_likelihood_ratios(y_test, y_pred)\n\nprint(f\"LR+: {pos_LR:.3f}\")"},{"lang":"python","text":"import pandas as pd\nfrom sklearn.model_selection import cross_validate\nfrom sklearn.dummy import DummyClassifier\n\ndef scoring(estimator, X, y):\n    y_pred = estimator.predict(X)\n    pos_lr, neg_lr = class_likelihood_ratios(y, y_pred, raise_warning=False)\n    return {\"positive_likelihood_ratio\": pos_lr, \"negative_likelihood_ratio\": neg_lr}\n\ndef extract_score(cv_results):\n    lr = pd.DataFrame(\n        {\n            \"positive\": cv_results[\"test_positive_likelihood_ratio\"],\n            \"negative\": cv_results[\"test_negative_likelihood_ratio\"],\n        }\n    )\n    return lr.aggregate([\"mean\", \"std\"])\n\nestimator = LogisticRegression()\nextract_score(cross_validate(estimator, X, y, scoring=scoring, cv=10))\n\nestimator = DummyClassifier(strategy=\"stratified\", random_state=1234)\nextract_score(cross_validate(estimator, X, y, scoring=scoring, cv=10))\n\nestimator = DummyClassifier(strategy=\"most_frequent\")\nextract_score(cross_validate(estimator, X, y, scoring=scoring, cv=10))"}]}],"commands":[],"reference":[{"path":"reference.py","text":"import pandas as pd\nfrom sklearn.model_selection import cross_validate\nfrom sklearn.dummy import DummyClassifier\n\ndef scoring(estimator, X, y):\n    y_pred = estimator.predict(X)\n    pos_lr, neg_lr = class_likelihood_ratios(y, y_pred, raise_warning=False)\n    return {\"positive_likelihood_ratio\": pos_lr, \"negative_likelihood_ratio\": neg_lr}\n\ndef extract_score(cv_results):\n    lr = pd.DataFrame(\n        {\n            \"positive\": cv_results[\"test_positive_likelihood_ratio\"],\n            \"negative\": cv_results[\"test_negative_likelihood_ratio\"],\n        }\n    )\n    return lr.aggregate([\"mean\", \"std\"])\n\nestimator = LogisticRegression()\nextract_score(cross_validate(estimator, X, y, scoring=scoring, cv=10))\n\nestimator = DummyClassifier(strategy=\"stratified\", random_state=1234)\nextract_score(cross_validate(estimator, X, y, scoring=scoring, cv=10))\n\nestimator = DummyClassifier(strategy=\"most_frequent\")\nextract_score(cross_validate(estimator, X, y, scoring=scoring, cv=10))"}],"source":"scikit-learn/scikit-learn · BSD 3-Clause"},"labex-sklearn-hierarchical-clustering-with-scikit-learn":{"intro":"In this lab, we will be using Python's scikit-learn library to perform hierarchical clustering on a few toy datasets. Hierarchical clustering is a method of clustering where you build a hierarchy of clusters, either in a top-down or bottom-up fashion. The goal of hierarchical clustering is to find clusters of points that are similar to each other, and dissimilar to points in other clusters.","steps":[{"title":"Import Libraries and Load Data","body":["Import Libraries and Load Data","We will start by importing the necessary libraries and loading the toy datasets that we will be using for our hierarchical clustering examples."],"code":[{"lang":"python","text":"import time\nimport warnings\n\nimport numpy as np\nimport matplotlib.pyplot as plt\n\nfrom sklearn import cluster, datasets\nfrom sklearn.preprocessing import StandardScaler\nfrom itertools import cycle, islice\n\nnp.random.seed(0)\n\n# %%\n# Generate datasets. We choose the size big enough to see the scalability\n# of the algorithms, but not too big to avoid too long running times\n\nn_samples = 1500\nnoisy_circles = datasets.make_circles(n_samples=n_samples, factor=0.5, noise=0.05)\nnoisy_moons = datasets.make_moons(n_samples=n_samples, noise=0.05)\nblobs = datasets.make_blobs(n_samples=n_samples, random_state=8)\nno_structure = np.random.rand(n_samples, 2), None\n\n# Anisotropicly distributed data\nrandom_state = 170\nX, y = datasets.make_blobs(n_samples=n_samples, random_state=random_state)\ntransformation = [[0.6, -0.6], [-0.4, 0.8]]\nX_aniso = np.dot(X, transformation)\naniso = (X_aniso, y)\n\n# blobs with varied variances\nvaried = datasets.make_blobs(\n    n_samples=n_samples, cluster_std=[1.0, 2.5, 0.5], random_state=random_state\n)"}]},{"title":"Perform Hierarchical Clustering","body":["Perform Hierarchical Clustering","We will now perform hierarchical clustering on the toy datasets that we loaded in step 1. We will use different linkage methods such as single, average, complete, and ward to build our clusters."],"code":[{"lang":"python","text":"# Set up cluster parameters\nplt.figure(figsize=(9 * 1.3 + 2, 14.5))\nplt.subplots_adjust(\n    left=0.02, right=0.98, bottom=0.001, top=0.96, wspace=0.05, hspace=0.01\n)\n\nplot_num = 1\n\ndefault_base = {\"n_neighbors\": 10, \"n_clusters\": 3}\n\ndatasets = [\n    (noisy_circles, {\"n_clusters\": 2}),\n    (noisy_moons, {\"n_clusters\": 2}),\n    (varied, {\"n_neighbors\": 2}),\n    (aniso, {\"n_neighbors\": 2}),\n    (blobs, {}),\n    (no_structure, {}),\n]\n\nfor i_dataset, (dataset, algo_params) in enumerate(datasets):\n    # update parameters with dataset-specific values\n    params = default_base.copy()\n    params.update(algo_params)\n\n    X, y = dataset\n\n    # normalize dataset for easier parameter selection\n    X = StandardScaler().fit_transform(X)\n\n    # ============\n    # Create cluster objects\n    # ============\n    ward = cluster.AgglomerativeClustering(\n        n_clusters=params[\"n_clusters\"], linkage=\"ward\"\n    )\n    complete = cluster.AgglomerativeClustering(\n        n_clusters=params[\"n_clusters\"], linkage=\"complete\"\n    )\n    average = cluster.AgglomerativeClustering(\n        n_clusters=params[\"n_clusters\"], linkage=\"average\"\n    )\n    single = cluster.AgglomerativeClustering(\n        n_clusters=params[\"n_clusters\"], linkage=\"single\"\n    )\n\n    clustering_algorithms = (\n        (\"Single Linkage\", single),\n        (\"Average Linkage\", average),"}]},{"title":"Analyze the Results","body":["We will now analyze the results of our hierarchical clustering. Based on the toy datasets that we used, we can make the following observations:","• Single linkage is fast, and can perform well on non-globular data, but it performs poorly in the presence of noise. • Average and complete linkage perform well on cleanly separated globular clusters, but have mixed results otherwise. • Ward is the most effective method for noisy data.","It is important to note that while these observations give us some intuition about the algorithms, this intuition might not apply to very high dimensional data."],"code":[]}],"commands":[],"reference":[],"source":"scikit-learn/scikit-learn · BSD 3-Clause"},"labex-sklearn-manifold-learning-on-handwritten-digits":{"intro":"In this lab, we will explore various manifold embedding techniques on the digits dataset. We will use different techniques to embed the digits dataset, plot the projection of the original data onto each embedding, and compare the results obtained from different embedding methods.","steps":[{"title":"Load the Digits Dataset","body":["We will load the digits dataset and only use six of the ten available classes. We will also plot the first hundred digits from this dataset."],"code":[{"lang":"python","text":"# Load digits dataset\nfrom sklearn.datasets import load_digits\n\ndigits = load_digits(n_class=6)\nX, y = digits.data, digits.target\nn_samples, n_features = X.shape\nn_neighbors = 30\n\n# Plot first hundred digits\nimport matplotlib.pyplot as plt\n\nfig, axs = plt.subplots(nrows=10, ncols=10, figsize=(6, 6))\nfor idx, ax in enumerate(axs.ravel()):\n    ax.imshow(X[idx].reshape((8, 8)), cmap=plt.cm.binary)\n    ax.axis(\"off\")\n_ = fig.suptitle(\"A selection from the 64-dimensional digits dataset\", fontsize=16)"}]},{"title":"Plot Embedding Function","body":["We will define a helper function to plot the embedding. The function takes the embedding data and the title for the plot as input. The function will plot every digit on the embedding and show an annotation box for a group of digits."],"code":[{"lang":"python","text":"import numpy as np\nfrom matplotlib import offsetbox\nfrom sklearn.preprocessing import MinMaxScaler\n\ndef plot_embedding(X, title):\n    _, ax = plt.subplots()\n    X = MinMaxScaler().fit_transform(X)\n\n    for digit in digits.target_names:\n        ax.scatter(\n            *X[y == digit].T,\n            marker=f\"${digit}$\",\n            s=60,\n            color=plt.cm.Dark2(digit),\n            alpha=0.425,\n            zorder=2,\n        )\n    shown_images = np.array([[1.0, 1.0]])  # just something big\n    for i in range(X.shape[0]):\n        # plot every digit on the embedding\n        # show an annotation box for a group of digits\n        dist = np.sum((X[i] - shown_images) ** 2, 1)\n        if np.min(dist) < 4e-3:\n            # don't show points that are too close\n            continue\n        shown_images = np.concatenate([shown_images, [X[i]]], axis=0)\n        imagebox = offsetbox.AnnotationBbox(\n            offsetbox.OffsetImage(digits.images[i], cmap=plt.cm.gray_r), X[i]\n        )\n        imagebox.set(zorder=1)\n        ax.add_artist(imagebox)\n\n    ax.set_title(title)\n    ax.axis(\"off\")"}]},{"title":"Compare Embedding Techniques","body":["We will compare different embedding techniques using different methods. We will store the projected data as well as the computational time needed to perform each projection."],"code":[{"lang":"python","text":"from sklearn.decomposition import TruncatedSVD\nfrom sklearn.discriminant_analysis import LinearDiscriminantAnalysis\nfrom sklearn.ensemble import RandomTreesEmbedding\nfrom sklearn.manifold import (\n    Isomap,\n    LocallyLinearEmbedding,\n    MDS,\n    SpectralEmbedding,\n    TSNE,\n)\nfrom sklearn.neighbors import NeighborhoodComponentsAnalysis\nfrom sklearn.pipeline import make_pipeline\nfrom sklearn.random_projection import SparseRandomProjection\n\nembeddings = {\n    \"Random projection embedding\": SparseRandomProjection(\n        n_components=2, random_state=42\n    ),\n    \"Truncated SVD embedding\": TruncatedSVD(n_components=2),\n    \"Linear Discriminant Analysis embedding\": LinearDiscriminantAnalysis(\n        n_components=2\n    ),\n    \"Isomap embedding\": Isomap(n_neighbors=n_neighbors, n_components=2),\n    \"Standard LLE embedding\": LocallyLinearEmbedding(\n        n_neighbors=n_neighbors, n_components=2, method=\"standard\"\n    ),\n    \"Modified LLE embedding\": LocallyLinearEmbedding(\n        n_neighbors=n_neighbors, n_components=2, method=\"modified\"\n    ),\n    \"Hessian LLE embedding\": LocallyLinearEmbedding(\n        n_neighbors=n_neighbors, n_components=2, method=\"hessian\"\n    ),\n    \"LTSA LLE embedding\": LocallyLinearEmbedding(\n        n_neighbors=n_neighbors, n_components=2, method=\"ltsa\"\n    ),\n    \"MDS embedding\": MDS(\n        n_components=2, n_init=1, max_iter=120, n_jobs=2, normalized_stress=\"auto\"\n    ),\n    \"Random Trees embedding\": make_pipeline(\n        RandomTreesEmbedding(n_estimators=200, max_depth=5, random_state=0),\n        TruncatedSVD(n_components=2),\n    ),\n    \"Spectral embedding\": SpectralEmbedding(\n        n_components=2, random_state=0, eigen_solver=\"arpack\"\n    ),\n    \"t-SNE embeedding\": TSNE(\n        n_components=2,\n        n_iter=500,"}]},{"title":"Plot Results","body":["We will plot the resulting projection given by each method."],"code":[{"lang":"python","text":"for name in timing:\n    title = f\"{name} (time {timing[name]:.3f}s)\"\n    plot_embedding(projections[name], title)\n\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"for name in timing:\n    title = f\"{name} (time {timing[name]:.3f}s)\"\n    plot_embedding(projections[name], title)\n\nplt.show()"}],"source":"scikit-learn/scikit-learn · BSD 3-Clause"},"labex-sklearn-local-outlier-factor-for-novelty-detection":{"intro":"In this lab, we will use the Local Outlier Factor (LOF) algorithm to perform novelty detection. LOF is an unsupervised anomaly detection method that identifies the local density deviation of a given data point with respect to its neighbors. It considers the samples that have a substantially lower density than their neighbors as outliers.","steps":[{"title":"Import Libraries","body":["We will start by importing the necessary libraries. We will use scikit-learn, numpy, and matplotlib."],"code":[{"lang":"python","text":"import numpy as np\nimport matplotlib.pyplot as plt\nfrom sklearn.neighbors import LocalOutlierFactor"}]},{"title":"Generate Data","body":["We will generate some data for training, testing, and outliers using numpy. We will generate 100 normal training observations, 20 normal testing observations, and 20 abnormal novel observations."],"code":[{"lang":"python","text":"np.random.seed(42)\n\nxx, yy = np.meshgrid(np.linspace(-5, 5, 500), np.linspace(-5, 5, 500))\nX = 0.3 * np.random.randn(100, 2)\nX_train = np.r_[X + 2, X - 2]\nX = 0.3 * np.random.randn(20, 2)\nX_test = np.r_[X + 2, X - 2]\nX_outliers = np.random.uniform(low=-4, high=4, size=(20, 2))"}]},{"title":"Train the Model","body":["We will now train the LOF model using the training data. We set the number of neighbors to 20 and novelty to true. We also set the contamination to 0.1."],"code":[{"lang":"python","text":"clf = LocalOutlierFactor(n_neighbors=20, novelty=True, contamination=0.1)\nclf.fit(X_train)"}]},{"title":"Evaluate the Model","body":["We will evaluate the trained model on the testing and outlier data. We will use the predict method to predict the labels of the testing and outlier data. We will then count the number of errors in the testing and outlier data."],"code":[{"lang":"python","text":"y_pred_test = clf.predict(X_test)\ny_pred_outliers = clf.predict(X_outliers)\nn_error_test = y_pred_test[y_pred_test == -1].size\nn_error_outliers = y_pred_outliers[y_pred_outliers == 1].size"}]},{"title":"Visualize the Results","body":["We will visualize the results by plotting the training, testing, and outlier data along with the learned frontier. We will also display the number of errors in the testing and outlier data."],"code":[{"lang":"python","text":"Z = clf.decision_function(np.c_[xx.ravel(), yy.ravel()])\nZ = Z.reshape(xx.shape)\n\nplt.title(\"Novelty Detection with LOF\")\nplt.contourf(xx, yy, Z, levels=np.linspace(Z.min(), 0, 7), cmap=plt.cm.PuBu)\na = plt.contour(xx, yy, Z, levels=[0], linewidths=2, colors=\"darkred\")\nplt.contourf(xx, yy, Z, levels=[0, Z.max()], colors=\"palevioletred\")\n\ns = 40\nb1 = plt.scatter(X_train[:, 0], X_train[:, 1], c=\"white\", s=s, edgecolors=\"k\")\nb2 = plt.scatter(X_test[:, 0], X_test[:, 1], c=\"blueviolet\", s=s, edgecolors=\"k\")\nc = plt.scatter(X_outliers[:, 0], X_outliers[:, 1], c=\"gold\", s=s, edgecolors=\"k\")\nplt.axis(\"tight\")\nplt.xlim((-5, 5))\nplt.ylim((-5, 5))\nplt.legend(\n    [a.collections[0], b1, b2, c],\n    [\n        \"learned frontier\",\n        \"training observations\",\n        \"new regular observations\",\n        \"new abnormal observations\",\n    ],\n    loc=\"upper left\",\n    prop=matplotlib.font_manager.FontProperties(size=11),\n)\nplt.xlabel(\n    \"errors novel regular: %d/40 ; errors novel abnormal: %d/40\"\n    % (n_error_test, n_error_outliers)\n)\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"Z = clf.decision_function(np.c_[xx.ravel(), yy.ravel()])\nZ = Z.reshape(xx.shape)\n\nplt.title(\"Novelty Detection with LOF\")\nplt.contourf(xx, yy, Z, levels=np.linspace(Z.min(), 0, 7), cmap=plt.cm.PuBu)\na = plt.contour(xx, yy, Z, levels=[0], linewidths=2, colors=\"darkred\")\nplt.contourf(xx, yy, Z, levels=[0, Z.max()], colors=\"palevioletred\")\n\ns = 40\nb1 = plt.scatter(X_train[:, 0], X_train[:, 1], c=\"white\", s=s, edgecolors=\"k\")\nb2 = plt.scatter(X_test[:, 0], X_test[:, 1], c=\"blueviolet\", s=s, edgecolors=\"k\")\nc = plt.scatter(X_outliers[:, 0], X_outliers[:, 1], c=\"gold\", s=s, edgecolors=\"k\")\nplt.axis(\"tight\")\nplt.xlim((-5, 5))\nplt.ylim((-5, 5))\nplt.legend(\n    [a.collections[0], b1, b2, c],\n    [\n        \"learned frontier\",\n        \"training observations\",\n        \"new regular observations\",\n        \"new abnormal observations\",\n    ],\n    loc=\"upper left\",\n    prop=matplotlib.font_manager.FontProperties(size=11),\n)\nplt.xlabel(\n    \"errors novel regular: %d/40 ; errors novel abnormal: %d/40\"\n    % (n_error_test, n_error_outliers)\n)\nplt.show()"}],"source":"scikit-learn/scikit-learn · BSD 3-Clause"},"labex-sklearn-outlier-detection-with-lof":{"intro":"The Local Outlier Factor (LOF) algorithm is an unsupervised machine learning method that is used to detect anomalies in data. It computes the local density deviation of a given data point with respect to its neighbors and considers as outliers the samples that have a substantially lower density than their neighbors.","steps":[{"title":"Import Libraries","body":["We will import numpy and matplotlib for data manipulation and visualization respectively. We will also import LocalOutlierFactor from sklearn.neighbors for outlier detection."],"code":[{"lang":"python","text":"import numpy as np\nimport matplotlib.pyplot as plt\nfrom sklearn.neighbors import LocalOutlierFactor"}]},{"title":"Generate Data with Outliers","body":["We will generate a dataset of 120 data points with 100 inliers and 20 outliers. We will then plot the data to visualize the outliers."],"code":[{"lang":"python","text":"np.random.seed(42)\n\nX_inliers = 0.3 * np.random.randn(100, 2)\nX_inliers = np.r_[X_inliers + 2, X_inliers - 2]\nX_outliers = np.random.uniform(low=-4, high=4, size=(20, 2))\nX = np.r_[X_inliers, X_outliers]\n\nplt.scatter(X[:, 0], X[:, 1], color=\"k\", s=3.0)\nplt.axis(\"tight\")\nplt.xlim((-5, 5))\nplt.ylim((-5, 5))\nplt.xlabel(\"Data points\")\nplt.title(\"Data with Outliers\")\nplt.show()"}]},{"title":"Fit the Model for Outlier Detection","body":["Fit the Model for Outlier Detection","We will use LocalOutlierFactor to fit the model for outlier detection and compute the predicted labels of the training samples."],"code":[{"lang":"python","text":"clf = LocalOutlierFactor(n_neighbors=20, contamination=0.1)\ny_pred = clf.fit_predict(X)\nX_scores = clf.negative_outlier_factor_"}]},{"title":"Plot Results","body":["We will plot the data points with circles whose radius is proportional to the outlier scores."],"code":[{"lang":"python","text":"plt.scatter(X[:, 0], X[:, 1], color=\"k\", s=3.0, label=\"Data points\")\n# plot circles with radius proportional to the outlier scores\nradius = (X_scores.max() - X_scores) / (X_scores.max() - X_scores.min())\nscatter = plt.scatter(\n    X[:, 0],\n    X[:, 1],\n    s=1000 * radius,\n    edgecolors=\"r\",\n    facecolors=\"none\",\n    label=\"Outlier scores\",\n)\nplt.axis(\"tight\")\nplt.xlim((-5, 5))\nplt.ylim((-5, 5))\nplt.xlabel(\"Outlier Detection\")\nplt.legend(\n    handler_map={scatter: HandlerPathCollection(update_func=update_legend_marker_size)}\n)\nplt.title(\"Local Outlier Factor (LOF)\")\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"plt.scatter(X[:, 0], X[:, 1], color=\"k\", s=3.0, label=\"Data points\")\n# plot circles with radius proportional to the outlier scores\nradius = (X_scores.max() - X_scores) / (X_scores.max() - X_scores.min())\nscatter = plt.scatter(\n    X[:, 0],\n    X[:, 1],\n    s=1000 * radius,\n    edgecolors=\"r\",\n    facecolors=\"none\",\n    label=\"Outlier scores\",\n)\nplt.axis(\"tight\")\nplt.xlim((-5, 5))\nplt.ylim((-5, 5))\nplt.xlabel(\"Outlier Detection\")\nplt.legend(\n    handler_map={scatter: HandlerPathCollection(update_func=update_legend_marker_size)}\n)\nplt.title(\"Local Outlier Factor (LOF)\")\nplt.show()"}],"source":"scikit-learn/scikit-learn · BSD 3-Clause"},"labex-sklearn-logistic-regression-model":{"intro":"This lab will provide a step-by-step guide on how to create a Logistic Regression Model using Python's scikit-learn library.","steps":[{"title":"Import necessary libraries","body":["The first step is to import the necessary libraries that will be used in this lab. We will be using numpy, matplotlib, scipy, and sklearn."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\nfrom scipy.special import expit\nfrom sklearn.linear_model import LinearRegression, LogisticRegression"}]},{"title":"Generate a toy dataset","body":["The next step is to generate a toy dataset, which is a straight line with some Gaussian noise. We will be using numpy to generate this dataset."],"code":[{"lang":"python","text":"# Generate a toy dataset, it's just a straight line with some Gaussian noise:\nxmin, xmax = -5, 5\nn_samples = 100\nnp.random.seed(0)\nX = np.random.normal(size=n_samples)\ny = (X > 0).astype(float)\nX[X > 0] *= 4\nX += 0.3 * np.random.normal(size=n_samples)\n\nX = X[:, np.newaxis]"}]},{"title":"Fit the classifier","body":["After generating the dataset, we will fit the classifier using LogisticRegression from scikit-learn."],"code":[{"lang":"python","text":"# Fit the classifier\nclf = LogisticRegression(C=1e5)\nclf.fit(X, y)"}]},{"title":"Plot the result","body":["The final step is to plot the result. We will use matplotlib to create a scatter plot of the example data, and plot the logistic regression model and linear regression model."],"code":[{"lang":"python","text":"# and plot the result\nplt.figure(1, figsize=(4, 3))\nplt.clf()\nplt.scatter(X.ravel(), y, label=\"example data\", color=\"black\", zorder=20)\nX_test = np.linspace(-5, 10, 300)\n\nloss = expit(X_test * clf.coef_ + clf.intercept_).ravel()\nplt.plot(X_test, loss, label=\"Logistic Regression Model\", color=\"red\", linewidth=3)\n\nols = LinearRegression()\nols.fit(X, y)\nplt.plot(\n    X_test,\n    ols.coef_ * X_test + ols.intercept_,\n    label=\"Linear Regression Model\",\n    linewidth=1,\n)\nplt.axhline(0.5, color=\".5\")\n\nplt.ylabel(\"y\")\nplt.xlabel(\"X\")\nplt.xticks(range(-5, 10))\nplt.yticks([0, 0.5, 1])\nplt.ylim(-0.25, 1.25)\nplt.xlim(-4, 10)\nplt.legend(\n    loc=\"lower right\",\n    fontsize=\"small\",\n)\nplt.tight_layout()\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"# and plot the result\nplt.figure(1, figsize=(4, 3))\nplt.clf()\nplt.scatter(X.ravel(), y, label=\"example data\", color=\"black\", zorder=20)\nX_test = np.linspace(-5, 10, 300)\n\nloss = expit(X_test * clf.coef_ + clf.intercept_).ravel()\nplt.plot(X_test, loss, label=\"Logistic Regression Model\", color=\"red\", linewidth=3)\n\nols = LinearRegression()\nols.fit(X, y)\nplt.plot(\n    X_test,\n    ols.coef_ * X_test + ols.intercept_,\n    label=\"Linear Regression Model\",\n    linewidth=1,\n)\nplt.axhline(0.5, color=\".5\")\n\nplt.ylabel(\"y\")\nplt.xlabel(\"X\")\nplt.xticks(range(-5, 10))\nplt.yticks([0, 0.5, 1])\nplt.ylim(-0.25, 1.25)\nplt.xlim(-4, 10)\nplt.legend(\n    loc=\"lower right\",\n    fontsize=\"small\",\n)\nplt.tight_layout()\nplt.show()"}],"source":"scikit-learn/scikit-learn · BSD 3-Clause"},"labex-sklearn-step-by-step-logistic-regression":{"intro":"In this lab, we will explore the sparsity of solutions when L1, L2, and Elastic-Net penalty are used for different values of C. We will use logistic regression to classify 8x8 images of digits into two classes: 0-4 against 5-9. We will visualize the coefficients of the models for varying C.","steps":[{"title":"Import Required Libraries","body":["The first step is to import the necessary libraries. We will need numpy, matplotlib.pyplot, datasets, StandardScaler, and LogisticRegression from sklearn.linear_model."],"code":[{"lang":"python","text":"import numpy as np\nimport matplotlib.pyplot as plt\nfrom sklearn.linear_model import LogisticRegression\nfrom sklearn import datasets\nfrom sklearn.preprocessing import StandardScaler"}]},{"title":"Load the Dataset","body":["We will load the digits dataset using datasets.load_digits(return_X_y=True). We will also standardize the data using StandardScaler().fit_transform(X). The target variable will be binary, where 0-4 will be classified as 0 and 5-9 will be classified as 1."],"code":[{"lang":"python","text":"X, y = datasets.load_digits(return_X_y=True)\nX = StandardScaler().fit_transform(X)\ny = (y > 4).astype(int)"}]},{"title":"Define Regularization Parameter and L1 Ratio","body":["Define Regularization Parameter and L1 Ratio","We will define the regularization parameter C and the L1 ratio l1_ratio for the Elastic-Net penalty. We will set l1_ratio to 0.5."],"code":[{"lang":"python","text":"l1_ratio = 0.5"}]},{"title":"Create Subplots for Visualization","body":["Create Subplots for Visualization","We will create subplots to visualize the coefficients of the models for varying C. We will create 3 rows and 3 columns of subplots."],"code":[{"lang":"python","text":"fig, axes = plt.subplots(3, 3)"}]},{"title":"Train Logistic Regression Models with Different Penalties and Regularization Parameters","body":["Train Logistic Regression Models with Different Penalties and Regularization Parameters","We will train logistic regression models with L1, L2, and Elastic-Net penalties and different values of C. We will increase the tolerance for short training time."],"code":[{"lang":"python","text":"for i, (C, axes_row) in enumerate(zip((1, 0.1, 0.01), axes)):\n    clf_l1_LR = LogisticRegression(C=C, penalty=\"l1\", tol=0.01, solver=\"saga\")\n    clf_l2_LR = LogisticRegression(C=C, penalty=\"l2\", tol=0.01, solver=\"saga\")\n    clf_en_LR = LogisticRegression(C=C, penalty=\"elasticnet\", solver=\"saga\", l1_ratio=l1_ratio, tol=0.01)\n    clf_l1_LR.fit(X, y)\n    clf_l2_LR.fit(X, y)\n    clf_en_LR.fit(X, y)"}]},{"title":"Calculate Sparsity and Scores","body":["We will calculate the sparsity (percentage of zero coefficients) and scores for each model."],"code":[{"lang":"python","text":"coef_l1_LR = clf_l1_LR.coef_.ravel()\n    coef_l2_LR = clf_l2_LR.coef_.ravel()\n    coef_en_LR = clf_en_LR.coef_.ravel()\n\n    sparsity_l1_LR = np.mean(coef_l1_LR == 0) * 100\n    sparsity_l2_LR = np.mean(coef_l2_LR == 0) * 100\n    sparsity_en_LR = np.mean(coef_en_LR == 0) * 100\n\n    score_l1_LR = clf_l1_LR.score(X, y)\n    score_l2_LR = clf_l2_LR.score(X, y)\n    score_en_LR = clf_en_LR.score(X, y)"}]},{"title":"Visualize Coefficients","body":["We will visualize the coefficients of the models for each penalty and C value."],"code":[{"lang":"python","text":"for ax, coefs in zip(axes_row, [coef_l1_LR, coef_en_LR, coef_l2_LR]):\n        ax.imshow(np.abs(coefs.reshape(8, 8)), interpolation='nearest', cmap='binary', vmax=1, vmin=0)\n        ax.set_xticks(())\n        ax.set_yticks(())"}]},{"title":"Set Titles and Labels","body":["We will set the titles and labels for the subplots."],"code":[{"lang":"python","text":"if i == 0:\n        axes_row[0].set_title(\"L1 penalty\")\n        axes_row[1].set_title(\"Elastic-Net\\nl1_ratio = %s\" % l1_ratio)\n        axes_row[2].set_title(\"L2 penalty\")\n\n    axes_row[0].set_ylabel(\"C = %s\" % C)"}]}],"commands":[],"reference":[],"source":"scikit-learn/scikit-learn · BSD 3-Clause"},"labex-sklearn-plot-multinomial-and-one-vs-rest-logistic-re":{"intro":"Logistic regression is a classification algorithm that can be used for binary and multi-class classification problems. In this lab, we will use the scikit-learn library to plot the decision surface of two logistic regression models, namely the multinomial logistic regression and the one-vs-rest logistic regression. We will use a 3-class dataset and plot the decision boundary of the two models to compare their performance.","steps":[{"title":"Import Libraries","body":["We will start by importing the necessary libraries for this lab. We will use the scikit-learn library to generate the dataset and train the logistic regression models, and the matplotlib library to plot the decision boundary."],"code":[{"lang":"python","text":"import numpy as np\nimport matplotlib.pyplot as plt\nfrom sklearn.datasets import make_blobs\nfrom sklearn.linear_model import LogisticRegression\nfrom sklearn.inspection import DecisionBoundaryDisplay"}]},{"title":"Generate Dataset","body":["We will generate a 3-class dataset using the make_blobs function from scikit-learn. We will use 1000 samples and set the centers of the blobs to be at [-5, 0], [0, 1.5], [5, -1]. We will then transform the dataset using a transformation matrix to make the dataset more difficult to classify."],"code":[{"lang":"python","text":"centers = [[-5, 0], [0, 1.5], [5, -1]]\nX, y = make_blobs(n_samples=1000, centers=centers, random_state=40)\ntransformation = [[0.4, 0.2], [-0.4, 1.2]]\nX = np.dot(X, transformation)"}]},{"title":"Train Multinomial Logistic Regression Model","body":["Train Multinomial Logistic Regression Model","We will now train a multinomial logistic regression model using the LogisticRegression function from scikit-learn. We will set the solver to \"sag\", the maximum number of iterations to 100, the random state to 42, and the multi-class option to \"multinomial\". We will then print the training score of the model."],"code":[{"lang":"python","text":"clf = LogisticRegression(\n        solver=\"sag\", max_iter=100, random_state=42, multi_class=\"multinomial\"\n    ).fit(X, y)\n\nprint(\"training score : %.3f (%s)\" % (clf.score(X, y), \"multinomial\"))"}]},{"title":"Plot Decision Boundary of Multinomial Logistic Regression Model","body":["Plot Decision Boundary of Multinomial Logistic Regression Model","We will now plot the decision surface of the multinomial logistic regression model using the DecisionBoundaryDisplay function from scikit-learn. We will set the response method to \"predict\", the colormap to \"plt.cm.Paired\", and plot the training points as well."],"code":[{"lang":"python","text":"_, ax = plt.subplots()\nDecisionBoundaryDisplay.from_estimator(\n        clf, X, response_method=\"predict\", cmap=plt.cm.Paired, ax=ax\n    )\nplt.title(\"Decision surface of LogisticRegression (multinomial)\")\nplt.axis(\"tight\")\n\ncolors = \"bry\"\nfor i, color in zip(clf.classes_, colors):\n        idx = np.where(y == i)\n        plt.scatter(\n            X[idx, 0], X[idx, 1], c=color, cmap=plt.cm.Paired, edgecolor=\"black\", s=20\n        )"}]},{"title":"Train One-vs-Rest Logistic Regression Model","body":["Train One-vs-Rest Logistic Regression Model","We will now train a one-vs-rest logistic regression model using the same parameters as in Step 3, but with the multi-class option set to \"ovr\". We will then print the training score of the model."],"code":[{"lang":"python","text":"clf = LogisticRegression(\n        solver=\"sag\", max_iter=100, random_state=42, multi_class=\"ovr\"\n    ).fit(X, y)\n\nprint(\"training score : %.3f (%s)\" % (clf.score(X, y), \"ovr\"))"}]},{"title":"Plot Decision Boundary of One-vs-Rest Logistic Regression Model","body":["Plot Decision Boundary of One-vs-Rest Logistic Regression Model","We will now plot the decision surface of the one-vs-rest logistic regression model using the same parameters as in Step 4, but plot the hyperplanes corresponding to the three one-vs-rest classifiers as dashed lines."],"code":[{"lang":"python","text":"_, ax = plt.subplots()\nDecisionBoundaryDisplay.from_estimator(\n        clf, X, response_method=\"predict\", cmap=plt.cm.Paired, ax=ax\n    )\nplt.title(\"Decision surface of LogisticRegression (ovr)\")\nplt.axis(\"tight\")\n\ncolors = \"bry\"\nfor i, color in zip(clf.classes_, colors):\n        idx = np.where(y == i)\n        plt.scatter(\n            X[idx, 0], X[idx, 1], c=color, cmap=plt.cm.Paired, edgecolor=\"black\", s=20\n        )\n\nxmin, xmax = plt.xlim()\nymin, ymax = plt.ylim()\ncoef = clf.coef_\nintercept = clf.intercept_\n\ndef plot_hyperplane(c, color):\n        def line(x0):\n            return (-(x0 * coef[c, 0]) - intercept[c]) / coef[c, 1]\n\n        plt.plot([xmin, xmax], [line(xmin), line(xmax)], ls=\"--\", color=color)\n\nfor i, color in zip(clf.classes_, colors):\n        plot_hyperplane(i, color)"}]},{"title":"Visualize Plots","body":["We will now visualize both plots side by side to compare the decision boundaries of the two models."],"code":[{"lang":"python","text":"plt.subplot(1,2,1)\n_, ax = plt.subplots()\nDecisionBoundaryDisplay.from_estimator(\n        clf, X, response_method=\"predict\", cmap=plt.cm.Paired, ax=ax\n    )\nplt.title(\"Multinomial Logistic Regression\")\nplt.axis(\"tight\")\n\ncolors = \"bry\"\nfor i, color in zip(clf.classes_, colors):\n        idx = np.where(y == i)\n        plt.scatter(\n            X[idx, 0], X[idx, 1], c=color, cmap=plt.cm.Paired, edgecolor=\"black\", s=20\n        )\n\nplt.subplot(1,2,2)\n_, ax = plt.subplots()\nDecisionBoundaryDisplay.from_estimator(\n        clf, X, response_method=\"predict\", cmap=plt.cm.Paired, ax=ax\n    )\nplt.title(\"One-vs-Rest Logistic Regression\")\nplt.axis(\"tight\")\n\ncolors = \"bry\"\nfor i, color in zip(clf.classes_, colors):\n        idx = np.where(y == i)\n        plt.scatter(\n            X[idx, 0], X[idx, 1], c=color, cmap=plt.cm.Paired, edgecolor=\"black\", s=20\n        )\n\nxmin, xmax = plt.xlim()\nymin, ymax = plt.ylim()\ncoef = clf.coef_\nintercept = clf.intercept_\n\ndef plot_hyperplane(c, color):\n        def line(x0):\n            return (-(x0 * coef[c, 0]) - intercept[c]) / coef[c, 1]\n\n        plt.plot([xmin, xmax], [line(xmin), line(xmax)], ls=\"--\", color=color)\n\nfor i, color in zip(clf.classes_, colors):\n        plot_hyperplane(i, color)\n\nplt.subplots_adjust(wspace=0.5)\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"plt.subplot(1,2,1)\n_, ax = plt.subplots()\nDecisionBoundaryDisplay.from_estimator(\n        clf, X, response_method=\"predict\", cmap=plt.cm.Paired, ax=ax\n    )\nplt.title(\"Multinomial Logistic Regression\")\nplt.axis(\"tight\")\n\ncolors = \"bry\"\nfor i, color in zip(clf.classes_, colors):\n        idx = np.where(y == i)\n        plt.scatter(\n            X[idx, 0], X[idx, 1], c=color, cmap=plt.cm.Paired, edgecolor=\"black\", s=20\n        )\n\nplt.subplot(1,2,2)\n_, ax = plt.subplots()\nDecisionBoundaryDisplay.from_estimator(\n        clf, X, response_method=\"predict\", cmap=plt.cm.Paired, ax=ax\n    )\nplt.title(\"One-vs-Rest Logistic Regression\")\nplt.axis(\"tight\")\n\ncolors = \"bry\"\nfor i, color in zip(clf.classes_, colors):\n        idx = np.where(y == i)\n        plt.scatter(\n            X[idx, 0], X[idx, 1], c=color, cmap=plt.cm.Paired, edgecolor=\"black\", s=20\n        )\n\nxmin, xmax = plt.xlim()\nymin, ymax = plt.ylim()\ncoef = clf.coef_\nintercept = clf.intercept_\n\ndef plot_hyperplane(c, color):\n        def line(x0):\n            return (-(x0 * coef[c, 0]) - intercept[c]) / coef[c, 1]\n\n        plt.plot([xmin, xmax], [line(xmin), line(xmax)], ls=\"--\", color=color)\n\nfor i, color in zip(clf.classes_, colors):\n        plot_hyperplane(i, color)\n\nplt.subplots_adjust(wspace=0.5)\nplt.show()"}],"source":"scikit-learn/scikit-learn · BSD 3-Clause"},"labex-sklearn-regularization-path-of-l1-logistic-regressio":{"intro":"The L1-Logistic Regression model is a binary classification method that uses L1 regularization to induce sparsity in the model. The regularization path of this model shows the coefficients of the model as regularization strength increases. In this lab, we will use the Iris dataset to train L1-penalized logistic regression models and plot their regularization paths.","steps":[{"title":"Load the Iris dataset","body":["We will load the Iris dataset from the scikit-learn library. The dataset contains four features: Sepal length, Sepal width, Petal length, and Petal width. We will use only the first two features for binary classification."],"code":[{"lang":"python","text":"from sklearn import datasets\n\niris = datasets.load_iris()\nX = iris.data\ny = iris.target\n\nX = X[y != 2] # Use only first two features for binary classification\ny = y[y != 2]\n\nX /= X.max() # Normalize X to speed-up convergence"}]},{"title":"Compute regularization path","body":["We will compute the regularization path by training L1-penalized logistic regression models with different regularization strengths. We will use the liblinear solver, which can efficiently optimize for the Logistic Regression loss with an L1 penalty. We will set a low value for the tolerance to make sure that the model has converged before collecting the coefficients. We will also use warm_start=True, which means that the coefficients of the models are reused to initialize the next model fit to speed-up the computation of the full-path."],"code":[{"lang":"python","text":"import numpy as np\nfrom sklearn import linear_model\nfrom sklearn.svm import l1_min_c\n\ncs = l1_min_c(X, y, loss=\"log\") * np.logspace(0, 10, 16)\n\nclf = linear_model.LogisticRegression(\n    penalty=\"l1\",\n    solver=\"liblinear\",\n    tol=1e-6,\n    max_iter=int(1e6),\n    warm_start=True,\n    intercept_scaling=10000.0,\n)\ncoefs_ = []\nfor c in cs:\n    clf.set_params(C=c)\n    clf.fit(X, y)\n    coefs_.append(clf.coef_.ravel().copy())\n\ncoefs_ = np.array(coefs_)"}]},{"title":"Plot regularization path","body":["We will plot the regularization path by using the coefficients of the trained models. The coefficients will be plotted against the log of the regularization strength. On the left-hand side of the figure (strong regularizers), all the coefficients are exactly 0. When regularization gets progressively looser, coefficients can get non-zero values one after the other."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\n\nplt.plot(np.log10(cs), coefs_, marker=\"o\")\nymin, ymax = plt.ylim()\nplt.xlabel(\"log(C)\")\nplt.ylabel(\"Coefficients\")\nplt.title(\"Logistic Regression Path\")\nplt.axis(\"tight\")\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"import matplotlib.pyplot as plt\n\nplt.plot(np.log10(cs), coefs_, marker=\"o\")\nymin, ymax = plt.ylim()\nplt.xlabel(\"log(C)\")\nplt.ylabel(\"Coefficients\")\nplt.title(\"Logistic Regression Path\")\nplt.axis(\"tight\")\nplt.show()"}],"source":"scikit-learn/scikit-learn · BSD 3-Clause"},"labex-sklearn-comparison-of-covariance-estimators":{"intro":"Covariance estimation is an important task in statistical analysis. In this lab, we will compare two methods of covariance estimation: Ledoit-Wolf and OAS. We will use Gaussian distributed data to compare the estimated MSE of these two methods.","steps":[{"title":"Import Libraries","body":["First, we need to import the necessary libraries for this lab. We will be using numpy for numerical calculations, matplotlib for visualizations, and scikit-learn for covariance estimation."],"code":[{"lang":"python","text":"import numpy as np\nimport matplotlib.pyplot as plt\nfrom scipy.linalg import toeplitz, cholesky\nfrom sklearn.covariance import LedoitWolf, OAS"}]},{"title":"Generate Data","body":["Next, we will generate Gaussian distributed data with a covariance matrix that follows an AR(1) process. We will use toeplitz and cholesky functions from scipy.linalg to generate the covariance matrix."],"code":[{"lang":"python","text":"np.random.seed(0)\n\nn_features = 100\nr = 0.1\nreal_cov = toeplitz(r ** np.arange(n_features))\ncoloring_matrix = cholesky(real_cov)"}]},{"title":"Compute MSE and Shrinkage","body":["We will compare the Ledoit-Wolf and OAS methods using the simulated data. We will compute the mean squared error (MSE) and shrinkage of both methods."],"code":[{"lang":"python","text":"n_samples_range = np.arange(6, 31, 1)\nrepeat = 100\nlw_mse = np.zeros((n_samples_range.size, repeat))\noa_mse = np.zeros((n_samples_range.size, repeat))\nlw_shrinkage = np.zeros((n_samples_range.size, repeat))\noa_shrinkage = np.zeros((n_samples_range.size, repeat))\n\nfor i, n_samples in enumerate(n_samples_range):\n    for j in range(repeat):\n        X = np.dot(np.random.normal(size=(n_samples, n_features)), coloring_matrix.T)\n\n        lw = LedoitWolf(store_precision=False, assume_centered=True)\n        lw.fit(X)\n        lw_mse[i, j] = lw.error_norm(real_cov, scaling=False)\n        lw_shrinkage[i, j] = lw.shrinkage_\n\n        oa = OAS(store_precision=False, assume_centered=True)\n        oa.fit(X)\n        oa_mse[i, j] = oa.error_norm(real_cov, scaling=False)\n        oa_shrinkage[i, j] = oa.shrinkage_"}]},{"title":"Plot Results","body":["Finally, we will plot the results to compare the MSE and shrinkage of the Ledoit-Wolf and OAS methods."],"code":[{"lang":"python","text":"plt.subplot(2, 1, 1)\nplt.errorbar(\n    n_samples_range,\n    lw_mse.mean(1),\n    yerr=lw_mse.std(1),\n    label=\"Ledoit-Wolf\",\n    color=\"navy\",\n    lw=2,\n)\nplt.errorbar(\n    n_samples_range,\n    oa_mse.mean(1),\n    yerr=oa_mse.std(1),\n    label=\"OAS\",\n    color=\"darkorange\",\n    lw=2,\n)\nplt.ylabel(\"Squared error\")\nplt.legend(loc=\"upper right\")\nplt.title(\"Comparison of covariance estimators\")\nplt.xlim(5, 31)\n\nplt.subplot(2, 1, 2)\nplt.errorbar(\n    n_samples_range,\n    lw_shrinkage.mean(1),\n    yerr=lw_shrinkage.std(1),\n    label=\"Ledoit-Wolf\",\n    color=\"navy\",\n    lw=2,\n)\nplt.errorbar(\n    n_samples_range,\n    oa_shrinkage.mean(1),\n    yerr=oa_shrinkage.std(1),\n    label=\"OAS\",\n    color=\"darkorange\",\n    lw=2,\n)\nplt.xlabel(\"n_samples\")\nplt.ylabel(\"Shrinkage\")\nplt.legend(loc=\"lower right\")\nplt.ylim(plt.ylim()[0], 1.0 + (plt.ylim()[1] - plt.ylim()[0]) / 10.0)\nplt.xlim(5, 31)\n\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"plt.subplot(2, 1, 1)\nplt.errorbar(\n    n_samples_range,\n    lw_mse.mean(1),\n    yerr=lw_mse.std(1),\n    label=\"Ledoit-Wolf\",\n    color=\"navy\",\n    lw=2,\n)\nplt.errorbar(\n    n_samples_range,\n    oa_mse.mean(1),\n    yerr=oa_mse.std(1),\n    label=\"OAS\",\n    color=\"darkorange\",\n    lw=2,\n)\nplt.ylabel(\"Squared error\")\nplt.legend(loc=\"upper right\")\nplt.title(\"Comparison of covariance estimators\")\nplt.xlim(5, 31)\n\nplt.subplot(2, 1, 2)\nplt.errorbar(\n    n_samples_range,\n    lw_shrinkage.mean(1),\n    yerr=lw_shrinkage.std(1),\n    label=\"Ledoit-Wolf\",\n    color=\"navy\",\n    lw=2,\n)\nplt.errorbar(\n    n_samples_range,\n    oa_shrinkage.mean(1),\n    yerr=oa_shrinkage.std(1),\n    label=\"OAS\",\n    color=\"darkorange\",\n    lw=2,\n)\nplt.xlabel(\"n_samples\")\nplt.ylabel(\"Shrinkage\")\nplt.legend(loc=\"lower right\")\nplt.ylim(plt.ylim()[0], 1.0 + (plt.ylim()[1] - plt.ylim()[0]) / 10.0)\nplt.xlim(5, 31)\n\nplt.show()"}],"source":"scikit-learn/scikit-learn · BSD 3-Clause"},"labex-sklearn-robust-covariance-estimation-and-mahalanobis":{"intro":"In this lab, we will explore the use of robust covariance estimation with Mahalanobis distances on Gaussian distributed data. Mahalanobis distance is a measure of the distance between a point and a distribution. It is defined as the distance between a point and the mean of the distribution, scaled by the inverse of the covariance matrix of the distribution. For Gaussian distributed data, the Mahalanobis distance can be used to compute the distance of an observation to the mode of the distribution. We will compare the performance of the Minimum Covariance Determinant (MCD) estimator, a robust estimator of covariance, with the standard covariance Maximum Likelihood Estimator (MLE) in calculating the Mahalanobis distances of a contaminated dataset.","steps":[{"title":"Generate Data","body":["First, we generate a dataset of 125 samples and 2 features. Both features are Gaussian distributed with a mean of 0. However, feature 1 has a standard deviation equal to 2 and feature 2 has a standard deviation equal to 1. Next, we replace 25 samples with Gaussian outlier samples where feature 1 has a standard deviation equal to 1 and feature 2 has a standard deviation equal to 7."],"code":[{"lang":"python","text":"import numpy as np\n\n# for consistent results\nnp.random.seed(7)\n\nn_samples = 125\nn_outliers = 25\nn_features = 2\n\n# generate Gaussian data of shape (125, 2)\ngen_cov = np.eye(n_features)\ngen_cov[0, 0] = 2.0\nX = np.dot(np.random.randn(n_samples, n_features), gen_cov)\n# add some outliers\noutliers_cov = np.eye(n_features)\noutliers_cov[np.arange(1, n_features), np.arange(1, n_features)] = 7.0\nX[-n_outliers:] = np.dot(np.random.randn(n_outliers, n_features), outliers_cov)"}]},{"title":"Fit MCD and MLE Covariance Estimators to Data","body":["Fit MCD and MLE Covariance Estimators to Data","We will fit the MCD and MLE based covariance estimators to our data and print the estimated covariance matrices. Note that the estimated variance of feature 2 is much higher with the MLE based estimator (7.5) than that of the MCD robust estimator (1.2). This shows that the MCD based robust estimator is much more resistant to the outlier samples, which were designed to have a much larger variance in feature 2."],"code":[{"lang":"python","text":"from sklearn.covariance import EmpiricalCovariance, MinCovDet\n\n# fit a MCD robust estimator to data\nrobust_cov = MinCovDet().fit(X)\n# fit a MLE estimator to data\nemp_cov = EmpiricalCovariance().fit(X)\nprint(\n    \"Estimated covariance matrix:\\nMCD (Robust):\\n{}\\nMLE:\\n{}\".format(\n        robust_cov.covariance_, emp_cov.covariance_\n    )\n)"}]},{"title":"Plot Contours of Mahalanobis Distances","body":["Plot Contours of Mahalanobis Distances","We will plot contours of the Mahalanobis distances calculated by both methods. Notice that the robust MCD based Mahalanobis distances fit the inlier black points much better, whereas the MLE based distances are more influenced by the outlier red points."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\n\nfig, ax = plt.subplots(figsize=(10, 5))\n# Plot data set\ninlier_plot = ax.scatter(X[:, 0], X[:, 1], color=\"black\", label=\"inliers\")\noutlier_plot = ax.scatter(\n    X[:, 0][-n_outliers:], X[:, 1][-n_outliers:], color=\"red\", label=\"outliers\"\n)\nax.set_xlim(ax.get_xlim()[0], 10.0)\nax.set_title(\"Mahalanobis distances of a contaminated data set\")\n\n# Create meshgrid of feature 1 and feature 2 values\nxx, yy = np.meshgrid(\n    np.linspace(plt.xlim()[0], plt.xlim()[1], 100),\n    np.linspace(plt.ylim()[0], plt.ylim()[1], 100),\n)\nzz = np.c_[xx.ravel(), yy.ravel()]\n# Calculate the MLE based Mahalanobis distances of the meshgrid\nmahal_emp_cov = emp_cov.mahalanobis(zz)\nmahal_emp_cov = mahal_emp_cov.reshape(xx.shape)\nemp_cov_contour = plt.contour(\n    xx, yy, np.sqrt(mahal_emp_cov), cmap=plt.cm.PuBu_r, linestyles=\"dashed\"\n)\n# Calculate the MCD based Mahalanobis distances\nmahal_robust_cov = robust_cov.mahalanobis(zz)\nmahal_robust_cov = mahal_robust_cov.reshape(xx.shape)\nrobust_contour = ax.contour(\n    xx, yy, np.sqrt(mahal_robust_cov), cmap=plt.cm.YlOrBr_r, linestyles=\"dotted\"\n)\n\n# Add legend\nax.legend(\n    [\n        emp_cov_contour.collections[1],\n        robust_contour.collections[1],\n        inlier_plot,\n        outlier_plot,\n    ],\n    [\"MLE dist\", \"MCD dist\", \"inliers\", \"outliers\"],\n    loc=\"upper right\",\n    borderaxespad=0,\n)\n\nplt.show()"}]},{"title":"Compare MLE and MCD Mahalanobis Distances","body":["Compare MLE and MCD Mahalanobis Distances","We will highlight the ability of MCD based Mahalanobis distances to distinguish outliers. We take the cubic root of the Mahalanobis distances, yielding approximately normal distributions. Then, we plot the values of inlier and outlier samples with boxplots. The distribution of outlier samples is more separated from the distribution of inlier samples for robust MCD based Mahalanobis distances."],"code":[{"lang":"python","text":"fig, (ax1, ax2) = plt.subplots(1, 2)\nplt.subplots_adjust(wspace=0.6)\n\n# Calculate cubic root of MLE Mahalanobis distances for samples\nemp_mahal = emp_cov.mahalanobis(X - np.mean(X, 0)) ** (0.33)\n# Plot boxplots\nax1.boxplot([emp_mahal[:-n_outliers], emp_mahal[-n_outliers:]], widths=0.25)\n# Plot individual samples\nax1.plot(\n    np.full(n_samples - n_outliers, 1.26),\n    emp_mahal[:-n_outliers],\n    \"+k\",\n    markeredgewidth=1,\n)\nax1.plot(np.full(n_outliers, 2.26), emp_mahal[-n_outliers:], \"+k\", markeredgewidth=1)\nax1.axes.set_xticklabels((\"inliers\", \"outliers\"), size=15)\nax1.set_ylabel(r\"$\\sqrt[3]{\\rm{(Mahal. dist.)}}$\", size=16)\nax1.set_title(\"Using non-robust estimates\\n(Maximum Likelihood)\")\n\n# Calculate cubic root of MCD Mahalanobis distances for samples\nrobust_mahal = robust_cov.mahalanobis(X - robust_cov.location_) ** (0.33)\n# Plot boxplots\nax2.boxplot([robust_mahal[:-n_outliers], robust_mahal[-n_outliers:]], widths=0.25)\n# Plot individual samples\nax2.plot(\n    np.full(n_samples - n_outliers, 1.26),\n    robust_mahal[:-n_outliers],\n    \"+k\",\n    markeredgewidth=1,\n)\nax2.plot(np.full(n_outliers, 2.26), robust_mahal[-n_outliers:], \"+k\", markeredgewidth=1)\nax2.axes.set_xticklabels((\"inliers\", \"outliers\"), size=15)\nax2.set_ylabel(r\"$\\sqrt[3]{\\rm{(Mahal. dist.)}}$\", size=16)\nax2.set_title(\"Using robust estimates\\n(Minimum Covariance Determinant)\")\n\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"fig, (ax1, ax2) = plt.subplots(1, 2)\nplt.subplots_adjust(wspace=0.6)\n\n# Calculate cubic root of MLE Mahalanobis distances for samples\nemp_mahal = emp_cov.mahalanobis(X - np.mean(X, 0)) ** (0.33)\n# Plot boxplots\nax1.boxplot([emp_mahal[:-n_outliers], emp_mahal[-n_outliers:]], widths=0.25)\n# Plot individual samples\nax1.plot(\n    np.full(n_samples - n_outliers, 1.26),\n    emp_mahal[:-n_outliers],\n    \"+k\",\n    markeredgewidth=1,\n)\nax1.plot(np.full(n_outliers, 2.26), emp_mahal[-n_outliers:], \"+k\", markeredgewidth=1)\nax1.axes.set_xticklabels((\"inliers\", \"outliers\"), size=15)\nax1.set_ylabel(r\"$\\sqrt[3]{\\rm{(Mahal. dist.)}}$\", size=16)\nax1.set_title(\"Using non-robust estimates\\n(Maximum Likelihood)\")\n\n# Calculate cubic root of MCD Mahalanobis distances for samples\nrobust_mahal = robust_cov.mahalanobis(X - robust_cov.location_) ** (0.33)\n# Plot boxplots\nax2.boxplot([robust_mahal[:-n_outliers], robust_mahal[-n_outliers:]], widths=0.25)\n# Plot individual samples\nax2.plot(\n    np.full(n_samples - n_outliers, 1.26),\n    robust_mahal[:-n_outliers],\n    \"+k\",\n    markeredgewidth=1,\n)\nax2.plot(np.full(n_outliers, 2.26), robust_mahal[-n_outliers:], \"+k\", markeredgewidth=1)\nax2.axes.set_xticklabels((\"inliers\", \"outliers\"), size=15)\nax2.set_ylabel(r\"$\\sqrt[3]{\\rm{(Mahal. dist.)}}$\", size=16)\nax2.set_title(\"Using robust estimates\\n(Minimum Covariance Determinant)\")\n\nplt.show()"}],"source":"scikit-learn/scikit-learn · BSD 3-Clause"},"labex-sklearn-manifold-learning-on-spherical-data":{"intro":"Manifold learning is a subfield of machine learning that deals with learning the underlying structure of high-dimensional data. In this lab, we will apply different manifold learning techniques on a spherical dataset. We will use dimensionality reduction to gain some intuition regarding the manifold learning methods.","steps":[{"title":"Import Libraries","body":["We will begin by importing the necessary libraries. We will be using scikit-learn, matplotlib, and numpy."],"code":[{"lang":"python","text":"from time import time\nimport numpy as np\nimport matplotlib.pyplot as plt\nfrom matplotlib.ticker import NullFormatter\nfrom sklearn import manifold\nfrom sklearn.utils import check_random_state\n\nimport mpl_toolkits.mplot3d"}]},{"title":"Create Spherical Dataset","body":["Next, we will create a spherical dataset. We will create a sphere, sever the poles, and a thin slice down its side. This will enable the manifold learning techniques to 'spread it open' whilst projecting it onto two dimensions."],"code":[{"lang":"python","text":"n_neighbors = 10\nn_samples = 1000\n\nrandom_state = check_random_state(0)\np = random_state.rand(n_samples) * (2 * np.pi - 0.55)\nt = random_state.rand(n_samples) * np.pi\n\nindices = (t < (np.pi - (np.pi / 8))) & (t > ((np.pi / 8)))\ncolors = p[indices]\nx, y, z = (\n    np.sin(t[indices]) * np.cos(p[indices]),\n    np.sin(t[indices]) * np.sin(p[indices]),\n    np.cos(t[indices]),\n)\n\nfig = plt.figure(figsize=(15, 8))\nplt.suptitle(\n    \"Manifold Learning with %i points, %i neighbors\" % (1000, n_neighbors), fontsize=14\n)\n\nax = fig.add_subplot(251, projection=\"3d\")\nax.scatter(x, y, z, c=p[indices], cmap=plt.cm.rainbow)\nax.view_init(40, -10)\n\nsphere_data = np.array([x, y, z]).T"}]},{"title":"Perform Locally Linear Embedding Manifold Learning","body":["Perform Locally Linear Embedding Manifold Learning","We will now perform Locally Linear Embedding (LLE) manifold learning. LLE is a powerful technique that can unfold complicated manifolds with a small number of samples. We will use four variations of LLE and compare their results."],"code":[{"lang":"python","text":"methods = [\"standard\", \"ltsa\", \"hessian\", \"modified\"]\nlabels = [\"LLE\", \"LTSA\", \"Hessian LLE\", \"Modified LLE\"]\n\nfor i, method in enumerate(methods):\n    t0 = time()\n    trans_data = (\n        manifold.LocallyLinearEmbedding(\n            n_neighbors=n_neighbors, n_components=2, method=method\n        )\n        .fit_transform(sphere_data)\n        .T\n    )\n    t1 = time()\n    print(\"%s: %.2g sec\" % (methods[i], t1 - t0))\n\n    ax = fig.add_subplot(252 + i)\n    plt.scatter(trans_data[0], trans_data[1], c=colors, cmap=plt.cm.rainbow)\n    plt.title(\"%s (%.2g sec)\" % (labels[i], t1 - t0))\n    ax.xaxis.set_major_formatter(NullFormatter())\n    ax.yaxis.set_major_formatter(NullFormatter())\n    plt.axis(\"tight\")"}]},{"title":"Perform Isomap Manifold Learning","body":["Perform Isomap Manifold Learning","Next, we will perform Isomap manifold learning. Isomap is a nonlinear dimensionality reduction technique that seeks a lower-dimensional embedding of the data that maintains geodesic distances between all pairs of points."],"code":[{"lang":"python","text":"t0 = time()\ntrans_data = (\n    manifold.Isomap(n_neighbors=n_neighbors, n_components=2)\n    .fit_transform(sphere_data)\n    .T\n)\nt1 = time()\nprint(\"%s: %.2g sec\" % (\"ISO\", t1 - t0))\n\nax = fig.add_subplot(257)\nplt.scatter(trans_data[0], trans_data[1], c=colors, cmap=plt.cm.rainbow)\nplt.title(\"%s (%.2g sec)\" % (\"Isomap\", t1 - t0))\nax.xaxis.set_major_formatter(NullFormatter())\nax.yaxis.set_major_formatter(NullFormatter())\nplt.axis(\"tight\")"}]},{"title":"Perform Multi-dimensional Scaling (MDS)","body":["Perform Multi-dimensional Scaling (MDS)","We will now perform Multi-dimensional Scaling (MDS) manifold learning. MDS is a technique that seeks a low-dimensional representation of the data in which the distances between points respect the distances in the original high-dimensional space."],"code":[{"lang":"python","text":"t0 = time()\nmds = manifold.MDS(2, max_iter=100, n_init=1, normalized_stress=\"auto\")\ntrans_data = mds.fit_transform(sphere_data).T\nt1 = time()\nprint(\"MDS: %.2g sec\" % (t1 - t0))\n\nax = fig.add_subplot(258)\nplt.scatter(trans_data[0], trans_data[1], c=colors, cmap=plt.cm.rainbow)\nplt.title(\"MDS (%.2g sec)\" % (t1 - t0))\nax.xaxis.set_major_formatter(NullFormatter())\nax.yaxis.set_major_formatter(NullFormatter())\nplt.axis(\"tight\")"}]},{"title":"Perform Spectral Embedding","body":["Next, we will perform Spectral Embedding manifold learning. Spectral Embedding is a technique that seeks a low-dimensional representation of the data that preserves pairwise distances between the points."],"code":[{"lang":"python","text":"t0 = time()\nse = manifold.SpectralEmbedding(n_components=2, n_neighbors=n_neighbors)\ntrans_data = se.fit_transform(sphere_data).T\nt1 = time()\nprint(\"Spectral Embedding: %.2g sec\" % (t1 - t0))\n\nax = fig.add_subplot(259)\nplt.scatter(trans_data[0], trans_data[1], c=colors, cmap=plt.cm.rainbow)\nplt.title(\"Spectral Embedding (%.2g sec)\" % (t1 - t0))\nax.xaxis.set_major_formatter(NullFormatter())\nax.yaxis.set_major_formatter(NullFormatter())\nplt.axis(\"tight\")"}]},{"title":"Perform t-distributed Stochastic Neighbor Embedding (t-SNE)","body":["Perform t-distributed Stochastic Neighbor Embedding (t-SNE)","Finally, we will perform t-distributed Stochastic Neighbor Embedding (t-SNE) manifold learning. t-SNE is a technique that seeks a low-dimensional representation of the data that preserves local distances between the points."],"code":[{"lang":"python","text":"t0 = time()\ntsne = manifold.TSNE(n_components=2, random_state=0)\ntrans_data = tsne.fit_transform(sphere_data).T\nt1 = time()\nprint(\"t-SNE: %.2g sec\" % (t1 - t0))\n\nax = fig.add_subplot(2, 5, 10)\nplt.scatter(trans_data[0], trans_data[1], c=colors, cmap=plt.cm.rainbow)\nplt.title(\"t-SNE (%.2g sec)\" % (t1 - t0))\nax.xaxis.set_major_formatter(NullFormatter())\nax.yaxis.set_major_formatter(NullFormatter())\nplt.axis(\"tight\")\n\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"t0 = time()\ntsne = manifold.TSNE(n_components=2, random_state=0)\ntrans_data = tsne.fit_transform(sphere_data).T\nt1 = time()\nprint(\"t-SNE: %.2g sec\" % (t1 - t0))\n\nax = fig.add_subplot(2, 5, 10)\nplt.scatter(trans_data[0], trans_data[1], c=colors, cmap=plt.cm.rainbow)\nplt.title(\"t-SNE (%.2g sec)\" % (t1 - t0))\nax.xaxis.set_major_formatter(NullFormatter())\nax.yaxis.set_major_formatter(NullFormatter())\nplt.axis(\"tight\")\n\nplt.show()"}],"source":"scikit-learn/scikit-learn · BSD 3-Clause"},"labex-sklearn-map-data-to-a-normal-distribution":{"intro":"This lab demonstrates how to use the Box-Cox and Yeo-Johnson transforms through PowerTransformer to map data from various distributions to a normal distribution.","steps":[{"title":"Import Libraries","body":["First, we need to import the necessary libraries: numpy, matplotlib, PowerTransformer, QuantileTransformer, and train_test_split."],"code":[{"lang":"python","text":"import numpy as np\nimport matplotlib.pyplot as plt\nfrom sklearn.preprocessing import PowerTransformer\nfrom sklearn.preprocessing import QuantileTransformer\nfrom sklearn.model_selection import train_test_split"}]},{"title":"Set Constants","body":["We will set the constants for the number of samples, font size, and bins."],"code":[{"lang":"python","text":"N_SAMPLES = 1000\nFONT_SIZE = 6\nBINS = 30"}]},{"title":"Create Random Distributions","body":["We will generate six different probability distributions: Lognormal, Chi-squared, Weibull, Gaussian, Uniform, and Bimodal."],"code":[{"lang":"python","text":"rng = np.random.RandomState(304)\nbc = PowerTransformer(method=\"box-cox\")\nyj = PowerTransformer(method=\"yeo-johnson\")\nqt = QuantileTransformer(n_quantiles=500, output_distribution=\"normal\", random_state=rng)\nsize = (N_SAMPLES, 1)\n\n# lognormal distribution\nX_lognormal = rng.lognormal(size=size)\n\n# chi-squared distribution\ndf = 3\nX_chisq = rng.chisquare(df=df, size=size)\n\n# weibull distribution\na = 50\nX_weibull = rng.weibull(a=a, size=size)\n\n# gaussian distribution\nloc = 100\nX_gaussian = rng.normal(loc=loc, size=size)\n\n# uniform distribution\nX_uniform = rng.uniform(low=0, high=1, size=size)\n\n# bimodal distribution\nloc_a, loc_b = 100, 105\nX_a, X_b = rng.normal(loc=loc_a, size=size), rng.normal(loc=loc_b, size=size)\nX_bimodal = np.concatenate([X_a, X_b], axis=0)"}]},{"title":"Create Plots","body":["Now, we will create plots for each of the six distributions, showing the original distribution and the transformed distribution using Box-Cox, Yeo-Johnson, and Quantile Transformer."],"code":[{"lang":"python","text":"distributions = [\n    (\"Lognormal\", X_lognormal),\n    (\"Chi-squared\", X_chisq),\n    (\"Weibull\", X_weibull),\n    (\"Gaussian\", X_gaussian),\n    (\"Uniform\", X_uniform),\n    (\"Bimodal\", X_bimodal),\n]\n\ncolors = [\"#D81B60\", \"#0188FF\", \"#FFC107\", \"#B7A2FF\", \"#000000\", \"#2EC5AC\"]\n\nfig, axes = plt.subplots(nrows=8, ncols=3, figsize=plt.figaspect(2))\naxes = axes.flatten()\naxes_idxs = [\n    (0, 3, 6, 9),\n    (1, 4, 7, 10),\n    (2, 5, 8, 11),\n    (12, 15, 18, 21),\n    (13, 16, 19, 22),\n    (14, 17, 20, 23),\n]\naxes_list = [(axes[i], axes[j], axes[k], axes[l]) for (i, j, k, l) in axes_idxs]\n\nfor distribution, color, axes in zip(distributions, colors, axes_list):\n    name, X = distribution\n    X_train, X_test = train_test_split(X, test_size=0.5)\n\n    # perform power transforms and quantile transform\n    X_trans_bc = bc.fit(X_train).transform(X_test)\n    lmbda_bc = round(bc.lambdas_[0], 2)\n    X_trans_yj = yj.fit(X_train).transform(X_test)\n    lmbda_yj = round(yj.lambdas_[0], 2)\n    X_trans_qt = qt.fit(X_train).transform(X_test)\n\n    ax_original, ax_bc, ax_yj, ax_qt = axes\n\n    ax_original.hist(X_train, color=color, bins=BINS)\n    ax_original.set_title(name, fontsize=FONT_SIZE)\n    ax_original.tick_params(axis=\"both\", which=\"major\", labelsize=FONT_SIZE)\n\n    for ax, X_trans, meth_name, lmbda in zip(\n        (ax_bc, ax_yj, ax_qt),\n        (X_trans_bc, X_trans_yj, X_trans_qt),\n        (\"Box-Cox\", \"Yeo-Johnson\", \"Quantile transform\"),\n        (lmbda_bc, lmbda_yj, None),\n    ):\n        ax.hist(X_trans, color=color, bins=BINS)\n        title = \"After {}\".format(meth_name)"}]}],"commands":[],"reference":[{"path":"reference.py","text":"distributions = [\n    (\"Lognormal\", X_lognormal),\n    (\"Chi-squared\", X_chisq),\n    (\"Weibull\", X_weibull),\n    (\"Gaussian\", X_gaussian),\n    (\"Uniform\", X_uniform),\n    (\"Bimodal\", X_bimodal),\n]\n\ncolors = [\"#D81B60\", \"#0188FF\", \"#FFC107\", \"#B7A2FF\", \"#000000\", \"#2EC5AC\"]\n\nfig, axes = plt.subplots(nrows=8, ncols=3, figsize=plt.figaspect(2))\naxes = axes.flatten()\naxes_idxs = [\n    (0, 3, 6, 9),\n    (1, 4, 7, 10),\n    (2, 5, 8, 11),\n    (12, 15, 18, 21),\n    (13, 16, 19, 22),\n    (14, 17, 20, 23),\n]\naxes_list = [(axes[i], axes[j], axes[k], axes[l]) for (i, j, k, l) in axes_idxs]\n\nfor distribution, color, axes in zip(distributions, colors, axes_list):\n    name, X = distribution\n    X_train, X_test = train_test_split(X, test_size=0.5)\n\n    # perform power transforms and quantile transform\n    X_trans_bc = bc.fit(X_train).transform(X_test)\n    lmbda_bc = round(bc.lambdas_[0], 2)\n    X_trans_yj = yj.fit(X_train).transform(X_test)\n    lmbda_yj = round(yj.lambdas_[0], 2)\n    X_trans_qt = qt.fit(X_train).transform(X_test)\n\n    ax_original, ax_bc, ax_yj, ax_qt = axes\n\n    ax_original.hist(X_train, color=color, bins=BINS)\n    ax_original.set_title(name, fontsize=FONT_SIZE)\n    ax_original.tick_params(axis=\"both\", which=\"major\", labelsize=FONT_SIZE)\n\n    for ax, X_trans, meth_name, lmbda in zip(\n        (ax_bc, ax_yj, ax_qt),\n        (X_trans_bc, X_trans_yj, X_trans_qt),\n        (\"Box-Cox\", \"Yeo-Johnson\", \"Quantile transform\"),\n        (lmbda_bc, lmbda_yj, None),\n    ):\n        ax.hist(X_trans, color=color, bins=BINS)\n        title = \"After {}\".format(meth_name)"}],"source":"scikit-learn/scikit-learn · BSD 3-Clause"},"labex-sklearn-visualize-high-dimensional-data-with-mds":{"intro":"Multi-dimensional scaling (MDS) is a technique used to visualize high-dimensional data in a lower dimensional space (usually 2D or 3D) while preserving the pairwise distances between the data points as much as possible. It is often used in exploratory data analysis and visualization.","steps":[{"title":"Import Libraries","body":["First, we need to import the necessary libraries. We will be using numpy, matplotlib, scikit-learn, and PCA from scikit-learn."],"code":[{"lang":"python","text":"import numpy as np\nfrom matplotlib import pyplot as plt\nfrom matplotlib.collections import LineCollection\nfrom sklearn import manifold\nfrom sklearn.metrics import euclidean_distances\nfrom sklearn.decomposition import PCA"}]},{"title":"Generate Data","body":["Next, we will generate a noisy dataset using numpy. We will generate 20 samples with 2 features each."],"code":[{"lang":"python","text":"EPSILON = np.finfo(np.float32).eps\nn_samples = 20\nseed = np.random.RandomState(seed=3)\nX_true = seed.randint(0, 20, 2 * n_samples).astype(float)\nX_true = X_true.reshape((n_samples, 2))\n# Center the data\nX_true -= X_true.mean()"}]},{"title":"Add Noise to Data","body":["We will then add noise to the pairwise distances between the data points using numpy."],"code":[{"lang":"python","text":"similarities = euclidean_distances(X_true)\n\n# Add noise to the similarities\nnoise = np.random.rand(n_samples, n_samples)\nnoise = noise + noise.T\nnoise[np.arange(noise.shape[0]), np.arange(noise.shape[0])] = 0\nsimilarities += noise"}]},{"title":"Perform MDS","body":["We will then perform MDS on the noisy dataset using scikit-learn's MDS class. We will use the precomputed dissimilarity option since we have already calculated the pairwise distances between the data points. We will also set the number of components to 2 for 2D visualization."],"code":[{"lang":"python","text":"mds = manifold.MDS(\n    n_components=2,\n    max_iter=3000,\n    eps=1e-9,\n    random_state=seed,\n    dissimilarity=\"precomputed\",\n    n_jobs=1,\n    normalized_stress=\"auto\",\n)\npos = mds.fit(similarities).embedding_"}]},{"title":"Perform Non-Metric MDS","body":["We will also perform non-metric MDS on the same dataset for comparison. We will use the same options as MDS, except we will set the metric option to False."],"code":[{"lang":"python","text":"nmds = manifold.MDS(\n    n_components=2,\n    metric=False,\n    max_iter=3000,\n    eps=1e-12,\n    dissimilarity=\"precomputed\",\n    random_state=seed,\n    n_jobs=1,\n    n_init=1,\n    normalized_stress=\"auto\",\n)\nnpos = nmds.fit_transform(similarities, init=pos)"}]},{"title":"Rescale and Rotate Data","body":["We will then rescale and rotate the data for visualization using PCA from scikit-learn."],"code":[{"lang":"python","text":"# Rescale the data\npos *= np.sqrt((X_true**2).sum()) / np.sqrt((pos**2).sum())\nnpos *= np.sqrt((X_true**2).sum()) / np.sqrt((npos**2).sum())\n\n# Rotate the data\nclf = PCA(n_components=2)\nX_true = clf.fit_transform(X_true)\npos = clf.fit_transform(pos)\nnpos = clf.fit_transform(npos)"}]},{"title":"Visualize Results","body":["Finally, we will visualize the results using matplotlib. We will plot the true position of the data points, the position of the data points using MDS, and the position of the data points using non-metric MDS. We will also plot the pairwise distances between the data points using LineCollection from matplotlib."],"code":[{"lang":"python","text":"fig = plt.figure(1)\nax = plt.axes([0.0, 0.0, 1.0, 1.0])\n\ns = 100\nplt.scatter(X_true[:, 0], X_true[:, 1], color=\"navy\", s=s, lw=0, label=\"True Position\")\nplt.scatter(pos[:, 0], pos[:, 1], color=\"turquoise\", s=s, lw=0, label=\"MDS\")\nplt.scatter(npos[:, 0], npos[:, 1], color=\"darkorange\", s=s, lw=0, label=\"NMDS\")\nplt.legend(scatterpoints=1, loc=\"best\", shadow=False)\n\nsimilarities = similarities.max() / (similarities + EPSILON) * 100\nnp.fill_diagonal(similarities, 0)\n# Plot the edges\nstart_idx, end_idx = np.where(pos)\n# a sequence of (*line0*, *line1*, *line2*), where::\n#            linen = (x0, y0), (x1, y1), ... (xm, ym)\nsegments = [\n    [X_true[i, :], X_true[j, :]] for i in range(len(pos)) for j in range(len(pos))\n]\nvalues = np.abs(similarities)\nlc = LineCollection(\n    segments, zorder=0, cmap=plt.cm.Blues, norm=plt.Normalize(0, values.max())\n)\nlc.set_array(similarities.flatten())\nlc.set_linewidths(np.full(len(segments), 0.5))\nax.add_collection(lc)\n\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"fig = plt.figure(1)\nax = plt.axes([0.0, 0.0, 1.0, 1.0])\n\ns = 100\nplt.scatter(X_true[:, 0], X_true[:, 1], color=\"navy\", s=s, lw=0, label=\"True Position\")\nplt.scatter(pos[:, 0], pos[:, 1], color=\"turquoise\", s=s, lw=0, label=\"MDS\")\nplt.scatter(npos[:, 0], npos[:, 1], color=\"darkorange\", s=s, lw=0, label=\"NMDS\")\nplt.legend(scatterpoints=1, loc=\"best\", shadow=False)\n\nsimilarities = similarities.max() / (similarities + EPSILON) * 100\nnp.fill_diagonal(similarities, 0)\n# Plot the edges\nstart_idx, end_idx = np.where(pos)\n# a sequence of (*line0*, *line1*, *line2*), where::\n#            linen = (x0, y0), (x1, y1), ... (xm, ym)\nsegments = [\n    [X_true[i, :], X_true[j, :]] for i in range(len(pos)) for j in range(len(pos))\n]\nvalues = np.abs(similarities)\nlc = LineCollection(\n    segments, zorder=0, cmap=plt.cm.Blues, norm=plt.Normalize(0, values.max())\n)\nlc.set_array(similarities.flatten())\nlc.set_linewidths(np.full(len(segments), 0.5))\nax.add_collection(lc)\n\nplt.show()"}],"source":"scikit-learn/scikit-learn · BSD 3-Clause"},"labex-sklearn-mean-shift-clustering-algorithm":{"intro":"This lab will guide you through the process of implementing the Mean-Shift Clustering Algorithm using the Scikit-learn library in Python. You will learn how to generate sample data, compute clustering with MeanShift, and plot the results.","steps":[{"title":"Import Required Libraries","body":["First, we need to import the required libraries: numpy, sklearn.cluster, sklearn.datasets, and matplotlib.pyplot."],"code":[{"lang":"python","text":"import numpy as np\nfrom sklearn.cluster import MeanShift, estimate_bandwidth\nfrom sklearn.datasets import make_blobs\nimport matplotlib.pyplot as plt"}]},{"title":"Generate Sample Data","body":["Next, we will generate sample data using the make_blobs function from the sklearn.datasets module. We will create a dataset with 10,000 samples and three clusters with centers at [[1, 1], [-1, -1], [1, -1]] and a standard deviation of 0.6."],"code":[{"lang":"python","text":"centers = [[1, 1], [-1, -1], [1, -1]]\nX, _ = make_blobs(n_samples=10000, centers=centers, cluster_std=0.6)"}]},{"title":"Compute Clustering with MeanShift","body":["Compute Clustering with MeanShift","Now we will compute clustering using the Mean-Shift algorithm with the MeanShift class from the sklearn.cluster module. We will use the estimate_bandwidth function to automatically detect the bandwidth parameter, which represents the size of the region of influence for each point."],"code":[{"lang":"python","text":"bandwidth = estimate_bandwidth(X, quantile=0.2, n_samples=500)\nms = MeanShift(bandwidth=bandwidth, bin_seeding=True)\nms.fit(X)\nlabels = ms.labels_\ncluster_centers = ms.cluster_centers_"}]},{"title":"Plot Results","body":["Finally, we will plot the results using the matplotlib.pyplot library. We will use different colors and markers for each cluster, and we will also plot the cluster centers."],"code":[{"lang":"python","text":"plt.figure(1)\nplt.clf()\n\ncolors = [\"#dede00\", \"#377eb8\", \"#f781bf\"]\nmarkers = [\"x\", \"o\", \"^\"]\n\nfor k, col in zip(range(n_clusters_), colors):\n    my_members = labels == k\n    cluster_center = cluster_centers[k]\n    plt.plot(X[my_members, 0], X[my_members, 1], markers[k], color=col)\n    plt.plot(\n        cluster_center[0],\n        cluster_center[1],\n        markers[k],\n        markerfacecolor=col,\n        markeredgecolor=\"k\",\n        markersize=14,\n    )\nplt.title(\"Estimated number of clusters: %d\" % n_clusters_)\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"plt.figure(1)\nplt.clf()\n\ncolors = [\"#dede00\", \"#377eb8\", \"#f781bf\"]\nmarkers = [\"x\", \"o\", \"^\"]\n\nfor k, col in zip(range(n_clusters_), colors):\n    my_members = labels == k\n    cluster_center = cluster_centers[k]\n    plt.plot(X[my_members, 0], X[my_members, 1], markers[k], color=col)\n    plt.plot(\n        cluster_center[0],\n        cluster_center[1],\n        markers[k],\n        markerfacecolor=col,\n        markeredgecolor=\"k\",\n        markersize=14,\n    )\nplt.title(\"Estimated number of clusters: %d\" % n_clusters_)\nplt.show()"}],"source":"scikit-learn/scikit-learn · BSD 3-Clause"},"labex-sklearn-comparing-k-means-and-minibatchkmeans":{"intro":"In this lab, we will compare two clustering algorithms: K-Means and MiniBatchKMeans. K-Means is a popular clustering algorithm that is widely used in machine learning. MiniBatchKMeans is a variant of K-Means that is faster but gives slightly different results. We will cluster a set of data using both algorithms and plot the results. We will also plot the points that are labeled differently between the two algorithms.","steps":[{"title":"Generate the Data","body":["We start by generating the blobs of data to be clustered."],"code":[{"lang":"python","text":"import numpy as np\nfrom sklearn.datasets import make_blobs\n\nnp.random.seed(0)\n\nbatch_size = 45\ncenters = [[1, 1], [-1, -1], [1, -1]]\nn_clusters = len(centers)\nX, labels_true = make_blobs(n_samples=3000, centers=centers, cluster_std=0.7)"}]},{"title":"Compute Clustering with KMeans","body":["Compute Clustering with KMeans","We will compute clustering with KMeans."],"code":[{"lang":"python","text":"import time\nfrom sklearn.cluster import KMeans\n\nk_means = KMeans(init=\"k-means++\", n_clusters=3, n_init=10)\nt0 = time.time()\nk_means.fit(X)\nt_batch = time.time() - t0"}]},{"title":"Compute Clustering with MiniBatchKMeans","body":["Compute Clustering with MiniBatchKMeans","We will compute clustering with MiniBatchKMeans."],"code":[{"lang":"python","text":"from sklearn.cluster import MiniBatchKMeans\n\nmbk = MiniBatchKMeans(\n    init=\"k-means++\",\n    n_clusters=3,\n    batch_size=batch_size,\n    n_init=10,\n    max_no_improvement=10,\n    verbose=0,\n)\nt0 = time.time()\nmbk.fit(X)\nt_mini_batch = time.time() - t0"}]},{"title":"Establishing Parity Between Clusters","body":["Establishing Parity Between Clusters","We want to have the same color for the same cluster from both the MiniBatchKMeans and the KMeans algorithm. Let's pair the cluster centers per closest one."],"code":[{"lang":"python","text":"from sklearn.metrics.pairwise import pairwise_distances_argmin\n\nk_means_cluster_centers = k_means.cluster_centers_\norder = pairwise_distances_argmin(k_means.cluster_centers_, mbk.cluster_centers_)\nmbk_means_cluster_centers = mbk.cluster_centers_[order]\n\nk_means_labels = pairwise_distances_argmin(X, k_means_cluster_centers)\nmbk_means_labels = pairwise_distances_argmin(X, mbk_means_cluster_centers)"}]},{"title":"Plotting the Results","body":[],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\n\nfig = plt.figure(figsize=(8, 3))\nfig.subplots_adjust(left=0.02, right=0.98, bottom=0.05, top=0.9)\ncolors = [\"#4EACC5\", \"#FF9C34\", \"#4E9A06\"]\n\n# KMeans\nax = fig.add_subplot(1, 3, 1)\nfor k, col in zip(range(n_clusters), colors):\n    my_members = k_means_labels == k\n    cluster_center = k_means_cluster_centers[k]\n    ax.plot(X[my_members, 0], X[my_members, 1], \"w\", markerfacecolor=col, marker=\".\")\n    ax.plot(\n        cluster_center[0],\n        cluster_center[1],\n        \"o\",\n        markerfacecolor=col,\n        markeredgecolor=\"k\",\n        markersize=6,\n    )\nax.set_title(\"KMeans\")\nax.set_xticks(())\nax.set_yticks(())\nplt.text(-3.5, 1.8, \"train time: %.2fs\\ninertia: %f\" % (t_batch, k_means.inertia_))\n\n# MiniBatchKMeans\nax = fig.add_subplot(1, 3, 2)\nfor k, col in zip(range(n_clusters), colors):\n    my_members = mbk_means_labels == k\n    cluster_center = mbk_means_cluster_centers[k]\n    ax.plot(X[my_members, 0], X[my_members, 1], \"w\", markerfacecolor=col, marker=\".\")\n    ax.plot(\n        cluster_center[0],\n        cluster_center[1],\n        \"o\",\n        markerfacecolor=col,\n        markeredgecolor=\"k\",\n        markersize=6,\n    )\nax.set_title(\"MiniBatchKMeans\")\nax.set_xticks(())\nax.set_yticks(())\nplt.text(-3.5, 1.8, \"train time: %.2fs\\ninertia: %f\" % (t_mini_batch, mbk.inertia_))\n\n# Initialize the different array to all False\ndifferent = mbk_means_labels == 4\nax = fig.add_subplot(1, 3, 3)"}]}],"commands":[],"reference":[{"path":"reference.py","text":"import matplotlib.pyplot as plt\n\nfig = plt.figure(figsize=(8, 3))\nfig.subplots_adjust(left=0.02, right=0.98, bottom=0.05, top=0.9)\ncolors = [\"#4EACC5\", \"#FF9C34\", \"#4E9A06\"]\n\n# KMeans\nax = fig.add_subplot(1, 3, 1)\nfor k, col in zip(range(n_clusters), colors):\n    my_members = k_means_labels == k\n    cluster_center = k_means_cluster_centers[k]\n    ax.plot(X[my_members, 0], X[my_members, 1], \"w\", markerfacecolor=col, marker=\".\")\n    ax.plot(\n        cluster_center[0],\n        cluster_center[1],\n        \"o\",\n        markerfacecolor=col,\n        markeredgecolor=\"k\",\n        markersize=6,\n    )\nax.set_title(\"KMeans\")\nax.set_xticks(())\nax.set_yticks(())\nplt.text(-3.5, 1.8, \"train time: %.2fs\\ninertia: %f\" % (t_batch, k_means.inertia_))\n\n# MiniBatchKMeans\nax = fig.add_subplot(1, 3, 2)\nfor k, col in zip(range(n_clusters), colors):\n    my_members = mbk_means_labels == k\n    cluster_center = mbk_means_cluster_centers[k]\n    ax.plot(X[my_members, 0], X[my_members, 1], \"w\", markerfacecolor=col, marker=\".\")\n    ax.plot(\n        cluster_center[0],\n        cluster_center[1],\n        \"o\",\n        markerfacecolor=col,\n        markeredgecolor=\"k\",\n        markersize=6,\n    )\nax.set_title(\"MiniBatchKMeans\")\nax.set_xticks(())\nax.set_yticks(())\nplt.text(-3.5, 1.8, \"train time: %.2fs\\ninertia: %f\" % (t_mini_batch, mbk.inertia_))\n\n# Initialize the different array to all False\ndifferent = mbk_means_labels == 4\nax = fig.add_subplot(1, 3, 3)"}],"source":"scikit-learn/scikit-learn · BSD 3-Clause"},"labex-sklearn-impute-missing-data":{"intro":"This lab demonstrates how to impute missing data in a dataset using different techniques in scikit-learn. The dataset used here are the diabetes dataset with 10 features and California housing dataset with 8 features. The missing values can be replaced by the mean, the median, or the most frequent value using SimpleImputer. This lab will investigate different imputation techniques like imputation by the constant value, imputation by the mean value of each feature combined with a missing-ness indicator auxiliary variable, k nearest neighbor imputation, and iterative imputation.","steps":[{"title":"Download Data and Create Missing Values Sets","body":["Download Data and Create Missing Values Sets","First, the two datasets are downloaded. We will only use the first 400 entries for the California housing dataset for the sake of speeding up the calculations. Then we will remove some values to create new versions with artificially missing data."],"code":[{"lang":"python","text":"import numpy as np\nfrom sklearn.datasets import fetch_california_housing, load_diabetes\n\nrng = np.random.RandomState(42)\n\nX_diabetes, y_diabetes = load_diabetes(return_X_y=True)\nX_california, y_california = fetch_california_housing(return_X_y=True)\nX_california = X_california[:400]\ny_california = y_california[:400]\nX_diabetes = X_diabetes[:400]\ny_diabetes = y_diabetes[:400]\n\ndef add_missing_values(X_full, y_full):\n    n_samples, n_features = X_full.shape\n\n    # Add missing values in 75% of the lines\n    missing_rate = 0.75\n    n_missing_samples = int(n_samples * missing_rate)\n\n    missing_samples = np.zeros(n_samples, dtype=bool)\n    missing_samples[:n_missing_samples] = True\n\n    rng.shuffle(missing_samples)\n    missing_features = rng.randint(0, n_features, n_missing_samples)\n    X_missing = X_full.copy()\n    X_missing[missing_samples, missing_features] = np.nan\n    y_missing = y_full.copy()\n\n    return X_missing, y_missing\n\nX_miss_california, y_miss_california = add_missing_values(X_california, y_california)\nX_miss_diabetes, y_miss_diabetes = add_missing_values(X_diabetes, y_diabetes)"}]},{"title":"Impute Missing Data and Score","body":["Now we will write a function which will score the results on the differently imputed data. Let's look at each imputer separately:"],"code":[{"lang":"python","text":"from sklearn.ensemble import RandomForestRegressor\nfrom sklearn.experimental import enable_iterative_imputer\nfrom sklearn.impute import SimpleImputer, KNNImputer, IterativeImputer\nfrom sklearn.model_selection import cross_val_score\nfrom sklearn.pipeline import make_pipeline\n\nN_SPLITS = 4\nregressor = RandomForestRegressor(random_state=0)\n\ndef get_scores_for_imputer(imputer, X_missing, y_missing):\n    estimator = make_pipeline(imputer, regressor)\n    impute_scores = cross_val_score(\n        estimator, X_missing, y_missing, scoring=\"neg_mean_squared_error\", cv=N_SPLITS\n    )\n    return impute_scores\n\nx_labels = []\n\nmses_california = np.zeros(5)\nstds_california = np.zeros(5)\nmses_diabetes = np.zeros(5)\nstds_diabetes = np.zeros(5)"}]},{"title":"Estimate the Score","body":["First, we want to estimate the score on the original data:"],"code":[{"lang":"python","text":"def get_full_score(X_full, y_full):\n    full_scores = cross_val_score(\n        regressor, X_full, y_full, scoring=\"neg_mean_squared_error\", cv=N_SPLITS\n    )\n    return full_scores.mean(), full_scores.std()\n\nmses_california[0], stds_california[0] = get_full_score(X_california, y_california)\nmses_diabetes[0], stds_diabetes[0] = get_full_score(X_diabetes, y_diabetes)\nx_labels.append(\"Full data\")"}]},{"title":"Replace Missing Values by 0","body":["Now we will estimate the score on the data where the missing values are replaced by 0:"],"code":[{"lang":"python","text":"def get_impute_zero_score(X_missing, y_missing):\n    imputer = SimpleImputer(\n        missing_values=np.nan, add_indicator=True, strategy=\"constant\", fill_value=0\n    )\n    zero_impute_scores = get_scores_for_imputer(imputer, X_missing, y_missing)\n    return zero_impute_scores.mean(), zero_impute_scores.std()\n\nmses_california[1], stds_california[1] = get_impute_zero_score(\n    X_miss_california, y_miss_california\n)\nmses_diabetes[1], stds_diabetes[1] = get_impute_zero_score(\n    X_miss_diabetes, y_miss_diabetes\n)\nx_labels.append(\"Zero imputation\")"}]},{"title":"KNN-Imputation of the Missing Values","body":["KNN-Imputation of the Missing Values","KNNImputer imputes missing values using the weighted or unweighted mean of the desired number of nearest neighbors."],"code":[{"lang":"python","text":"def get_impute_knn_score(X_missing, y_missing):\n    imputer = KNNImputer(missing_values=np.nan, add_indicator=True)\n    knn_impute_scores = get_scores_for_imputer(imputer, X_missing, y_missing)\n    return knn_impute_scores.mean(), knn_impute_scores.std()\n\nmses_california[2], stds_california[2] = get_impute_knn_score(\n    X_miss_california, y_miss_california\n)\nmses_diabetes[2], stds_diabetes[2] = get_impute_knn_score(\n    X_miss_diabetes, y_miss_diabetes\n)\nx_labels.append(\"KNN Imputation\")"}]},{"title":"Impute Missing Values with Mean","body":["Impute Missing Values with Mean"],"code":[{"lang":"python","text":"def get_impute_mean(X_missing, y_missing):\n    imputer = SimpleImputer(missing_values=np.nan, strategy=\"mean\", add_indicator=True)\n    mean_impute_scores = get_scores_for_imputer(imputer, X_missing, y_missing)\n    return mean_impute_scores.mean(), mean_impute_scores.std()\n\nmses_california[3], stds_california[3] = get_impute_mean(\n    X_miss_california, y_miss_california\n)\nmses_diabetes[3], stds_diabetes[3] = get_impute_mean(X_miss_diabetes, y_miss_diabetes)\nx_labels.append(\"Mean Imputation\")"}]},{"title":"Iterative Imputation of the Missing Values","body":["Iterative Imputation of the Missing Values","Another option is the IterativeImputer. This uses round-robin linear regression, modeling each feature with missing values as a function of other features, in turn. The version implemented assumes Gaussian (output) variables. If your features are obviously non-normal, consider transforming them to look more normal to potentially improve performance."],"code":[{"lang":"python","text":"def get_impute_iterative(X_missing, y_missing):\n    imputer = IterativeImputer(\n        missing_values=np.nan,\n        add_indicator=True,\n        random_state=0,\n        n_nearest_features=3,\n        max_iter=1,\n        sample_posterior=True,\n    )\n    iterative_impute_scores = get_scores_for_imputer(imputer, X_missing, y_missing)\n    return iterative_impute_scores.mean(), iterative_impute_scores.std()\n\nmses_california[4], stds_california[4] = get_impute_iterative(\n    X_miss_california, y_miss_california\n)\nmses_diabetes[4], stds_diabetes[4] = get_impute_iterative(\n    X_miss_diabetes, y_miss_diabetes\n)\nx_labels.append(\"Iterative Imputation\")\n\nmses_diabetes = mses_diabetes * -1\nmses_california = mses_california * -1"}]},{"title":"Plot the Results","body":["Finally, we are going to visualize the score:"],"code":[{"lang":"python","text":"n_bars = len(mses_diabetes)\nxval = np.arange(n_bars)\n\ncolors = [\"r\", \"g\", \"b\", \"orange\", \"black\"]\n\n# plot diabetes results\nplt.figure(figsize=(12, 6))\nax1 = plt.subplot(121)\nfor j in xval:\n    ax1.barh(\n        j,\n        mses_diabetes[j],\n        xerr=stds_diabetes[j],\n        color=colors[j],\n        alpha=0.6,\n        align=\"center\",\n    )\n\nax1.set_title(\"Imputation Techniques with Diabetes Data\")\nax1.set_xlim(left=np.min(mses_diabetes) * 0.9, right=np.max(mses_diabetes) * 1.1)\nax1.set_yticks(xval)\nax1.set_xlabel(\"MSE\")\nax1.invert_yaxis()\nax1.set_yticklabels(x_labels)\n\n# plot california dataset results\nax2 = plt.subplot(122)\nfor j in xval:\n    ax2.barh(\n        j,\n        mses_california[j],\n        xerr=stds_california[j],\n        color=colors[j],\n        alpha=0.6,\n        align=\"center\",\n    )\n\nax2.set_title(\"Imputation Techniques with California Data\")\nax2.set_yticks(xval)\nax2.set_xlabel(\"MSE\")\nax2.invert_yaxis()\nax2.set_yticklabels([\"\"] * n_bars)\n\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"n_bars = len(mses_diabetes)\nxval = np.arange(n_bars)\n\ncolors = [\"r\", \"g\", \"b\", \"orange\", \"black\"]\n\n# plot diabetes results\nplt.figure(figsize=(12, 6))\nax1 = plt.subplot(121)\nfor j in xval:\n    ax1.barh(\n        j,\n        mses_diabetes[j],\n        xerr=stds_diabetes[j],\n        color=colors[j],\n        alpha=0.6,\n        align=\"center\",\n    )\n\nax1.set_title(\"Imputation Techniques with Diabetes Data\")\nax1.set_xlim(left=np.min(mses_diabetes) * 0.9, right=np.max(mses_diabetes) * 1.1)\nax1.set_yticks(xval)\nax1.set_xlabel(\"MSE\")\nax1.invert_yaxis()\nax1.set_yticklabels(x_labels)\n\n# plot california dataset results\nax2 = plt.subplot(122)\nfor j in xval:\n    ax2.barh(\n        j,\n        mses_california[j],\n        xerr=stds_california[j],\n        color=colors[j],\n        alpha=0.6,\n        align=\"center\",\n    )\n\nax2.set_title(\"Imputation Techniques with California Data\")\nax2.set_yticks(xval)\nax2.set_xlabel(\"MSE\")\nax2.invert_yaxis()\nax2.set_yticklabels([\"\"] * n_bars)\n\nplt.show()"}],"source":"scikit-learn/scikit-learn · BSD 3-Clause"},"labex-sklearn-multi-layer-perceptron-regularization":{"intro":"This lab demonstrates how to use regularization in multi-layer perceptron (MLP) to combat overfitting. We will compare different values for the regularization parameter, alpha, and observe how the decision functions change.","steps":[{"title":"Import Libraries","body":["We will start by importing the necessary libraries for this lab. We will use scikit-learn to create synthetic datasets, MLPClassifier to build the MLP model, StandardScaler to standardize the data, and make_pipeline to create a pipeline of transformations and classifier."],"code":[{"lang":"python","text":"import numpy as np\nfrom matplotlib import pyplot as plt\nfrom matplotlib.colors import ListedColormap\nfrom sklearn.model_selection import train_test_split\nfrom sklearn.preprocessing import StandardScaler\nfrom sklearn.datasets import make_moons, make_circles, make_classification\nfrom sklearn.neural_network import MLPClassifier\nfrom sklearn.pipeline import make_pipeline"}]},{"title":"Define Alphas","body":["We will define different values for the regularization parameter, alpha. We will use np.logspace to generate 5 logarithmically spaced values between 0.1 and 10."],"code":[{"lang":"python","text":"alphas = np.logspace(-1, 1, 5)"}]},{"title":"Create Classifiers","body":["We will create MLP classifiers for each value of alpha. We will create a pipeline that includes StandardScaler to standardize the data and MLPClassifier with different values of alpha. We will set the solver to 'lbfgs', which is an optimizer in the family of quasi-Newton methods. We will set max_iter to 2000 and early_stopping to True to prevent overfitting. We will use two hidden layers with 10 neurons each."],"code":[{"lang":"python","text":"classifiers = []\nnames = []\nfor alpha in alphas:\n    classifiers.append(\n        make_pipeline(\n            StandardScaler(),\n            MLPClassifier(\n                solver=\"lbfgs\",\n                alpha=alpha,\n                random_state=1,\n                max_iter=2000,\n                early_stopping=True,\n                hidden_layer_sizes=[10, 10],\n            ),\n        )\n    )\n    names.append(f\"alpha {alpha:.2f}\")"}]},{"title":"Create Datasets","body":["We will create three synthetic datasets using make_classification, make_moons, and make_circles functions from scikit-learn. We will split each dataset into training and testing sets using train_test_split."],"code":[{"lang":"python","text":"X, y = make_classification(\n    n_features=2, n_redundant=0, n_informative=2, random_state=0, n_clusters_per_class=1\n)\nrng = np.random.RandomState(2)\nX += 2 * rng.uniform(size=X.shape)\nlinearly_separable = (X, y)\n\ndatasets = [\n    make_moons(noise=0.3, random_state=0),\n    make_circles(noise=0.2, factor=0.5, random_state=1),\n    linearly_separable,\n]\n\nfigure = plt.figure(figsize=(17, 9))\ni = 1\n# iterate over datasets\nfor X, y in datasets:\n    # split into training and test part\n    X_train, X_test, y_train, y_test = train_test_split(\n        X, y, test_size=0.4, random_state=42\n    )"}]},{"title":"Plot Datasets","body":["We will plot each dataset and color the training and testing points differently."],"code":[{"lang":"python","text":"x_min, x_max = X[:, 0].min() - 0.5, X[:, 0].max() + 0.5\n    y_min, y_max = X[:, 1].min() - 0.5, X[:, 1].max() + 0.5\n    xx, yy = np.meshgrid(np.arange(x_min, x_max, h), np.arange(y_min, y_max, h))\n\n    # just plot the dataset first\n    cm = plt.cm.RdBu\n    cm_bright = ListedColormap([\"#FF0000\", \"#0000FF\"])\n    ax = plt.subplot(len(datasets), len(classifiers) + 1, i)\n    # Plot the training points\n    ax.scatter(X_train[:, 0], X_train[:, 1], c=y_train, cmap=cm_bright)\n    # and testing points\n    ax.scatter(X_test[:, 0], X_test[:, 1], c=y_test, cmap=cm_bright, alpha=0.6)\n    ax.set_xlim(xx.min(), xx.max())\n    ax.set_ylim(yy.min(), yy.max())\n    ax.set_xticks(())\n    ax.set_yticks(())\n    i += 1"}]},{"title":"Fit Classifiers and Plot Decision Boundaries","body":["Fit Classifiers and Plot Decision Boundaries","We will fit each classifier on each dataset and plot the decision boundaries. We will use contourf to plot the decision boundary and scatter to plot the training and testing points. We will also display the accuracy score on each plot."],"code":[{"lang":"python","text":"# iterate over classifiers\n    for name, clf in zip(names, classifiers):\n        ax = plt.subplot(len(datasets), len(classifiers) + 1, i)\n        clf.fit(X_train, y_train)\n        score = clf.score(X_test, y_test)\n\n        # Plot the decision boundary. For that, we will assign a color to each\n        # point in the mesh [x_min, x_max] x [y_min, y_max].\n        if hasattr(clf, \"decision_function\"):\n            Z = clf.decision_function(np.column_stack([xx.ravel(), yy.ravel()]))\n        else:\n            Z = clf.predict_proba(np.column_stack([xx.ravel(), yy.ravel()]))[:, 1]\n\n        # Put the result into a color plot\n        Z = Z.reshape(xx.shape)\n        ax.contourf(xx, yy, Z, cmap=cm, alpha=0.8)\n\n        # Plot also the training points\n        ax.scatter(\n            X_train[:, 0],\n            X_train[:, 1],\n            c=y_train,\n            cmap=cm_bright,\n            edgecolors=\"black\",\n            s=25,\n        )\n        # and testing points\n        ax.scatter(\n            X_test[:, 0],\n            X_test[:, 1],\n            c=y_test,\n            cmap=cm_bright,\n            alpha=0.6,\n            edgecolors=\"black\",\n            s=25,\n        )\n\n        ax.set_xlim(xx.min(), xx.max())\n        ax.set_ylim(yy.min(), yy.max())\n        ax.set_xticks(())\n        ax.set_yticks(())\n        ax.set_title(name)\n        ax.text(\n            xx.max() - 0.3,\n            yy.min() + 0.3,\n            f\"{score:.3f}\".lstrip(\"0\"),\n            size=15,\n            horizontalalignment=\"right\","}]},{"title":"Show Plots","body":["Finally, we will adjust the subplot layout and display the plots."],"code":[{"lang":"python","text":"figure.subplots_adjust(left=0.02, right=0.98)\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"figure.subplots_adjust(left=0.02, right=0.98)\nplt.show()"}],"source":"scikit-learn/scikit-learn · BSD 3-Clause"},"labex-sklearn-scikit-learn-mlpclassifier-stochastic-learni":{"intro":"This lab will guide you through the process of using the Scikit-learn MLPClassifier to compare the performance of different stochastic learning strategies, including SGD and Adam. The MLPClassifier is a neural network classifier that uses backpropagation to optimize the weights of the network. The goal of this lab is to show how different stochastic learning strategies can affect the training loss curves of the MLPClassifier. We will use several small datasets for this example, although the general trend shown in these examples seems to carry over to larger datasets.","steps":[{"title":"Import necessary libraries","body":["First, we need to import the necessary libraries, including MLPClassifier, MinMaxScaler, datasets, and matplotlib.pyplot. We will also import ConvergenceWarning to ignore convergence warnings during training."],"code":[{"lang":"python","text":"import warnings\n\nimport matplotlib.pyplot as plt\n\nfrom sklearn.neural_network import MLPClassifier\nfrom sklearn.preprocessing import MinMaxScaler\nfrom sklearn import datasets\nfrom sklearn.exceptions import ConvergenceWarning"}]},{"title":"Define different learning strategies","body":["Define different learning strategies","Next, we need to define the different learning strategies we want to compare. We will define several different learning rate schedules and momentum parameters, including constant learning-rate, constant with momentum, constant with Nesterov's momentum, inv-scaling learning-rate, inv-scaling with momentum, inv-scaling with Nesterov's momentum, and adam. We will also define labels and plot_args to use in our plot later."],"code":[{"lang":"python","text":"# different learning rate schedules and momentum parameters\nparams = [\n    {\n        \"solver\": \"sgd\",\n        \"learning_rate\": \"constant\",\n        \"momentum\": 0,\n        \"learning_rate_init\": 0.2,\n    },\n    {\n        \"solver\": \"sgd\",\n        \"learning_rate\": \"constant\",\n        \"momentum\": 0.9,\n        \"nesterovs_momentum\": False,\n        \"learning_rate_init\": 0.2,\n    },\n    {\n        \"solver\": \"sgd\",\n        \"learning_rate\": \"constant\",\n        \"momentum\": 0.9,\n        \"nesterovs_momentum\": True,\n        \"learning_rate_init\": 0.2,\n    },\n    {\n        \"solver\": \"sgd\",\n        \"learning_rate\": \"invscaling\",\n        \"momentum\": 0,\n        \"learning_rate_init\": 0.2,\n    },\n    {\n        \"solver\": \"sgd\",\n        \"learning_rate\": \"invscaling\",\n        \"momentum\": 0.9,\n        \"nesterovs_momentum\": True,\n        \"learning_rate_init\": 0.2,\n    },\n    {\n        \"solver\": \"sgd\",\n        \"learning_rate\": \"invscaling\",\n        \"momentum\": 0.9,\n        \"nesterovs_momentum\": False,\n        \"learning_rate_init\": 0.2,\n    },\n    {\"solver\": \"adam\", \"learning_rate_init\": 0.01},\n]\n\nlabels = [\n    \"constant learning-rate\",\n    \"constant with momentum\","}]},{"title":"Define a function to plot the learning curves","body":["Define a function to plot the learning curves","Next, we need to define a function that will plot the learning curves for each learning strategy on each dataset. The function takes in the dataset (X, y), an axis to plot on, and a name for the dataset. We will use MinMaxScaler to scale the data and MLPClassifier to train the neural network. We will train the network using each learning strategy, ignoring convergence warnings, and plot the learning curves for each strategy on the same plot."],"code":[{"lang":"python","text":"def plot_on_dataset(X, y, ax, name):\n    # for each dataset, plot learning for each learning strategy\n    print(\"\\nlearning on dataset %s\" % name)\n    ax.set_title(name)\n\n    X = MinMaxScaler().fit_transform(X)\n    mlps = []\n    if name == \"digits\":\n        # digits is larger but converges fairly quickly\n        max_iter = 15\n    else:\n        max_iter = 400\n\n    for label, param in zip(labels, params):\n        print(\"training: %s\" % label)\n        mlp = MLPClassifier(random_state=0, max_iter=max_iter, **param)\n\n        # some parameter combinations will not converge as can be seen on the\n        # plots so they are ignored here\n        with warnings.catch_warnings():\n            warnings.filterwarnings(\n                \"ignore\", category=ConvergenceWarning, module=\"sklearn\"\n            )\n            mlp.fit(X, y)\n\n        mlps.append(mlp)\n        print(\"Training set score: %f\" % mlp.score(X, y))\n        print(\"Training set loss: %f\" % mlp.loss_)\n    for mlp, label, args in zip(mlps, labels, plot_args):\n        ax.plot(mlp.loss_curve_, label=label, **args)"}]},{"title":"Load or generate small datasets","body":["Load or generate small datasets","Now, we need to load or generate the small datasets we will use for this example. We will use the iris dataset, the digits dataset, and two datasets generated using make_circles and make_moons functions."],"code":[{"lang":"python","text":"iris = datasets.load_iris()\nX_digits, y_digits = datasets.load_digits(return_X_y=True)\ndata_sets = [\n    (iris.data, iris.target),\n    (X_digits, y_digits),\n    datasets.make_circles(noise=0.2, factor=0.5, random_state=1),\n    datasets.make_moons(noise=0.3, random_state=0),\n]"}]},{"title":"Plot the learning curves for each dataset","body":["Plot the learning curves for each dataset","Finally, we can plot the learning curves for each dataset using the plot_on_dataset function. We will create a 2x2 plot and plot each dataset on a separate axis."],"code":[{"lang":"python","text":"fig, axes = plt.subplots(2, 2, figsize=(15, 10))\n\nfor ax, data, name in zip(\n    axes.ravel(), data_sets, [\"iris\", \"digits\", \"circles\", \"moons\"]\n):\n    plot_on_dataset(*data, ax=ax, name=name)\n\nfig.legend(ax.get_lines(), labels, ncol=3, loc=\"upper center\")\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"fig, axes = plt.subplots(2, 2, figsize=(15, 10))\n\nfor ax, data, name in zip(\n    axes.ravel(), data_sets, [\"iris\", \"digits\", \"circles\", \"moons\"]\n):\n    plot_on_dataset(*data, ax=ax, name=name)\n\nfig.legend(ax.get_lines(), labels, ncol=3, loc=\"upper center\")\nplt.show()"}],"source":"scikit-learn/scikit-learn · BSD 3-Clause"},"labex-sklearn-classify-handwritten-digits-with-mlp-classif":{"intro":"This tutorial will show you how to create an MLPClassifier using Scikit-learn to classify handwritten digits from the MNIST dataset. We will also visualize the weights of the first layer of the MLP to gain insight into the learning behavior.","steps":[{"title":"Import Libraries","body":["We will start by importing the necessary libraries for this project."],"code":[{"lang":"python","text":"import warnings\nimport matplotlib.pyplot as plt\nfrom sklearn.datasets import fetch_openml\nfrom sklearn.exceptions import ConvergenceWarning\nfrom sklearn.neural_network import MLPClassifier\nfrom sklearn.model_selection import train_test_split"}]},{"title":"Load Data","body":["Next, we will load the MNIST dataset using Scikit-learn's fetch_openml function."],"code":[{"lang":"python","text":"X, y = fetch_openml(\n    \"mnist_784\", version=1, return_X_y=True, as_frame=False, parser=\"pandas\"\n)"}]},{"title":"Preprocess Data","body":["We will normalize the data by dividing each pixel value by 255.0, which is the maximum pixel value."],"code":[{"lang":"python","text":"X = X / 255.0"}]},{"title":"Split Data","body":["We will split the dataset into a training set and a test set using the train_test_split function."],"code":[{"lang":"python","text":"X_train, X_test, y_train, y_test = train_test_split(X, y, random_state=0, test_size=0.7)"}]},{"title":"Train MLPClassifier","body":["We will create an MLPClassifier with a single hidden layer containing 40 neurons. We will train the MLP for only 8 iterations due to resource constraints. We will also catch the ConvergenceWarning that will be thrown because the model won't converge within the limited number of iterations."],"code":[{"lang":"python","text":"mlp = MLPClassifier(\n    hidden_layer_sizes=(40,),\n    max_iter=8,\n    alpha=1e-4,\n    solver=\"sgd\",\n    verbose=10,\n    random_state=1,\n    learning_rate_init=0.2,\n)\n\nwith warnings.catch_warnings():\n    warnings.filterwarnings(\"ignore\", category=ConvergenceWarning, module=\"sklearn\")\n    mlp.fit(X_train, y_train)"}]},{"title":"Evaluate the Model","body":["We will evaluate the MLPClassifier by computing its accuracy on the training and test sets."],"code":[{"lang":"python","text":"print(\"Training set score: %f\" % mlp.score(X_train, y_train))\nprint(\"Test set score: %f\" % mlp.score(X_test, y_test))"}]},{"title":"Visualize Weights","body":["Finally, we will visualize the weights of the first layer of the MLP. We will create a 4x4 grid of subplots and display each weight as a 28x28 pixel grayscale image."],"code":[{"lang":"python","text":"fig, axes = plt.subplots(4, 4)\nvmin, vmax = mlp.coefs_[0].min(), mlp.coefs_[0].max()\nfor coef, ax in zip(mlp.coefs_[0].T, axes.ravel()):\n    ax.matshow(coef.reshape(28, 28), cmap=plt.cm.gray, vmin=0.5 * vmin, vmax=0.5 * vmax)\n    ax.set_xticks(())\n    ax.set_yticks(())\n\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"fig, axes = plt.subplots(4, 4)\nvmin, vmax = mlp.coefs_[0].min(), mlp.coefs_[0].max()\nfor coef, ax in zip(mlp.coefs_[0].T, axes.ravel()):\n    ax.matshow(coef.reshape(28, 28), cmap=plt.cm.gray, vmin=0.5 * vmin, vmax=0.5 * vmax)\n    ax.set_xticks(())\n    ax.set_yticks(())\n\nplt.show()"}],"source":"scikit-learn/scikit-learn · BSD 3-Clause"},"labex-sklearn-gradient-boosting-monotonic-constraints":{"intro":"This is a step-by-step tutorial to demonstrate the effect of monotonic constraints on a gradient boosting estimator. Gradient boosting is a popular machine learning technique used for regression and classification tasks. In this tutorial, we will build an artificial dataset and use a gradient boosting estimator to demonstrate the effect of monotonic constraints on the model's predictions.","steps":[{"title":"Import Libraries","body":["We will start by importing the necessary libraries required for this tutorial."],"code":[{"lang":"python","text":"from sklearn.ensemble import HistGradientBoostingRegressor\nfrom sklearn.inspection import PartialDependenceDisplay\nimport numpy as np\nimport matplotlib.pyplot as plt\nimport pandas as pd"}]},{"title":"Generate Data","body":["We will generate an artificial dataset where the target value is positively correlated with the first feature and negatively correlated with the second feature. We will also add some random noise to make the data more realistic."],"code":[{"lang":"python","text":"rng = np.random.RandomState(0)\n\nn_samples = 1000\nf_0 = rng.rand(n_samples)\nf_1 = rng.rand(n_samples)\nX = np.c_[f_0, f_1]\nnoise = rng.normal(loc=0.0, scale=0.01, size=n_samples)\n\ny = 5 * f_0 + np.sin(10 * np.pi * f_0) - 5 * f_1 - np.cos(10 * np.pi * f_1) + noise"}]},{"title":"Fit a Model Without Constraints","body":["Fit a Model Without Constraints","We will fit a model on the generated data without any constraints to see how the model performs without any restrictions."],"code":[{"lang":"python","text":"gbdt_no_cst = HistGradientBoostingRegressor()\ngbdt_no_cst.fit(X, y)"}]},{"title":"Fit a Model with Monotonic Constraints","body":["Fit a Model With Monotonic Constraints","We will now fit another model on the same data but with monotonic constraints on the features. We will impose a monotonic increase constraint on the first feature and a monotonic decrease constraint on the second feature."],"code":[{"lang":"python","text":"gbdt_with_monotonic_cst = HistGradientBoostingRegressor(monotonic_cst=[1, -1])\ngbdt_with_monotonic_cst.fit(X, y)"}]},{"title":"Display Partial Dependence","body":["We will now display the partial dependence of the predictions on the two features for both the models."],"code":[{"lang":"python","text":"fig, ax = plt.subplots()\ndisp = PartialDependenceDisplay.from_estimator(\n    gbdt_no_cst,\n    X,\n    features=[0, 1],\n    feature_names=(\n        \"First feature\",\n        \"Second feature\",\n    ),\n    line_kw={\"linewidth\": 4, \"label\": \"unconstrained\", \"color\": \"tab:blue\"},\n    ax=ax,\n)\nPartialDependenceDisplay.from_estimator(\n    gbdt_with_monotonic_cst,\n    X,\n    features=[0, 1],\n    line_kw={\"linewidth\": 4, \"label\": \"constrained\", \"color\": \"tab:orange\"},\n    ax=disp.axes_,\n)\n\nfor f_idx in (0, 1):\n    disp.axes_[0, f_idx].plot(\n        X[:, f_idx], y, \"o\", alpha=0.3, zorder=-1, color=\"tab:green\"\n    )\n    disp.axes_[0, f_idx].set_ylim(-6, 6)\n\nplt.legend()\nfig.suptitle(\"Monotonic constraints effect on partial dependences\")\nplt.show()"}]},{"title":"Using Feature Names to Specify Monotonic Constraints","body":["Using Feature Names to Specify Monotonic Constraints","If the training data has feature names, it's possible to specify the monotonic constraints by passing a dictionary. We will now demonstrate this by using the same data and specifying the constraints using feature names."],"code":[{"lang":"python","text":"X_df = pd.DataFrame(X, columns=[\"f_0\", \"f_1\"])\n\ngbdt_with_monotonic_cst_df = HistGradientBoostingRegressor(\n    monotonic_cst={\"f_0\": 1, \"f_1\": -1}\n).fit(X_df, y)\n\nnp.allclose(\n    gbdt_with_monotonic_cst_df.predict(X_df), gbdt_with_monotonic_cst.predict(X)\n)"}]}],"commands":[],"reference":[{"path":"reference.py","text":"X_df = pd.DataFrame(X, columns=[\"f_0\", \"f_1\"])\n\ngbdt_with_monotonic_cst_df = HistGradientBoostingRegressor(\n    monotonic_cst={\"f_0\": 1, \"f_1\": -1}\n).fit(X_df, y)\n\nnp.allclose(\n    gbdt_with_monotonic_cst_df.predict(X_df), gbdt_with_monotonic_cst.predict(X)\n)"}],"source":"scikit-learn/scikit-learn · BSD 3-Clause"},"labex-sklearn-optimizing-model-hyperparameters-with-gridse":{"intro":"In this tutorial, we will learn about GridSearchCV function in Scikit-Learn. GridSearchCV is a function that is used to search for the best hyperparameters for a given model. It is an exhaustive search over specified parameter values for an estimator. The parameters of the estimator used to apply these methods are optimized by cross-validated grid-search over a parameter grid.","steps":[{"title":"Import libraries","body":["Let's begin by importing the necessary libraries."],"code":[{"lang":"python","text":"import numpy as np\nfrom matplotlib import pyplot as plt\n\nfrom sklearn.datasets import make_hastie_10_2\nfrom sklearn.model_selection import GridSearchCV\nfrom sklearn.metrics import make_scorer\nfrom sklearn.metrics import accuracy_score\nfrom sklearn.tree import DecisionTreeClassifier"}]},{"title":"Load dataset","body":["In this step, we will load a dataset using Scikit-Learn's make_hastie_10_2 function. This function generates a synthetic dataset for binary classification."],"code":[{"lang":"python","text":"X, y = make_hastie_10_2(n_samples=8000, random_state=42)"}]},{"title":"Define the hyperparameters and evaluation metrics","body":["Define the hyperparameters and evaluation metrics","In this step, we will define the hyperparameters for the DecisionTreeClassifier model and the evaluation metrics that we will be using. We will be using the AUC (Area Under the Curve) and Accuracy metrics."],"code":[{"lang":"python","text":"scoring = {\"AUC\": \"roc_auc\", \"Accuracy\": make_scorer(accuracy_score)}"}]},{"title":"Perform the grid search","body":["In this step, we will use the GridSearchCV function to perform the grid search. We will be searching for the best hyperparameters for the min_samples_split parameter of the DecisionTreeClassifier model."],"code":[{"lang":"python","text":"gs = GridSearchCV(\n    DecisionTreeClassifier(random_state=42),\n    param_grid={\"min_samples_split\": range(2, 403, 20)},\n    scoring=scoring,\n    refit=\"AUC\",\n    n_jobs=2,\n    return_train_score=True,\n)\ngs.fit(X, y)\nresults = gs.cv_results_"}]},{"title":"Visualize the results","body":["In this step, we will visualize the results of the grid search using a plot. We will be plotting the AUC and Accuracy scores for both the training and testing sets."],"code":[{"lang":"python","text":"plt.figure(figsize=(13, 13))\nplt.title(\"GridSearchCV evaluating using multiple scorers simultaneously\", fontsize=16)\n\nplt.xlabel(\"min_samples_split\")\nplt.ylabel(\"Score\")\n\nax = plt.gca()\nax.set_xlim(0, 402)\nax.set_ylim(0.73, 1)\n\n# Get the regular numpy array from the MaskedArray\nX_axis = np.array(results[\"param_min_samples_split\"].data, dtype=float)\n\nfor scorer, color in zip(sorted(scoring), [\"g\", \"k\"]):\n    for sample, style in ((\"train\", \"--\"), (\"test\", \"-\")):\n        sample_score_mean = results[\"mean_%s_%s\" % (sample, scorer)]\n        sample_score_std = results[\"std_%s_%s\" % (sample, scorer)]\n        ax.fill_between(\n            X_axis,\n            sample_score_mean - sample_score_std,\n            sample_score_mean + sample_score_std,\n            alpha=0.1 if sample == \"test\" else 0,\n            color=color,\n        )\n        ax.plot(\n            X_axis,\n            sample_score_mean,\n            style,\n            color=color,\n            alpha=1 if sample == \"test\" else 0.7,\n            label=\"%s (%s)\" % (scorer, sample),\n        )\n\n    best_index = np.nonzero(results[\"rank_test_%s\" % scorer] == 1)[0][0]\n    best_score = results[\"mean_test_%s\" % scorer][best_index]\n\n    # Plot a dotted vertical line at the best score for that scorer marked by x\n    ax.plot(\n        [\n            X_axis[best_index],\n        ]\n        * 2,\n        [0, best_score],\n        linestyle=\"-.\",\n        color=color,\n        marker=\"x\",\n        markeredgewidth=3,\n        ms=8,"}]}],"commands":[],"reference":[{"path":"reference.py","text":"plt.figure(figsize=(13, 13))\nplt.title(\"GridSearchCV evaluating using multiple scorers simultaneously\", fontsize=16)\n\nplt.xlabel(\"min_samples_split\")\nplt.ylabel(\"Score\")\n\nax = plt.gca()\nax.set_xlim(0, 402)\nax.set_ylim(0.73, 1)\n\n# Get the regular numpy array from the MaskedArray\nX_axis = np.array(results[\"param_min_samples_split\"].data, dtype=float)\n\nfor scorer, color in zip(sorted(scoring), [\"g\", \"k\"]):\n    for sample, style in ((\"train\", \"--\"), (\"test\", \"-\")):\n        sample_score_mean = results[\"mean_%s_%s\" % (sample, scorer)]\n        sample_score_std = results[\"std_%s_%s\" % (sample, scorer)]\n        ax.fill_between(\n            X_axis,\n            sample_score_mean - sample_score_std,\n            sample_score_mean + sample_score_std,\n            alpha=0.1 if sample == \"test\" else 0,\n            color=color,\n        )\n        ax.plot(\n            X_axis,\n            sample_score_mean,\n            style,\n            color=color,\n            alpha=1 if sample == \"test\" else 0.7,\n            label=\"%s (%s)\" % (scorer, sample),\n        )\n\n    best_index = np.nonzero(results[\"rank_test_%s\" % scorer] == 1)[0][0]\n    best_score = results[\"mean_test_%s\" % scorer][best_index]\n\n    # Plot a dotted vertical line at the best score for that scorer marked by x\n    ax.plot(\n        [\n            X_axis[best_index],\n        ]\n        * 2,\n        [0, best_score],\n        linestyle=\"-.\",\n        color=color,\n        marker=\"x\",\n        markeredgewidth=3,\n        ms=8,"}],"source":"scikit-learn/scikit-learn · BSD 3-Clause"},"labex-sklearn-joint-feature-selection-with-multi-task-lass":{"intro":"In this lab, we will explore how to perform joint feature selection using the multi-task Lasso algorithm. We will use scikit-learn, a popular Python machine learning library, to generate some sample data and fit models to it. We will then plot the results of the models to see how they compare.","steps":[{"title":"Generate Data","body":["First, we need to generate some sample data that we can use to fit our models. We will use numpy to generate 100 samples, each with 30 features and 40 tasks. We will also randomly select 5 relevant features and create coefficients for them using sine waves with random frequency and phase. Finally, we will add some random noise to the data."],"code":[{"lang":"python","text":"import numpy as np\n\nrng = np.random.RandomState(42)\n\n# Generate some 2D coefficients with sine waves with random frequency and phase\nn_samples, n_features, n_tasks = 100, 30, 40\nn_relevant_features = 5\ncoef = np.zeros((n_tasks, n_features))\ntimes = np.linspace(0, 2 * np.pi, n_tasks)\nfor k in range(n_relevant_features):\n    coef[:, k] = np.sin((1.0 + rng.randn(1)) * times + 3 * rng.randn(1))\n\nX = rng.randn(n_samples, n_features)\nY = np.dot(X, coef.T) + rng.randn(n_samples, n_tasks)"}]},{"title":"Fit Models","body":["Now that we have our data, we can fit models to it using the Lasso and multi-task Lasso algorithms. We will fit a Lasso model for each task and then fit a multi-task Lasso model to all tasks at once."],"code":[{"lang":"python","text":"from sklearn.linear_model import MultiTaskLasso, Lasso\n\ncoef_lasso_ = np.array([Lasso(alpha=0.5).fit(X, y).coef_ for y in Y.T])\ncoef_multi_task_lasso_ = MultiTaskLasso(alpha=1.0).fit(X, Y).coef_"}]},{"title":"Plot Results","body":["Finally, we can plot the results of our models to see how they compare. We will plot the support (i.e., the location of non-zero coefficients) for each model, as well as the time series for one of the features."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\n\nfig = plt.figure(figsize=(8, 5))\nplt.subplot(1, 2, 1)\nplt.spy(coef_lasso_)\nplt.xlabel(\"Feature\")\nplt.ylabel(\"Time (or Task)\")\nplt.text(10, 5, \"Lasso\")\nplt.subplot(1, 2, 2)\nplt.spy(coef_multi_task_lasso_)\nplt.xlabel(\"Feature\")\nplt.ylabel(\"Time (or Task)\")\nplt.text(10, 5, \"MultiTaskLasso\")\nfig.suptitle(\"Coefficient non-zero location\")\n\nfeature_to_plot = 0\nplt.figure()\nlw = 2\nplt.plot(coef[:, feature_to_plot], color=\"seagreen\", linewidth=lw, label=\"Ground truth\")\nplt.plot(\n    coef_lasso_[:, feature_to_plot], color=\"cornflowerblue\", linewidth=lw, label=\"Lasso\"\n)\nplt.plot(\n    coef_multi_task_lasso_[:, feature_to_plot],\n    color=\"gold\",\n    linewidth=lw,\n    label=\"MultiTaskLasso\",\n)\nplt.legend(loc=\"upper center\")\nplt.axis(\"tight\")\nplt.ylim([-1.1, 1.1])\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"import matplotlib.pyplot as plt\n\nfig = plt.figure(figsize=(8, 5))\nplt.subplot(1, 2, 1)\nplt.spy(coef_lasso_)\nplt.xlabel(\"Feature\")\nplt.ylabel(\"Time (or Task)\")\nplt.text(10, 5, \"Lasso\")\nplt.subplot(1, 2, 2)\nplt.spy(coef_multi_task_lasso_)\nplt.xlabel(\"Feature\")\nplt.ylabel(\"Time (or Task)\")\nplt.text(10, 5, \"MultiTaskLasso\")\nfig.suptitle(\"Coefficient non-zero location\")\n\nfeature_to_plot = 0\nplt.figure()\nlw = 2\nplt.plot(coef[:, feature_to_plot], color=\"seagreen\", linewidth=lw, label=\"Ground truth\")\nplt.plot(\n    coef_lasso_[:, feature_to_plot], color=\"cornflowerblue\", linewidth=lw, label=\"Lasso\"\n)\nplt.plot(\n    coef_multi_task_lasso_[:, feature_to_plot],\n    color=\"gold\",\n    linewidth=lw,\n    label=\"MultiTaskLasso\",\n)\nplt.legend(loc=\"upper center\")\nplt.axis(\"tight\")\nplt.ylim([-1.1, 1.1])\nplt.show()"}],"source":"scikit-learn/scikit-learn · BSD 3-Clause"},"labex-sklearn-multi-label-document-classification":{"intro":"This lab demonstrates a multi-label document classification problem using scikit-learn. The dataset is generated randomly based on the following process:","steps":[{"title":"Import Libraries","body":["In this step, we import the necessary libraries: numpy, matplotlib, make_multilabel_classification from sklearn.datasets, OneVsRestClassifier and SVC from sklearn.multiclass, PCA and CCA from sklearn.decomposition."],"code":[{"lang":"python","text":"import numpy as np\nimport matplotlib.pyplot as plt\nfrom sklearn.datasets import make_multilabel_classification\nfrom sklearn.multiclass import OneVsRestClassifier\nfrom sklearn.svm import SVC\nfrom sklearn.decomposition import PCA\nfrom sklearn.cross_decomposition import CCA"}]},{"title":"Define Plotting Function","body":["In this step, we define the plot_hyperplane and plot_subfigure functions. plot_hyperplane function is used to get the separating hyperplane while plot_subfigure function is used to plot the subplots."],"code":[{"lang":"python","text":"def plot_hyperplane(clf, min_x, max_x, linestyle, label):\n    # get the separating hyperplane\n    w = clf.coef_[0]\n    a = -w[0] / w[1]\n    xx = np.linspace(min_x - 5, max_x + 5)  # make sure the line is long enough\n    yy = a * xx - (clf.intercept_[0]) / w[1]\n    plt.plot(xx, yy, linestyle, label=label)\n\n\ndef plot_subfigure(X, Y, subplot, title, transform):\n    if transform == \"pca\":\n        X = PCA(n_components=2).fit_transform(X)\n    elif transform == \"cca\":\n        X = CCA(n_components=2).fit(X, Y).transform(X)\n    else:\n        raise ValueError\n\n    min_x = np.min(X[:, 0])\n    max_x = np.max(X[:, 0])\n\n    min_y = np.min(X[:, 1])\n    max_y = np.max(X[:, 1])\n\n    classif = OneVsRestClassifier(SVC(kernel=\"linear\"))\n    classif.fit(X, Y)\n\n    plt.subplot(2, 2, subplot)\n    plt.title(title)\n\n    zero_class = np.where(Y[:, 0])\n    one_class = np.where(Y[:, 1])\n    plt.scatter(X[:, 0], X[:, 1], s=40, c=\"gray\", edgecolors=(0, 0, 0))\n    plt.scatter(\n        X[zero_class, 0],\n        X[zero_class, 1],\n        s=160,\n        edgecolors=\"b\",\n        facecolors=\"none\",\n        linewidths=2,\n        label=\"Class 1\",\n    )\n    plt.scatter(\n        X[one_class, 0],\n        X[one_class, 1],\n        s=80,\n        edgecolors=\"orange\",\n        facecolors=\"none\",\n        linewidths=2,"}]},{"title":"Generate Dataset","body":["In this step, we generate the dataset using make_multilabel_classification function from sklearn.datasets."],"code":[{"lang":"python","text":"X, Y = make_multilabel_classification(\n    n_classes=2, n_labels=1, allow_unlabeled=True, random_state=1\n)"}]},{"title":"Plot Subplots","body":["In this step, we use plot_subfigure function to plot the subplots."],"code":[{"lang":"python","text":"plt.figure(figsize=(8, 6))\n\nplot_subfigure(X, Y, 1, \"With unlabeled samples + CCA\", \"cca\")\nplot_subfigure(X, Y, 2, \"With unlabeled samples + PCA\", \"pca\")\n\nX, Y = make_multilabel_classification(\n    n_classes=2, n_labels=1, allow_unlabeled=False, random_state=1\n)\n\nplot_subfigure(X, Y, 3, \"Without unlabeled samples + CCA\", \"cca\")\nplot_subfigure(X, Y, 4, \"Without unlabeled samples + PCA\", \"pca\")\n\nplt.subplots_adjust(0.04, 0.02, 0.97, 0.94, 0.09, 0.2)\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"plt.figure(figsize=(8, 6))\n\nplot_subfigure(X, Y, 1, \"With unlabeled samples + CCA\", \"cca\")\nplot_subfigure(X, Y, 2, \"With unlabeled samples + PCA\", \"pca\")\n\nX, Y = make_multilabel_classification(\n    n_classes=2, n_labels=1, allow_unlabeled=False, random_state=1\n)\n\nplot_subfigure(X, Y, 3, \"Without unlabeled samples + CCA\", \"cca\")\nplot_subfigure(X, Y, 4, \"Without unlabeled samples + PCA\", \"pca\")\n\nplt.subplots_adjust(0.04, 0.02, 0.97, 0.94, 0.09, 0.2)\nplt.show()"}],"source":"scikit-learn/scikit-learn · BSD 3-Clause"},"labex-sklearn-plot-nca-classification":{"intro":"This lab will show how to compare nearest neighbors classification with and without Neighborhood Components Analysis (NCA). We will plot the class decision boundaries given by a Nearest Neighbors classifier when using the Euclidean distance on the original features, versus using the Euclidean distance after the transformation learned by Neighborhood Components Analysis. The latter aims to find a linear transformation that maximizes the (stochastic) nearest neighbor classification accuracy on the training set. We will use the Iris dataset which contains 3 classes of 50 instances each.","steps":[{"title":"Import Libraries","body":["We will start by importing the necessary libraries. We will use scikit-learn to perform the nearest neighbors classification and NCA. We will use matplotlib to plot the class decision boundaries."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nfrom matplotlib.colors import ListedColormap\nfrom sklearn import datasets\nfrom sklearn.model_selection import train_test_split\nfrom sklearn.preprocessing import StandardScaler\nfrom sklearn.neighbors import KNeighborsClassifier, NeighborhoodComponentsAnalysis\nfrom sklearn.pipeline import Pipeline\nfrom sklearn.inspection import DecisionBoundaryDisplay"}]},{"title":"Load and Prepare the Data","body":["Next, we will load and prepare the data. We will load the Iris dataset using scikit-learn and select only two features. We will then split the data into a training set and a testing set."],"code":[{"lang":"python","text":"n_neighbors = 1\n\ndataset = datasets.load_iris()\nX, y = dataset.data, dataset.target\n\n# we only take two features. We could avoid this ugly\n# slicing by using a two-dim dataset\nX = X[:, [0, 2]]\n\nX_train, X_test, y_train, y_test = train_test_split(\n    X, y, stratify=y, test_size=0.7, random_state=42\n)"}]},{"title":"Create Color Maps","body":["We will now create color maps to plot the class decision boundaries. We will use light colors for the background and bold colors for the class colors."],"code":[{"lang":"python","text":"h = 0.05  # step size in the mesh\n\n# Create color maps\ncmap_light = ListedColormap([\"#FFAAAA\", \"#AAFFAA\", \"#AAAAFF\"])\ncmap_bold = ListedColormap([\"#FF0000\", \"#00FF00\", \"#0000FF\"])"}]},{"title":"Define Classifiers","body":["We will define two classifiers: one using KNN and the other using NCA and KNN. We will use pipelines to scale the data and apply the classifiers."],"code":[{"lang":"python","text":"names = [\"KNN\", \"NCA, KNN\"]\n\nclassifiers = [\n    Pipeline(\n        [\n            (\"scaler\", StandardScaler()),\n            (\"knn\", KNeighborsClassifier(n_neighbors=n_neighbors)),\n        ]\n    ),\n    Pipeline(\n        [\n            (\"scaler\", StandardScaler()),\n            (\"nca\", NeighborhoodComponentsAnalysis()),\n            (\"knn\", KNeighborsClassifier(n_neighbors=n_neighbors)),\n        ]\n    ),\n]"}]},{"title":"Train and Test Classifiers","body":["We will now train and test the classifiers. We will loop over the classifiers and fit them to the training data. We will then plot the class decision boundaries and calculate the score on the testing data."],"code":[{"lang":"python","text":"for name, clf in zip(names, classifiers):\n    clf.fit(X_train, y_train)\n    score = clf.score(X_test, y_test)\n\n    _, ax = plt.subplots()\n    DecisionBoundaryDisplay.from_estimator(\n        clf,\n        X,\n        cmap=cmap_light,\n        alpha=0.8,\n        ax=ax,\n        response_method=\"predict\",\n        plot_method=\"pcolormesh\",\n        shading=\"auto\",\n    )\n\n    # Plot also the training and testing points\n    plt.scatter(X[:, 0], X[:, 1], c=y, cmap=cmap_bold, edgecolor=\"k\", s=20)\n    plt.title(\"{} (k = {})\".format(name, n_neighbors))\n    plt.text(\n        0.9,\n        0.1,\n        \"{:.2f}\".format(score),\n        size=15,\n        ha=\"center\",\n        va=\"center\",\n        transform=plt.gca().transAxes,\n    )\n\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"for name, clf in zip(names, classifiers):\n    clf.fit(X_train, y_train)\n    score = clf.score(X_test, y_test)\n\n    _, ax = plt.subplots()\n    DecisionBoundaryDisplay.from_estimator(\n        clf,\n        X,\n        cmap=cmap_light,\n        alpha=0.8,\n        ax=ax,\n        response_method=\"predict\",\n        plot_method=\"pcolormesh\",\n        shading=\"auto\",\n    )\n\n    # Plot also the training and testing points\n    plt.scatter(X[:, 0], X[:, 1], c=y, cmap=cmap_bold, edgecolor=\"k\", s=20)\n    plt.title(\"{} (k = {})\".format(name, n_neighbors))\n    plt.text(\n        0.9,\n        0.1,\n        \"{:.2f}\".format(score),\n        size=15,\n        ha=\"center\",\n        va=\"center\",\n        transform=plt.gca().transAxes,\n    )\n\nplt.show()"}],"source":"scikit-learn/scikit-learn · BSD 3-Clause"},"labex-sklearn-neighborhood-components-analysis":{"intro":"This lab is aimed at demonstrating the use of Neighborhood Components Analysis (NCA) in learning a distance metric that maximizes the nearest neighbors classification accuracy. It provides a visual representation of this metric compared to the original point space.","steps":[{"title":"Generate Data Points","body":["We will start by generating a data set of 9 samples from 3 classes, and plot the points in the original space. For this example, we focus on the classification of point no. 3."],"code":[{"lang":"python","text":"import numpy as np\nimport matplotlib.pyplot as plt\nfrom sklearn.datasets import make_classification\nfrom sklearn.neighbors import NeighborhoodComponentsAnalysis\nfrom matplotlib import cm\nfrom scipy.special import logsumexp\n\nX, y = make_classification(\n    n_samples=9,\n    n_features=2,\n    n_informative=2,\n    n_redundant=0,\n    n_classes=3,\n    n_clusters_per_class=1,\n    class_sep=1.0,\n    random_state=0,\n)\n\nplt.figure(1)\nax = plt.gca()\nfor i in range(X.shape[0]):\n    ax.text(X[i, 0], X[i, 1], str(i), va=\"center\", ha=\"center\")\n    ax.scatter(X[i, 0], X[i, 1], s=300, c=cm.Set1(y[[i]]), alpha=0.4)\n\nax.set_title(\"Original points\")\nax.axes.get_xaxis().set_visible(False)\nax.axes.get_yaxis().set_visible(False)\nax.axis(\"equal\")  # so that boundaries are displayed correctly as circles"}]},{"title":"Visualize Neighbors","body":["We now visualize the links between the data points, with the thickness of a link between point no. 3 and another point being proportional to their distance."],"code":[{"lang":"python","text":"def link_thickness_i(X, i):\n    diff_embedded = X[i] - X\n    dist_embedded = np.einsum(\"ij,ij->i\", diff_embedded, diff_embedded)\n    dist_embedded[i] = np.inf\n\n    # compute exponentiated distances (use the log-sum-exp trick to\n    # avoid numerical instabilities\n    exp_dist_embedded = np.exp(-dist_embedded - logsumexp(-dist_embedded))\n    return exp_dist_embedded\n\n\ndef relate_point(X, i, ax):\n    pt_i = X[i]\n    for j, pt_j in enumerate(X):\n        thickness = link_thickness_i(X, i)\n        if i != j:\n            line = ([pt_i[0], pt_j[0]], [pt_i[1], pt_j[1]])\n            ax.plot(*line, c=cm.Set1(y[j]), linewidth=5 * thickness[j])\n\n\ni = 3\nrelate_point(X, i, ax)\nplt.show()"}]},{"title":"Learn an Embedding","body":["We will now use NCA to learn an embedding and plot the points after the transformation. We then take the embedding and find the nearest neighbors."],"code":[{"lang":"python","text":"nca = NeighborhoodComponentsAnalysis(max_iter=30, random_state=0)\nnca = nca.fit(X, y)\n\nplt.figure(2)\nax2 = plt.gca()\nX_embedded = nca.transform(X)\nrelate_point(X_embedded, i, ax2)\n\nfor i in range(len(X)):\n    ax2.text(X_embedded[i, 0], X_embedded[i, 1], str(i), va=\"center\", ha=\"center\")\n    ax2.scatter(X_embedded[i, 0], X_embedded[i, 1], s=300, c=cm.Set1(y[[i]]), alpha=0.4)\n\nax2.set_title(\"NCA embedding\")\nax2.axes.get_xaxis().set_visible(False)\nax2.axes.get_yaxis().set_visible(False)\nax2.axis(\"equal\")\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"nca = NeighborhoodComponentsAnalysis(max_iter=30, random_state=0)\nnca = nca.fit(X, y)\n\nplt.figure(2)\nax2 = plt.gca()\nX_embedded = nca.transform(X)\nrelate_point(X_embedded, i, ax2)\n\nfor i in range(len(X)):\n    ax2.text(X_embedded[i, 0], X_embedded[i, 1], str(i), va=\"center\", ha=\"center\")\n    ax2.scatter(X_embedded[i, 0], X_embedded[i, 1], s=300, c=cm.Set1(y[[i]]), alpha=0.4)\n\nax2.set_title(\"NCA embedding\")\nax2.axes.get_xaxis().set_visible(False)\nax2.axes.get_yaxis().set_visible(False)\nax2.axis(\"equal\")\nplt.show()"}],"source":"scikit-learn/scikit-learn · BSD 3-Clause"},"labex-sklearn-nearest-centroid-classification":{"intro":"This lab will guide you through the implementation of Nearest Centroid Classification using Scikit-learn. Nearest Centroid Classification is a simple classification method that works by computing the centroid for each class and then classifying new data points based on which centroid they are closest to.","steps":[{"title":"Import the Required Libraries","body":["First, we need to import the necessary libraries, which include Numpy, Matplotlib, Scikit-learn datasets, NearestCentroid, and DecisionBoundaryDisplay."],"code":[{"lang":"python","text":"import numpy as np\nimport matplotlib.pyplot as plt\nfrom matplotlib.colors import ListedColormap\nfrom sklearn import datasets\nfrom sklearn.neighbors import NearestCentroid\nfrom sklearn.inspection import DecisionBoundaryDisplay"}]},{"title":"Load the Data","body":["Next, we load the iris dataset from Scikit-learn and select only the first two features for visualization purposes."],"code":[{"lang":"python","text":"iris = datasets.load_iris()\nX = iris.data[:, :2]\ny = iris.target"}]},{"title":"Create Color Maps","body":["We create two color maps for visualization purposes using the ListedColormap function from Matplotlib."],"code":[{"lang":"python","text":"cmap_light = ListedColormap([\"orange\", \"cyan\", \"cornflowerblue\"])\ncmap_bold = ListedColormap([\"darkorange\", \"c\", \"darkblue\"])"}]},{"title":"Create and Fit the Classifier","body":["We create an instance of Nearest Centroid Classifier with a shrinkage value of 0.2 and fit the data."],"code":[{"lang":"python","text":"clf = NearestCentroid(shrink_threshold=0.2)\nclf.fit(X, y)"}]},{"title":"Predict and Measure Accuracy","body":["We predict the class labels for the input data and measure the accuracy of the classifier."],"code":[{"lang":"python","text":"y_pred = clf.predict(X)\nprint(\"Accuracy: \", np.mean(y == y_pred))"}]},{"title":"Visualize the Decision Boundaries","body":["Visualize the Decision Boundaries","We visualize the decision boundaries for the classifier using the DecisionBoundaryDisplay function from Scikit-learn."],"code":[{"lang":"python","text":"_, ax = plt.subplots()\nDecisionBoundaryDisplay.from_estimator(\n    clf, X, cmap=cmap_light, ax=ax, response_method=\"predict\"\n)"}]},{"title":"Plot the Data Points","body":["We plot the input data points using the scatter function from Matplotlib."],"code":[{"lang":"python","text":"plt.scatter(X[:, 0], X[:, 1], c=y, cmap=cmap_bold, edgecolor=\"k\", s=20)"}]},{"title":"Add Title and Axis Labels","body":["We add a title and axis labels to the plot using the title, xlabel, and ylabel functions from Matplotlib."],"code":[{"lang":"python","text":"plt.title(\"Nearest Centroid Classification\")\nplt.xlabel(\"Sepal length\")\nplt.ylabel(\"Sepal width\")"}]}],"commands":[],"reference":[],"source":"scikit-learn/scikit-learn · BSD 3-Clause"},"labex-sklearn-nested-cross-validation-for-model-selection":{"intro":"Nested cross-validation is a technique used to estimate the generalization error of a model and its hyperparameters. It is especially useful when choosing between different models or when hyperparameters need to be optimized. In this tutorial, we will compare non-nested and nested cross-validation on a support vector classifier model using the iris dataset. We will also visualize the difference in performance between the two methods.","steps":[{"title":"Load the Dataset","body":["The first step is to load the iris dataset from scikit-learn."],"code":[{"lang":"python","text":"from sklearn.datasets import load_iris\n\n# Load the dataset\niris = load_iris()\nX_iris = iris.data\ny_iris = iris.target"}]},{"title":"Define the Hyperparameters","body":["Next, we define the hyperparameters to be optimized for the support vector classifier. In this case, we optimize the cost parameter C and the kernel coefficient gamma."],"code":[{"lang":"python","text":"# Set up possible values of parameters to optimize over\np_grid = {\"C\": [1, 10, 100], \"gamma\": [0.01, 0.1]}"}]},{"title":"Define the Model","body":["We use a support vector classifier with a radial basis function kernel."],"code":[{"lang":"python","text":"from sklearn.svm import SVC\n\n# We will use a Support Vector Classifier with \"rbf\" kernel\nsvm = SVC(kernel=\"rbf\")"}]},{"title":"Non-Nested Cross-Validation","body":["We use non-nested cross-validation to tune the hyperparameters and evaluate the performance of the model. The GridSearchCV function performs an exhaustive search over specified parameter values for an estimator. We use a 4-fold cross-validation."],"code":[{"lang":"python","text":"from sklearn.model_selection import GridSearchCV\n\n# Non_nested parameter search and scoring\nclf = GridSearchCV(estimator=svm, param_grid=p_grid, cv=4)\nclf.fit(X_iris, y_iris)\nnon_nested_score = clf.best_score_"}]},{"title":"Nested Cross-Validation","body":["We use nested cross-validation to estimate the generalization error of the model and its hyperparameters. In the inner loop, we perform a grid search to find the best hyperparameters for each training set. In the outer loop, we evaluate the performance of the model on the test set."],"code":[{"lang":"python","text":"from sklearn.model_selection import KFold, cross_val_score\n\n# Number of random trials\nNUM_TRIALS = 30\n\n# Arrays to store scores\nnon_nested_scores = np.zeros(NUM_TRIALS)\nnested_scores = np.zeros(NUM_TRIALS)\n\n# Loop for each trial\nfor i in range(NUM_TRIALS):\n    # Choose cross-validation techniques for the inner and outer loops,\n    # independently of the dataset.\n    inner_cv = KFold(n_splits=4, shuffle=True, random_state=i)\n    outer_cv = KFold(n_splits=4, shuffle=True, random_state=i)\n\n    # Nested CV with parameter optimization\n    clf = GridSearchCV(estimator=svm, param_grid=p_grid, cv=inner_cv)\n    nested_score = cross_val_score(clf, X=X_iris, y=y_iris, cv=outer_cv)\n    nested_scores[i] = nested_score.mean()\n\nscore_difference = non_nested_score - nested_scores.mean()"}]},{"title":"Visualize the Results","body":["We visualize the results of the non-nested and nested cross-validation using a bar chart."],"code":[{"lang":"python","text":"from matplotlib import pyplot as plt\n\n# Plot bar chart of the difference.\nplt.bar([\"Non-Nested\", \"Nested\"], [non_nested_score, nested_scores.mean()])\nplt.ylim([0.9, 1.0])\nplt.ylabel(\"Score\")\nplt.title(\"Non-Nested and Nested Cross-Validation Scores\")\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"from matplotlib import pyplot as plt\n\n# Plot bar chart of the difference.\nplt.bar([\"Non-Nested\", \"Nested\"], [non_nested_score, nested_scores.mean()])\nplt.ylim([0.9, 1.0])\nplt.ylabel(\"Score\")\nplt.title(\"Non-Nested and Nested Cross-Validation Scores\")\nplt.show()"}],"source":"scikit-learn/scikit-learn · BSD 3-Clause"},"labex-sklearn-non-negative-least-squares-regression":{"intro":"In this lab, we will learn about Non-negative least squares regression, a type of linear regression that constrains the regression coefficients to be non-negative. We will use Python's scikit-learn library to implement this algorithm and compare it to the classic linear regression.","steps":[{"title":"Generate Random Data","body":["We will generate some random data to test our algorithm. We will create 200 samples with 50 features and use a true coefficient of 3 for each feature. We will then threshold coefficients to render them non-negative. Lastly, we will add some noise to the samples."],"code":[{"lang":"python","text":"import numpy as np\n\nnp.random.seed(42)\n\nn_samples, n_features = 200, 50\nX = np.random.randn(n_samples, n_features)\ntrue_coef = 3 * np.random.randn(n_features)\ntrue_coef[true_coef < 0] = 0\ny = np.dot(X, true_coef)\ny += 5 * np.random.normal(size=(n_samples,))"}]},{"title":"Split Data into Train and Test Sets","body":["Split Data into Train and Test Sets","We will split our data into a train set and a test set, with 50% of the data in each set."],"code":[{"lang":"python","text":"from sklearn.model_selection import train_test_split\n\nX_train, X_test, y_train, y_test = train_test_split(X, y, test_size=0.5)"}]},{"title":"Fit Non-Negative Least Squares Regression","body":["Fit Non-Negative Least Squares Regression","We will now fit our data using non-negative least squares regression. This is done using scikit-learn's LinearRegression class with the positive=True parameter. We will then predict the values for our test set and calculate the R2 score."],"code":[{"lang":"python","text":"from sklearn.linear_model import LinearRegression\nfrom sklearn.metrics import r2_score\n\nreg_nnls = LinearRegression(positive=True)\ny_pred_nnls = reg_nnls.fit(X_train, y_train).predict(X_test)\nr2_score_nnls = r2_score(y_test, y_pred_nnls)\nprint(\"NNLS R2 score\", r2_score_nnls)"}]},{"title":"Fit Classic Linear Regression","body":["We will now fit our data using classic linear regression. This is done using scikit-learn's LinearRegression class. We will then predict the values for our test set and calculate the R2 score."],"code":[{"lang":"python","text":"reg_ols = LinearRegression()\ny_pred_ols = reg_ols.fit(X_train, y_train).predict(X_test)\nr2_score_ols = r2_score(y_test, y_pred_ols)\nprint(\"OLS R2 score\", r2_score_ols)"}]},{"title":"Compare Regression Coefficients","body":["Compare Regression Coefficients","We will now compare the regression coefficients between non-negative least squares regression and classic linear regression. We will plot the coefficients against each other and observe that they are highly correlated. However, the non-negative constraint shrinks some coefficients to 0. This is because non-negative least squares inherently yield sparse results."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\n\nfig, ax = plt.subplots()\nax.plot(reg_ols.coef_, reg_nnls.coef_, linewidth=0, marker=\".\")\n\nlow_x, high_x = ax.get_xlim()\nlow_y, high_y = ax.get_ylim()\nlow = max(low_x, low_y)\nhigh = min(high_x, high_y)\nax.plot([low, high], [low, high], ls=\"--\", c=\".3\", alpha=0.5)\nax.set_xlabel(\"OLS regression coefficients\", fontweight=\"bold\")\nax.set_ylabel(\"NNLS regression coefficients\", fontweight=\"bold\")"}]}],"commands":[],"reference":[{"path":"reference.py","text":"import matplotlib.pyplot as plt\n\nfig, ax = plt.subplots()\nax.plot(reg_ols.coef_, reg_nnls.coef_, linewidth=0, marker=\".\")\n\nlow_x, high_x = ax.get_xlim()\nlow_y, high_y = ax.get_ylim()\nlow = max(low_x, low_y)\nhigh = min(high_x, high_y)\nax.plot([low, high], [low, high], ls=\"--\", c=\".3\", alpha=0.5)\nax.set_xlabel(\"OLS regression coefficients\", fontweight=\"bold\")\nax.set_ylabel(\"NNLS regression coefficients\", fontweight=\"bold\")"}],"source":"scikit-learn/scikit-learn · BSD 3-Clause"},"labex-sklearn-linear-regression-example":{"intro":"This lab demonstrates how to use linear regression to draw a straight line that best fits a dataset and how to calculate the coefficients, residual sum of squares, and coefficient of determination. We will be using the scikit-learn library to perform linear regression on the diabetes dataset.","steps":[{"title":"Load the Diabetes Dataset","body":["We start by loading the diabetes dataset from scikit-learn and only selecting one feature from the dataset."],"code":[{"lang":"python","text":"import numpy as np\nfrom sklearn import datasets\n\n# Load the diabetes dataset\ndiabetes_X, diabetes_y = datasets.load_diabetes(return_X_y=True)\n\n# Use only one feature\ndiabetes_X = diabetes_X[:, np.newaxis, 2]"}]},{"title":"Split the Dataset","body":["Next, we split the dataset into training and testing sets. We will use 80% of the data for training and 20% for testing."],"code":[{"lang":"python","text":"# Split the data into training/testing sets\ndiabetes_X_train = diabetes_X[:-20]\ndiabetes_X_test = diabetes_X[-20:]\n\n# Split the targets into training/testing sets\ndiabetes_y_train = diabetes_y[:-20]\ndiabetes_y_test = diabetes_y[-20:]"}]},{"title":"Train the Model","body":["Now, we create a linear regression object and train the model using the training sets."],"code":[{"lang":"python","text":"from sklearn import linear_model\n\n# Create linear regression object\nregr = linear_model.LinearRegression()\n\n# Train the model using the training sets\nregr.fit(diabetes_X_train, diabetes_y_train)"}]},{"title":"Make Predictions","body":["We can now use the trained model to make predictions on the testing set."],"code":[{"lang":"python","text":"# Make predictions using the testing set\ndiabetes_y_pred = regr.predict(diabetes_X_test)"}]},{"title":"Calculate Metrics","body":["We can calculate the coefficients, mean squared error, and coefficient of determination."],"code":[{"lang":"python","text":"from sklearn.metrics import mean_squared_error, r2_score\n\n# The coefficients\nprint(\"Coefficients: \\n\", regr.coef_)\n\n# The mean squared error\nprint(\"Mean squared error: %.2f\"\n      % mean_squared_error(diabetes_y_test, diabetes_y_pred))\n\n# The coefficient of determination: 1 is perfect prediction\nprint(\"Coefficient of determination: %.2f\"\n      % r2_score(diabetes_y_test, diabetes_y_pred))"}]},{"title":"Visualize the Results","body":["Finally, we can plot the predicted values against the actual values to visualize how well the model fits the data."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\n\n# Plot outputs\nplt.scatter(diabetes_X_test, diabetes_y_test, color=\"black\")\nplt.plot(diabetes_X_test, diabetes_y_pred, color=\"blue\", linewidth=3)\n\nplt.xticks(())\nplt.yticks(())\n\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"import matplotlib.pyplot as plt\n\n# Plot outputs\nplt.scatter(diabetes_X_test, diabetes_y_test, color=\"black\")\nplt.plot(diabetes_X_test, diabetes_y_pred, color=\"blue\", linewidth=3)\n\nplt.xticks(())\nplt.yticks(())\n\nplt.show()"}],"source":"scikit-learn/scikit-learn · BSD 3-Clause"}};
